window.__D("text/pelach-harimon/c004",{"p":[[4801940289,"לומר קדוש כו' ולהתבטל במס\"נ כו', ולכן אע\"פ שהכלים דע\"ס נק' בשם גופים במאמר פתח אלי'<sup data-n=\"3151\">31</sup> מצד שאין ערוך להם לגבי א\"ס הפשוט דלאו מכל אינון מדות כלל, מ\"מ מתייחד בהם ומתגלה ע\"י בבחי' גילוי גמור כנ\"ל, משא\"כ בבחי' ע\"ס דבריאה המה כדוגמת הלבושים שאינם מגלים רק קצת החיות וגם יכול לפשטו כו', כן ע\"י ע\"ס דבריאה אינו מתגלה רק הארה בעלמא בעולמות ומלאכים שהוא בחי' ביטול מצד ההשגה ומדות שלמטה הרבה מבחי' מס\"נ וגם יכול להיות בחי' הסתלקות אלקות ח\"ו משא\"כ באצילות לא שניתי<sup data-n=\"3152\">32</sup> כתיב [זולת בבחי' תוס' אור שנמשך יתר מכפי המדה בזה יכול להיות תוס' וגרעון מצד מעה\"ת כו' וד\"ל] [... אך כ\"ז הוא בבחי' חיצוני' ואמצעי' הכלים די\"ס דבי\"ע שהמה מלאכים נבראים מאין ליש אבל בחי' האורות ופנימי' הכלים די\"ס דבי\"ע הם ג\"כ בבחי' אלקות ממש מתייחדים ומגלים אור בגילוי גמור כנ\"ל בי\"ס דאצי' כו', וזהו בחי' פני אדם לארבעתן<sup data-n=\"3153\">33</sup> כו']. ומזה הטעם הנשמות נק' בשם אדם להיות כי עיקרי' הנשמה היא בחי' אצי' בחי' ביטול ומס\"נ שלמעלה מהשגה וכמאמר טהורה היא<sup data-n=\"3154\">34</sup> ומה שנמצא השגה ומדות בנשמה מצד נר\"ן דבי\"ע אינם רק לבושי הנשמה ולכן נק' בשם אדם בחי' מ\"ה ביטול בתכלית וגילוי כ\"ז א\"א להתגלות רק ע\"י י\"ס דאצי' כנ\"ל, אבל המלאכים נק' בשם חיות ובהמות<sup data-n=\"3155\">35</sup> כי בהמה בגי' ב\"ן שהוא בחי' יש להיות כי עיקר שרשם נמשך מבחי' מל' דאצי' הנמשכת בבחי' הסתר בחיצוני' הכלים דבי\"ע שנק' בשם יש ע\"ש פעולתו להוות יש ונק' כבוד<sup data-n=\"3156\">36</sup> נברא<sup data-n=\"3157\">37</sup> ג\"כ ע\"ש פעולתו להוות הנברא כמ\"ש במ\"א, אע\"פ שבאמת הוא בחי' אלקות ולכן הגילוי שמתגלה מזאת הבחי' הוא בחי' יש, וגם שמתגלה אא\"ס ע\"י בחי' זאת נק' ביטול היש בלבד הארה מועטת כמו ע\"י הלבושים ולכן נק' בשם חיות ובהמות כו' וד\"ל.\n<b>והנה</b> בחי' המרכבה דמלאכי' מתחלקים בכלל לד' מחנות פני ארי' להימין הוא בחי' מחנה מיכאל<sup data-n=\"3158\">38</sup> שהמזיגה שלהם הוא בד\"כ בחי' אהבה ומתחלק בפרט לכמה מיני מזיגות שונות ק\"פ אלף<sup data-n=\"3159\">39</sup> וכן מחנה גבריאל ביראה מתחלק ג\"כ לכמה מיני מזיגות שונות וכן כל הד' מדריגות והם באים בהשתלשלות עד למטה בעולם העשי' הגשמי ד' רוחות העולם דרום הוא מזיגה אחרת וצפון הוא מזיגה אחרת כו', וכן ד' מדריגות דדצח\"מ כ\"א הוא מזיגה אחרת בד\"כ ובפרט כ\"א מתחלק לכמה מיני מזיגות שונות, אך כ\"ז הוא עצם הבריאה שלהם מאין ליש שאינם בבחי' ביטול אמיתי רק ביטול היש ולכן יש בהם קצת בחי' יש במה שהמה מקור להשפיע בהשתלשלות עד",[["3151","31","<b>במאמר פתח אלי'</b>: ת\"ז בהקדמה יז, א."],["3152","32","<b>לא שניתי</b>: מלאכי ג, ו."],["3153","33","<b>פני אדם לארבעתן</b>: ראה יחזקאל א, י. מאמרי אדה\"א בראשית ע' קנו. וש\"נ. תו\"ח שמות ח\"א כח, א. וש\"נ."],["3154","34","<b>טהורה היא</b>: ברכת אלקי נשמה."],["3155","35","<b>המלאכים. . חיות ובהמות</b>: יחזקאל א, י. ראה גם לעיל ע' ד. וש\"נ."],["3156","36","<b>מל'. . כבוד נברא</b>: ראה מאמרי אדה\"א דרושי חתונה ח\"א ע' ב ואילך."],["3157","37","<b>כבוד נברא</b>: ראה ת\"ז בהקדמה ה, א. ו, ב. לקמן מאמר ד\"ה בסוכות תשבו תרכ\"ב הערה 83."],["3158","38","<b>פני ארי' להימין. . מיכאל</b>: ראה יחזקאל א, י. זהר בהעלותך קנד, א."],["3159","39","<b>מחנה מיכאל. . ק\"פ אלף</b>: ראה זהר בהעלותך שם. לעיל מאמר ד\"ה וספרתם תקצ\"ח ובהערה 79."]]],[4801940339,"למטה מטה בד' רוחות העולם ודצח\"מ כנ\"ל, אך באמת יש להם ג\"כ בחי' כנפים אע\"פ שנק' בשם חיות ובהמות וכידוע מארז\"ל ע\"פ ועוף יעופף ועוף זה מיכאל יעופף זה גבריאל<sup data-n=\"3160\">40</sup>, והוא מש\"א ובשתים יעופף<sup data-n=\"3161\">41</sup> בבחי' רו\"ש. והענין הוא ע\"ד שמצינו בעופות השמים שמעופפים בכנפיהם כלפי מעלה ברוממות השמים ועיקר פריחה שלו הוא אל מקום מחוז חפצו ותשוקתו דייקא והיינו ע\"י שמנדנד בכנפיו אנה ואנה ע\"י נתרומם גופו ובא אל מחוז חפצו כו', כן נאמר במלאכים שבמרכבה בוערות כמראה הלפידים<sup data-n=\"3162\">42</sup> והוא ענין תוקף רשפי אש התשוקה באהבה או ביראה שהוא כמו השלהבת העולה למעלה מעלה כן בכחם ויכולתם לצאת מגדרי הכלים שלהם שהוא בחי' הרצוא שלהם שהוא בחי' אהבה ותשוקה נפלאה ליכלל בבחי' סוכ\"ע המקיף שהוא קדוש ומובדל מהם בתכלית וזהו מש\"א קדוש ואח\"כ נעשה בחי' שוב שהוא בחי' רוממות יותר נעלה עד שמה שהאיר מתחילה בבחי' מקיף עליהם נמשך אח\"כ אצלם בבחי' פנימי וממילא נמשכים מקיפים חדשים שהוא בחי' רצוא יותר נעלה ואח\"כ נמשך גם זה בבחי' שוב ועד\"ז מתרוממים בעילוי אחר עילוי כו', והוא כמו העוף הפורש כנפיו למעלה מגופו ואח\"כ כשינוח בכנפיו אצל גופו מתרומם גופו יותר כו'.\n<b>והנה</b> אע\"פ שבחי' כנפיהם הוא בחי' היציאה מגדרי הכלים שלהם מ\"מ גם הם פרודות כי אע\"פ שפנימי' רצונם הוא לצאת מגדרי הכלי שלהם מ\"מ הוא מלובש בבחי' לבושם כמו שנבראו מאין ליש כמו עד\"מ מיכאל ששרשו בחי' חסד<sup data-n=\"3163\">43</sup> מחמת זה מהותו הוא בחי' אהבה כן השאגה לצאת מגדרי הכלי ליכלל וליבטל הוא ג\"כ עלי' בבחי' אהבה ותשוקה כי הרצוא הוא ג\"כ מהות תשוקה רק שהוא התגברות התשוקה עד שלא יכילנה הכלי, ולכן נק' בלה\"ק בשם שאגה שהוא ענין צעקה בהתגלות להיות בפני ארי' הרצוא ותשוקה הוא בהתגלות והשוב הוא בהעלם שמקבל מבחי' חסד עליון דאצי' שפועל גילוי אא\"ס והגילוי שלמעלה פועל רצוא במקבל כענין משכני אחריך נרוצה<sup data-n=\"3164\">44</sup> וכן בנש\"י מצד חומר<sup data-n=\"3165\">45</sup> גופם שמקבלי' מבחי' המלאכים דפני ארי' [משא\"כ מצד שרש נשמתם הם גבוהים הרבה ממנו כי הם בבחי' אדם שעל הכסא] נאמר בהם אחרי הוי' ילכו כארי' ישאג כארי' שבמרכבה כו', וכן מחנה גבריאל אשר מהותו הוא בחי' יראה מצד ששרשו בחי' גבורות וכן<sup data-n=\"3166\">46</sup> גם היציאה שלהם מגדרי הכלי שהוא הרצוא שבו הוא מלובש בבחי' יראה ופחד ואין הרצוא בהתגלות כ\"כ ונק' זעים מחיל כסא<sup data-n=\"3167\">47</sup> כמו עד\"מ זעזוע הגוף שבא מצד תוקף האימה וסילוק הדמים ואח\"כ בבחי' השוב נופל זיעה ומזיעתן נעשה נה\"ד<sup data-n=\"3168\">48</sup> על ראש רשעים יחול<sup data-n=\"3169\">49</sup> כי מצד השגתם בגדולת א\"ס נעשה בהם תוקף הביטול ביראה וממילא נמשך",[["3160","40","<b>ועוף יעופף. . מיכאל. . גבריאל</b>: בראשית א, כ. ראה זהר בראשית מו, ב. מאמרי אדה\"א קונטרסים ע' שעו. וש\"נ. תו\"ח בראשית יט, א ובהערה 5."],["3161","41","<b>ובשתים יעופף</b>: ישעי' ו, ב."],["3162","42","<b>בוערות כמראה הלפידים</b>: יחזקאל א, יג."],["3163","43","<b>מיכאל. . חסד</b>: ראה ת\"ז ת\"ע קכו, א. קכז, א. שו\"ע אדה\"ז הל' תפלה סק\"כ, ס\"ב."],["3164","44","<b>משכני אחריך נרוצה</b>: שה\"ש א, ד."],["3165","45","<b>חומר</b>: אולי כ\"ה בגוכת\"י."],["3166","46","<b>וכן</b>: אולי כתוב: ולכן."],["3167","47","<b>זעים מחיל כסא</b>: ראה פיוט והחיות ב(נוסח הקדושה אשכנז) מוסף לר\"ה."],["3168","48","<b>ומזיעתן נעשה נה\"ד</b>: ראה חגיגה יג, סע\"ב."],["3169","49","<b>על ראש רשעים יחול</b>: ירמי' כג, יט. ל, כג."]]],[4801940386,"הרוגז על עוברי רצונו כו', ולכן בלה\"ק הצעקה דשור נק' גועה נעלמת קצת, ופני נשר הוא מדה ממוצעת בין אוי\"ר והיינו אע\"פ שהוא אינו ראוי לחסד וקירוב מצד שפלותו מ\"מ מצד הרחמים<sup data-n=\"3170\">50</sup> ראוי לקרבו כן במרכבה ע\"י פני נשר הוא מרומם כל מדריגות השפלות ביותר אפי' בתחתי' עולם העשי' להגביהם למעלה להיות בהם גילוי אלקות כמו עושה משפט לעשוקים<sup data-n=\"3171\">51</sup> לניצוצות שנעשקו בתחתיות הקליפה וע\"י המשפט דאיהו רחמי<sup data-n=\"3172\">52</sup> מצילם וכן משפט לאלקי יעקב<sup data-n=\"3173\">53</sup> שהם נשמות שפלים, י' עקב<sup data-n=\"3174\">54</sup> כו'. וכן ועלו מושיעים לשפוט את הר עשו<sup data-n=\"3175\">55</sup> הניצוצו' שנפלו שמה כו', וזהו ואשא אתכם על כנפי נשרים<sup data-n=\"3176\">56</sup> ואביא אתכם אלי שבמצרים היו נש\"י בתכלית השפלות משועבדים בגופם בעבודה בחומר ובלבנים ולא הי' ראוי' לקבלת התורה פב\"פ דבר הוי'<sup data-n=\"3177\">57</sup> רק ע\"י כנפי נשרים שהוא מדה\"ר נתרוממו לתכלית העילוי דמ\"ת וגם בזה יש תוקף הרחמנות לצאת מגדרי הכלי שהוא מצד הרגשת אא\"ס המקיף כמ\"ש דרך הנשר בשמים<sup data-n=\"3178\">58</sup> מחמת זה מרגיש השפלות בעצמו ועי\"ז נעשה התגברות לצאת מגדרי הכלי ליכלל בבחי' המקיף כו', וכן פני אדם שבמרכבה שהוא בחי' הביטול במעשה יש בזה ג\"כ תוקף הביטול עד שאינו יכול לעשות, אך מחמת השוב בא למעשה כו' [... והנה באמת כל אחד כלול מכולם ולכן נאמר וארבע כנפים לאחת<sup data-n=\"3179\">59</sup> כו' כידוע דכלילין דא בדא ושלובין<sup data-n=\"3180\">60</sup> כו', אך עיקר שרש הכנפים הוא בחי' פני נשר שבכאו\"א כי ארבעה פנים לאחת<sup data-n=\"3181\">61</sup> וכ\"א מהפנים כלול מכולם ולכן מבחי' פני נשר שבכל פן הוא בחי' הכנף ולכן ארבע כנפים לאחת מצד שארבעה פנים לאחת ומצד פני אדם שבכאו\"א נאמר וידי אדם תחת כנפיהם<sup data-n=\"3182\">62</sup> כנלע\"ד בדרך אפשר].\n<b>והנה</b> א' וכנפיהם פרודות מלמעלה, היינו ששרש זה הפירוד נמשך מלמעלה, מפני קבלתם מלמעלה כח האלקי השופע עליהם בבחי' התחלקות בשיעור ומדה בכאו\"א לפי ערכו והיינו מצד שבשרשם ומקורם האלקי יש לכאו\"א שרש מיוחד בפ\"ע ולזה כאשר באים מהעלם אל הגילוי המה באים בבחי' ריבוי והתחלקות. והענין הוא ע\"ד דוגמא למטה בהבל הלב שהוא פשוט ורוחני וגם אחר שנתצמצם במיצר הגרון נתגשם קצת ונעשה קול מורגש מ\"מ הוא קול פשוט רק בעברו דרך ה'",[["3170","50","<b>נשר. . הרחמים</b>: ראה ירושלמי פאה פ\"א, ה\"א. תנחומא עקב ב. לקו\"ת האזינו עז, ג. עח, א ואילך. מאמרי אדה\"א דברים ח\"ג ע' תתעט. וש\"נ. תו\"ח בשלח ח\"א ריג, ב ובהערה 213."],["3171","51","<b>עושה משפט לעשוקים</b>: תהלים קמו, ז. ראה סידור שחרית נז, ד."],["3172","52","<b>המשפט דאיהו רחמי</b>: ראה ת\"ז בהקדמה יז, ב. מאמרי אדה\"א דברים ח\"א ע' קח. וש\"נ."],["3173","53","<b>משפט לאלקי יעקב</b>: תהלים פא, ה."],["3174","54","<b>יעקב. . י' עקב</b>: ע\"ח שער סדר אצי' ש\"ג, פ\"ב. ראה מאמרי אדה\"א דברים ח\"ג ע' תתמז. וש\"נ. תו\"ח שמות ח\"א יח, ב. וש\"נ."],["3175","55","<b>ועלו מושיעים לשפוט את הר עשו</b>: עובדי' בסופו [בדילוג]. ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'תצז."],["3176","56","<b>ואשא אתכם על כנפי נשרים</b>: יתרו יט, ד."],["3177","57","<b>פב\"פ דבר הוי'</b>: ואתחנן ה, ד."],["3178","58","<b>דרך הנשר בשמים</b>: משלי ל, יט."],["3179","59","<b>וארבע כנפים לאחת</b>: יחזקאל א, ו."],["3180","60","<b>דכלילין דא בדא ושלובין</b>: ראה זהר תרומה קעא, א. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תשמו."],["3181","61","<b>ארבעה פנים לאחת</b>: המשך הכתוב וארבע כנפים."],["3182","62","<b>וידי אדם תחת כנפיהם</b>: יחזקאל א, כח [ושם: מתחת]."]]],[4801940430,"מוצאות הפה נתחלק לאותיות מחולקים אחה\"ע מהגרון<sup data-n=\"3183\">63</sup> גיכ\"ק מהחיך בומ\"ף מהשפתים כו' כמ\"כ למעלה כתיב בדבר ה' שמים נעשו<sup data-n=\"3184\">64</sup> שהבל לב העליון הוא אור אלקי פשוט וע\"י צמצום שבחזה דז\"א נעשה בנין כתר מל' שהוא ע\"ד קול פשוט המורגש כו', ואח\"כ נמשכים ה' גבורות שמזה הוא בנין המל'<sup data-n=\"3185\">65</sup> מחכמה ולמטה שזהו ענין ה' מוצאות הפה דמל' [... כי השפתים הם בחי' נו\"ה<sup data-n=\"3186\">66</sup> השייכים לבחי' מל' דמל' והשיניים הם בגבו'<sup data-n=\"3187\">67</sup> דמל' לכן בטבעם לפרר כמו טבע הגבורה לפרר והלשון הוא ת\"ת<sup data-n=\"3188\">68</sup> שבמל' והחיך הוא חסד שבמל' והגרון הוא בינה<sup data-n=\"3189\">69</sup> מקור המדות כו' ולכן שם גם משכן קול הכללי המקור לכל האותיות כנלע\"ד בדרך אפשר]. והנה מצד שבבחי' המל' שהוא מקור הנבראים מאין ליש יש בחי' ריבוי והתחלקות בהעלם לכן גם בבחי' גילוי של הנבראים נמשך ד' מחנות שכינה<sup data-n=\"3190\">70</sup> כפי המספר שבהעלם, אך א\"כ למה לא נברא ה' מחנות כמספר המוצאות, אך הענין הוא דמוצא החמישי שהוא מוצא החיך אע\"פ שגם הוא מקור לאותיות מחולקים גיכ\"ק מ\"מ יש בו עוד בחי' א' שהוא המקור הכוללם יחד וממנו יתחלקו כולם בשיעור ומדה ולכן אינו בא בכלל הד' מוצאות הנמשכים לנבראים כי הוא הכלל הכולל שטבעו לישאר בהעלם כו' וד\"ל. והטעם לזה הנה אנו רואים שיש בו עוד כח אחד להרגיש כל מיני טעמים עריבות ומתיקות או חמיצות כמ\"ש וחיך יטעם אוכל<sup data-n=\"3191\">71</sup> והיינו מפני ששרשו בחכ\"ע שבה מלובש מבחי' התענוג העליון ולכן בכחו להרגיש ג\"כ הטעם והעונג כו', והנה ידוע דחכ\"ע הוא מקור כל צי\"א כידוע דאבא יסד ברתא<sup data-n=\"3192\">72</sup> לכן בחי' החיך שהוא חכ'<sup data-n=\"3193\">73</sup> שבמל' שמקבל מחכמה עילאה [... כידוע בענין חכ' בראש וחכמה בסוף<sup data-n=\"3194\">74</sup> ונעוץ תחילתן בסופן<sup data-n=\"3195\">75</sup> כו'] הוא המקור הכולל לכל המוצאות ולכן לא נברא ממנו מחנה פרטיות כנ\"ל [... וע\"כ לומר שגם האותיות היוצאים ממנו הם כלליים ולא פרטיים ולכן לא נברא מהם מציאות נברא פרטי כו' וצ\"ע]<sup data-n=\"3196\">76</sup>.",[["3183","63","<b>אחה\"ע מהגרון</b>: ס\"י פ\"ב, מ\"ג. ראה הנסמן במאמרי אדה\"א דברים ח\"א ע' קה."],["3184","64","<b>בדבר ה' שמים נעשו</b>: תהלים לג, ו."],["3185","65","<b>ה' גבורות. . בנין המל'</b>: ראה גם לקמן מאמר ד\"ה וספרתם הה' על יד הערה 17."],["3186","66","<b>השפתים הם בחי' נו\"ה</b>: ראה זהר רע\"מ פינחס רנ, א. מאו\"א מערכת שפה סס\"ו."],["3187","67","<b>והשיניים הם בגבו'</b>: ראה ע\"ח שער דרושי הצלם שכ\"ה דרוש ב."],["3188","68","<b>והלשון הוא ת\"ת</b>: ראה ע\"ח שם."],["3189","69","<b>והגרון הוא בינה</b>: ראה ע\"ח שער העיבורים שכ\"ח, פ\"ה. שער מ\"ן ומ\"ד של\"ט, דרוש ט. דרוש יד ובהגה שם. שער הולדת או\"א וזו\"ן שט\"ז, פ\"א."],["3190","70","<b>ד' מחנות שכינה</b>: זהר במדבר קיח, ב."],["3191","71","<b>וחיך יטעם אוכל</b>: איוב יב, יא [ושם: אוכל יטעם]. לד, ג [ושם: יטעם לאכל]. ראה מאמרי אדה\"א דברים ח\"ב ע' תרפב. וש\"נ. שה\"א ט, א הערה 1."],["3192","72","<b>דאבא יסד ברתא</b>: ראה זהר רע\"מ פינחס רנו, ב. רמח, א. רנח, א. אגה\"ק ס\"ה. מאמרי אדה\"א דברים ח\"ב ע' שפ הערה ד\"ה מצירופי. קונטרסים ס\"ע תקמז ואילך. תו\"ח שמות ח\"א יב, א."],["3193","73","<b>החיך שהוא חכ'</b>: ראה פרדס שער עה\"כ שכ\"ג, פ\"ח מערכת חיך. ע\"ח שער מ\"ן ומ\"ד של\"ט, דרוש ט."],["3194","74","<b>חכ' בראש וחכ' בסוף</b>: ראה זהר בראשית כו, ב. שעה\"י קמג, א הערה 8."],["3195","75","<b>ונעוץ תחילתן בסופן</b>: ראה ס\"י פ\"א, מ\"ז. סה\"מ תר\"ל ע' שכ."],["3196","76","<b>וצ\"ע]</b>: ע\"כ נכתב בגוכת\"י."]]],[4801940116,"<b>בעזה\"י</b>\n<b>וספרתם</b> לכם<sup data-n=\"3197\">1</sup> ממחרת השבת מיום הביאכם את עומר התנופה שבע שבתות כו' תספרו חמשים יום<sup data-n=\"3198\">2</sup>. ויש להבין בכלל ענין ספה\"ע אחר הקרבת עומר שעורים דוקא, שהוא ממחרת השבת דוקא שארז\"ל ע\"ז שהוא מחרת יו\"ט הראשון של פסח<sup data-n=\"3199\">3</sup>, שאז הי' אכילת מצה ויצי\"מ כו', ואח\"ז דוקא מתחיל ענין ספה\"ע. וגם להבין ענין תנופת העומר כמ\"ש והניף את העומר<sup data-n=\"3200\">4</sup> לפני הוי' לרצונכם ממחרת השבת יניפנו הכהן כו', מהו ענין התנופה מתחלה, וגם הלא ידוע בשם הבעש\"ט נ\"ע שהתורה היא נצחית<sup data-n=\"3201\">5</sup>, ומה שהי' מקודם בגשמיות בזמן הבית עכשיו הוא ברוחניות כו' וא\"כ מהו ענינו בעבודה שקודם ספה\"ע צ\"ל ענין התנופה. וגם עצם ענין הלשון שמתחיל והניף את העומר ל' יחיד דקאי על הכהן ומסיים לרצונכם ל' רבים כו'. וגם להבין ענין הידוע שבחי' ספה\"ע הוא בחי' ממוצע מיצי\"מ לבוא לבחי' מתן תורה, וגילוי בחי' אנכי כו'. והנה מתחלה יש להקדים ענין שבתיבת וספרתם יש בו ג' פי' הא' לשון מספר והב' ל' זיכוך ובירור כמו אבן ספיר<sup data-n=\"3202\">6</sup> ופי' הג' וספרתם לכם שתמשיכו לכם להיות בגדר קדושת הספי'<sup data-n=\"3203\">7</sup> כו'.\n<b>ולהבין</b> כל הנ\"ל יש להקדים ענין הידוע על עומר שעורים, כי שעורים הוא מאכל בהמה<sup data-n=\"3204\">8</sup>, ובשרש קאי על בחי' מל' דאצי' שנק' בשם בהמה רבה<sup data-n=\"3205\">9</sup> כי בהמה בגימט' ב\"ן<sup data-n=\"3206\">10</sup> ושם ב\"ן הוא בבחי' מל'<sup data-n=\"3207\">11</sup> כידוע בספרי המקובלים, ושעורה הצירוף הוא שיעור ה'<sup data-n=\"3208\">12</sup> כמ\"ש במקובלים, כי בחי' ה' תתאה הוא בחי' מל'<sup data-n=\"3209\">13</sup> כו', ועיקר בנינה הוא מהגבורות<sup data-n=\"3210\">14</sup> כו', וזהו שיעור ה' שההמשכה הוא ע\"י שיעורים וצמצומים כו', רק שבענין שיעור ה' יש בו ב' פי' הא' שהשיעור הוא שיתגלה בחי' הה\"א שהוא בחי' המל', ופי' הב' הוא שגם כשיומשך מבחי' הה\"א למטה בבחי'",[["3197","1","<b>וספרתם לכם</b>: מאמר זה הוא כנראה דרוש ר\"ה.\nלמאמר זה ראה לקו\"ת אמור מאמר ד\"ה זה לה, ב."],["3198","2","<b>וספרתם לכם. . חמשים יום</b>: אמור כג, טו."],["3199","3","<b>ממחרת השבת. . יו\"ט הראשון של פסח</b>: תו\"כ אמור שם. מנחות סה, ב."],["3200","4","<b>והניף את העומר</b>: אמור שם, יא."],["3201","5","<b>בשם הבעש\"ט נ\"ע שהתורה היא נצחית</b>: ראה גם תניא פי\"ז. תו\"ח שמות ח\"א א, א. וש\"נ."],["3202","6","<b>וספרתם. . זיכוך. . אבן ספיר</b>: ראה גם ערכי הכנויים לבעל סדה\"ד מערכת ספיר [ספירה]. לקו\"ת אמור כאן לה, ב. לעיל מאמר ד\"ה וספרתם תקצ\"ח בתחלתו."],["3203","7","<b>וספרתם לכם. . בגדר קדושת הספי'</b>: לקמן בהמאמר מציין ללקו\"ת — אמור לו, ב. ראה גם רד\"ה וספרתם תקצ\"ח."],["3204","8","<b>שעורים הוא מאכל בהמה</b>: ראה מל\"א ה, ח. פסחים ג, סע\"ב. סוטה יד, א (במשנה)."],["3205","9","<b>בהמה רבה</b>: ראה תניא ספמ\"ו. לקו\"ת אמור לו, א. תו\"ח בראשית טז, ג ובהערה 26."],["3206","10","<b>בהמה בגימט' ב\"ן</b>: ראה תניא שם. מאמרי אדה\"א ויקרא ח\"א ע' ד. וש\"נ."],["3207","11","<b>ב\"ן. . מל'</b>: ראה ע\"ח שער רפ\"ח ניצוצין שי\"ח, פ\"ג. שעה\"י קמה, א הערה 14."],["3208","12","<b>ושעורה. . שיעור ה'</b>: זהר בלק קפח, ב. ראה גם לקמן מאמר ד\"ה בסוכות תשבו תרכ\"ב הערה 38."],["3209","13","<b>ה' תתאה. . מל'</b>: ראה זהר ויקרא יז, א. תו\"ח ויצא קסז, ג הערה 38."],["3210","14","<b>מל'. . בנינה הוא מהגבורות</b>: ראה ע\"ח שער תיקון הנוקבא של\"ד, פ\"ה. מאמרי אדה\"א דברים ח\"א ע' ריח. וש\"נ. תו\"ח בשלח ח\"א רמד, א. וש\"נ."]]],[4801940180,"ההשתל' וכמ\"ש בהבראם ומאחז\"ל ע\"ז בה' בראם<sup data-n=\"3211\">15</sup> כו', שאות הה\"א הוא אות זעירא<sup data-n=\"3212\">16</sup> שמורה ג\"כ על קטנות וצמצום כו' כידוע, הוא ג\"כ ע\"י שיעור וצמצום כו', וכידוע הענין בכהאריז\"ל שיש בבחי' מל' ב' מיני גבורות, ה' גבורות לצורך עצמה, ובחי' ה\"ג לצורך בנינה<sup data-n=\"3213\">17</sup> שהוא בחי' המשכה להשתל' כו' כמו שיבואר.\n<b>וביאור</b> הענין הלא ידוע כי מקור ההשתל' מתחיל מבחי' המדות דאצי' וכמ\"ש בזוהר ששת ימים ולא כתיב בששת<sup data-n=\"3214\">18</sup>, שית יומין עלאין דבהון עביד קוב\"ה שמיא וארעא וכמ\"ש כי אמרתי עולם חסד יבנה<sup data-n=\"3215\">19</sup> כו', אבל בחי' חו\"ג<sup data-n=\"3216\">20</sup> עלאין<sup data-n=\"3217\">21</sup> הם למעלה ממקור ההשתל', כידוע על ענין קדמה לעולם אלפים שנה<sup data-n=\"3218\">22</sup> כו' ולכן נק' במקובלים בחי' המדות אור המאיר לזולתו, אבל בחי' חו\"ב נק' אור המאיר לעצמו כו', וע\"ד דוגמא למטה מבשרי אחזה<sup data-n=\"3219\">23</sup> שמציאות המדות הם שייכים לזולתו דוקא להטיב לזולתו ולרחק לזולתו כו', אבל מציאת חו\"ב העיקר הוא להשכיל השכלות עמוקות לעצמו<sup data-n=\"3220\">24</sup> ורק הארה בעלמא נמשך מעצם המוחי' בהמדות היינו איך להתנהג במדותיו כו', אך הלא ידוע מה שמבואר בתניא שאם הי' בחי' ההשתל' מעצם המדות<sup data-n=\"3221\">25</sup> אפי' אם הי' בחי' ריבוי ההשתל' הי' כל הנבראים בטלים במקורם בבחי' ביטול העלול בעילתו כביטול זיו השמש בשמש שהוא שם בבחי' אין ואפס, ולא הי' יכול להתהוות בחי' יש נברא שהוא מסתיר ומעלים לגמרי על בחי' אין אלקי השופע בו, ובחי' נפרד, וכמ\"ש ומשם יפרד<sup data-n=\"3222\">26</sup> כו', אלא דוקא מצד בחי' המל' שבנינה מהגבו' והן הן גבורותיו<sup data-n=\"3223\">27</sup> להסתיר ולהעלים א\"ע שיוכל להתהוות בחי' עולמות בי\"ע כו' וכמ\"ש מלכותך מכ\"ע<sup data-n=\"3224\">28</sup> כו'.\n<b>וביאור</b> הענין יובן ע\"ד דוגמא מבחי' זיו השמש שמאיר לארץ ולדרים עליה, שיש בכח האור להשפיע כמה כחות גשמיי' כמו להשפיע אור בחלונות",[["3211","15","<b>בהבראם. . בה' בראם</b>: ראה מנחות כט, ב. ב\"ר פי\"ב, ב. וראה גם לקמן מאמר ד\"ה וזכרתי הר\"ת על יד הערה 24 ואילך."],["3212","16","<b>בהבראם. . הה\"א הוא אות זעירא</b>: ראה זהר לך צג, א. אנציק' תלמודית מערכת ה כרך ח ע' לה הערה 121. וראה גם אוה\"ת בראשית כרך ג ע' 1030 ספ\"ד. ר\"ע תקטז. בלק ע' תתקיט. ישעי' כרך ג' ע' א'ריח. מאמרי אדמו\"ר הצ\"צ תרט\"ו ע' רכה."],["3213","17","<b>ה' גבורות לצורך עצמה. . בנינה</b>: ראה גם סידור תפלת ר\"ה רלו, ד ואילך. מאמרי אדה\"א דברים ח\"ג ע' א'י ואילך. ע' א'יט ואילך."],["3214","18","<b>ששת ימים ולא כתיב בששת</b>: תשא לא, יז. ראה זהר ויחי רמז, א. אמור צד, רע\"ב. מאמרי אדה\"א דברים ח\"א ע' רז ואילך. וש\"נ."],["3215","19","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג. ראה לעיל ע' קיג. וש\"נ."],["3216","20","<b>חו\"ג</b>: כנצ\"ל: חו\"ב."],["3217","21","<b>חו\"ב עילאין</b>: ראה ע\"ח שער הזווגים שט\"ו, פ\"א (מ\"ב). פ\"ד. לקמן מאמר ד\"ה את שבתותי תרי\"ב ובהערה 21."],["3218","22","<b>קדמה לעולם אלפים שנה</b>: ראה שבת פח, ב וברש\"י שם. מדרש תהלים צ, ד. הנסמן במאמרי אדה\"א דברים ח\"א ע' כ."],["3219","23","<b>מבשרי אחזה</b>: ע\"פ איוב יט, כו."],["3220","24","<b>המדות. . לזולתו. . חו\"ב. . לעצמו</b>: ראה גם לעיל ע' קטז. וש\"נ."],["3221","25","<b>שמבואר בתניא. . ההשתל' מעצם המדות</b>: ראה שער היחוד והאמונה פ\"ז."],["3222","26","<b>ומשם יפרד</b>: בראשית ב, י."],["3223","27","<b>והן הן גבורותיו</b>: יומא סט, ב ע\"פ גי' יל\"ש עקב י, יז (רמז תתנו). נחמי' ח, ו (רמז תתרעא)."],["3224","28","<b>מלכותך מכ\"ע</b>: תהלים קמה, יג."]]],[4801940237,"רבים, וגם להשפיע טעמי פירות וכמ\"ש ממגד תבואות שמש<sup data-n=\"3225\">29</sup>, וגם להתיך וכמ\"ש וחם השמש ונמס<sup data-n=\"3226\">30</sup>, וגם לייבש ולאפות ולבשל מחום הזיו כו' ועוד כמה כחות, והלא זה ידוע כי בחי' הזיו ישנו גם במקורו בעצם גוף כדור השמש, וכמבואר בתניא שאדרבה שם הוא מאיר בתוקף<sup data-n=\"3227\">31</sup> ויתר עוז כו' רק הוא שם בבחי' אין ואפס ומיוחד במקורו כו', וא\"כ האם נוכל לומר שגם בחי' הזיו כמו שהוא כלול במקורו ישנו ג\"כ בכחו להשפיע כל כחות גשמיי' הנ\"ל, וזה אין לומר, כי הלא הוא מיוחד במקורו ממש, אין ערוך כלל להיות מקור לכל הכחות, והראי' לזה שהלא אפי' בחי' הזיו שהי' מתפשט מן השמש חוץ למקורו בחלל העולם, רק שלא ע\"י התלבשותו בהעלם המגן והנרתק שעל השמש<sup data-n=\"3228\">32</sup>, ג\"כ אינו ערוך להיות מקור לכל השפעות הנ\"ל, וכמאחז\"ל לעתיד יוציא חמה מנרתקה<sup data-n=\"3229\">33</sup> ואז הרשעים נדונין בה, וצדיקים נהנין ומתרפאין בה כו', וא\"כ אנו רואים שאפי' בחי' הזיו שיתפשט בבחי' ריחוק מקום ממקורו אינו ערוך לכל ההשפעות הנ\"ל, וכ\"ש הזיו שהוא מיוחד בעצם ממש כו', וא\"כ הלא יש הפרש גדול בין הזיו המתפשט בחלל העולם, לבחי' הזיו המיוחד בעצם כו' הגם שהוא נמשך ממנו כו', והסיבה לזה הוא מחמת שעצם גוף כדור השמש נסתיים בחלל העולם, וכמ\"ש ויתן אותם אלקים<sup data-n=\"3230\">34</sup> ברקיע השמים כו', וכל חלל העולם הוא בבחי' ריחוק מקום מן העצם, וא\"כ הזיו הוא מתפשט בבחי' ריחוק מקום ממקורו, וגם יש בחי' מגן ונרתק שמכסה ומסתיר על עצם השמש וגם על הזיו הכלול בעצם כו', שאינו מאיר הזיו כמו שהוא רק הארה דהארה, ומחמת זה הוא סיבת שינוי והפרש של בחי' זיו המתפשט כו' מבחי' זיו המיוחד בעצם כו', וא\"כ הרי נוכל להבין מזה שאם יצוייר הענין כשהי' עצם גוף כדור השמש ממלא כל החלל של העולם, ולא הי' מקום חוץ, הרי הי' כל הזיו ע\"ד הזיו הכלול עתה במקורו שהוא בבחי' אין ואפס ממש, הלא להיכן יתפשט, כיון שאין לך מקום חוץ ממנו, וגם זה מובן שאז אין שייך בחי' מגן ונרתק על השמש כי הלא פעולת המגן ונרתק הוא רק לפעול בחי' שינוי הזמן שיהי' בבחי' ריחוק מקום והתפשטות ומקור לכל כחות הגשמיי' הנ\"ל, אבל כשאין מקום להתפשט ממילא אין שייך המגן ונרתק כו', רק הי' נשאר בבחי' כח ויכולת בהזיו להתפשט, וכמו עתה שגם בהזיו הכלול יש בחי' כח ויכולת להתפשט, כי הלא ההתפשטות נמשך ממנו כו'.\n<b>ועד\"ז</b> יובן למעלה בבחי' שמש הוי' דז\"א<sup data-n=\"3231\">35</sup> שהוא מקור כל ההשתל' כמ\"ש בתניא אשר ע\"ז נק' בשם הוי' שמורה שהוא בחי' מקור המהווה והתוס' יו\"ד<sup data-n=\"3232\">36</sup> מורה על תמידיות הפעולה, שבכל עת ורגע הוא מחי' ומהווה כו', אך מ\"מ",[["3225","29","<b>ממגד תבואות שמש</b>: ברכה לג, טו [ושם: וממגד]."],["3226","30","<b>וחם השמש ונמס</b>: בשלח טז, כא."],["3227","31","<b>וכמבואר בתניא שאדרבה שם הוא מאיר בתוקף</b>: ראה שער היחוד והאמונה פ\"ג."],["3228","32","<b>והנרתק שעל השמש</b>: ראה גם מאמרי אדה\"א דברים ח\"ג ע' תתקב. וש\"נ. בהערה הבאה."],["3229","33","<b>לעתיד יוציא חמה מנרתקה</b>: ראה נדרים ח, ב."],["3230","34","<b>ויתן אותם אלקים</b>: בראשית א, יז."],["3231","35","<b>שמש הוי' דז\"א</b>: ראה ע\"ח שער לידת המוחין שכ\"א, פ\"ב."],["3232","36","<b>כמ\"ש בתניא. . הוי'. . מקור המהווה והתוס' יו\"ד</b>: ראה שער היחוד והאמונה פ\"ד."]]],[4801940290,"הלא ידוע כי אם הי' הגילוי בהשתל' מעצם שם הוי' בלתי בחי' מגן ונרתק דשם אלקים<sup data-n=\"3233\">37</sup> א\"א לקבלו בבחי' השתל' באופן כזה, כי הלא שם הוי' מורה ג\"כ הפי' הי' הוה ויהי' כאחד<sup data-n=\"3234\">38</sup> דהיינו כמו קודם שנבה\"ע הי' ממלא כל החלל כן עתה אחר שנבה\"ע בלי שום שינוי כלל וכמ\"ש אני הוי' לא שניתי<sup data-n=\"3235\">39</sup> כו', וגם כמ\"ש והקדוש בשמים ובארץ<sup data-n=\"3236\">40</sup> שידוע שקדוש בוי\"ו קאי על בחי' מדות דז\"א שהוא ממלא כל החלל למטה כמו למעלה, וא\"כ כל הנבראים הם כלולים במקורם בבחי' אין ואפס, ולזה הטעם נק' בחי' מדות לגבי מל' בחי' סוכ\"ע, וידוע דהפי' סובב אינו מקיף מלמעלה<sup data-n=\"3237\">41</sup> רק אדרבה תוכו ותוך תוכו ולית אתר פנוי מיני'<sup data-n=\"3238\">42</sup> רק הכוונה הוא שמאיר בהעלם ולא בגילוי כי אלו יתגלה להמקבלים הי' מרגישים כי הם בבחי' אין. וזהו מ\"ש בתניא כי אלמלא ניתן רשות<sup data-n=\"3239\">43</sup> לעין לראות היו רואים כי הנפעל הוא בחי' אין ואפס לגבי כח הפועל, כי באמת גם אחרי התהוותו בבחי' נפעל הוא בבחי' התכללות במקורו, אבל הלא תכלית הכוונה שיהי' הנברא נראה בבחי' יש כו', ולזאת נתגלה בחי' המל' שבנינה מהגבורות, והוא ג\"כ כח הא\"ס שמורה על שלימות בלתי שום חסרון שיש בו גם הכח להעלים ולצמצם א\"ע כו', ולזה הטעם נק' בחי' מל' בזוהר בשם ים סוף<sup data-n=\"3240\">44</sup> שמפרש בזוהר דקאי על בחי' מל' שנק' סופא דכ\"ד<sup data-n=\"3241\">45</sup> דאצי', שלכאורה אינו מובן כלל איך נק' בחי' מל' בשם סוף הלא היא ג\"כ מדה האלקי' וכמ\"ש לך ה' הממלכה<sup data-n=\"3242\">46</sup> כמו לך ה' הגדולה כו' ומיוחדת ג\"כ במאצילה כו'. רק הכוונה הוא שבחי' גבורות שבמל' בכחם לסיים ולהסתיר לגבי המקבלים שלא ירגישו עצם גילוי המדות כמו שהם מצד עצמם שממלא כל החלל גם עתה, והוא ע\"ד דוגמת זיו השמש כנ\"ל כשיהי' מקור לכל הכחות הגשמיי' הנ\"ל מוכרח שיסתיים עצם גוף כדור השמש בחלל העולם ויתלבש בבחי' מגן ונרתק כנ\"ל, ואז יוכל הזיו להשתנות להיות בבחי' מקור כנ\"ל, וכאן בזיו השמש הוא בחי' סיום בפועל, ולמעלה הוא רק בחי' סיום והעדר הגילוי למקבלים.\n<b>וזהו\"ע</b> הנז' בכהאריז\"ל שיש ה\"ג לצורך עצמה היינו אפי' עצמי' המל' כמו שהיא בבחי' אצי' שנק' בשם מלכותך כו' הוא ג\"כ ע\"י גבורות וכח המעלים ואז תוכל להיות בבחי' מקור לנשמות ומלאכים דאצי' שנק' בשם עולם האצי' כו', וזהו",[["3233","37","<b>הלא ידוע. . שם הוי'. . דשם אלקים</b>: ראה שער היחוד והאמונה שם ואילך."],["3234","38","<b>הוי'. . הי' הוה ויהי' כאחד</b>: ראה שער היחוד והאמונה פ\"ז. תו\"ח מקץ ריט, ד הערה 62."],["3235","39","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["3236","40","<b>והקדוש בשמים ובארץ</b>: ברכת ישתבח. ראה גם מאמרי אדה\"א שמות ח\"ב ס\"ע תכב. וש\"נ. דברים ח\"א ע' קפג. וש\"נ."],["3237","41","<b>דהפי' סובב אינו מקיף מלמעלה</b>: ראה תניא פמ\"ח סז, סע\"ב ובמ\"מ הגהות והע\"ק לשם. לעיל ע' קס ובהערה 64."],["3238","42","<b>ולית אתר פנוי מיני'</b>: ראה ת\"ז תנ\"ז צא, ב. ת\"ע קכב, ב. ס' האמונות והדעות לרס\"ג מ\"ב, פי\"ג. תניא פכ\"א ובמ\"מ הגהות והע\"ק לשם. לקו\"ת בהר מא, א. שם בהוספות נב, ג."],["3239","43","<b>מ\"ש בתניא כי אלמלא ניתן רשות</b>: ראה שער היחוד והאמונה פ\"ג."],["3240","44","<b>מל' בזוהר בשם ים סוף</b>: רע\"מ פינחס רנו, ב."],["3241","45","<b>מל' שנק' סופא דכ\"ד</b>: ראה זהר בשלח נו, א. פקודי רכו, סע\"א."],["3242","46","<b>לך ה' הממלכה</b>: דהי\"א כט, יא."]]],[4801940340,"פי' הא' הנ\"ל שיעור ה' שהשיעורים וצמצומים שיתגלה בחי' ה' שהוא בחי' מל' כנ\"ל אפי' בבחי' אצי', רק ע\"ז כתיב כי נשגב שמו לבדו<sup data-n=\"3243\">47</sup>, והיינו אפי' בחי' שמו שהוא בחי' מל' כמו שהיא בבחי' אצי' עדיין הוא נשגב ומרומם עדיין להיות בחי' מקור לנשמות ומלאכים דבי\"ע בבחי' ומשם יפרד, כי הלא נשמות ומלאכים דאצי'<sup data-n=\"3244\">49</sup> נק' בשם נוני ימא<sup data-n=\"3245\">48</sup> וכמאמר כל מה שיש ביבשה<sup data-n=\"3246\">50</sup> יש בים רק ההפרש שברואים שביבשה הם בבחי' נפרדים ממקורם אבל ברואים שבים אינם נפרדים כלל ממקורם והם בתכלית הביטול ובהתכללות במקורם כו'. כן ע\"ד דוגמא למעלה נשמות ומלאכים דאצי' הם בתכלית הביטול וההתכללות במקורם והביטול בתמידיות אצלם, ולא נפסק אפי' רגע אחת, הגם שהם מהות בפ\"ע אשר ע\"ש זה נק' בשם עולם האצי', וכמו דגים שבים שהם כלולים במקורם אבל מ\"מ הם מהות בפ\"ע, כי הדג אינו מים ומים אינם דג כו', וזה פועל בחי' גבורות שבמל' שאינם ע\"ד זיו השמש בשמש שהוא מיוחד בעצם השמש ואינו עולה בשם כלל כו', אבל מ\"מ ה\"ה כלולים במקורם לגמרי, וא\"כ בחי' מל' דאצי' כמו שהיא בבחי' אצי' נשגב ומרומם מגדר ברואים שביבשה שהם בחי' בי\"ע ששייך שם ומשם יפרד כו' שהנברא יוכל להיות בבחי' פירוד ממקורו כו', ולזה צ\"ל עוד בחי' גבורות וצמצומים שיסתירו ויעלימו גם על בחי' המל' כמו שהיא באצי' שלא תאיר כמו שהיא בעצם רק בחי' הארה דהארה מאיר ממנה להיות מקור לבריאה, וזהו מה שמבואר במקובלים כי בחי' מל' דמל' דאצי' נעשה עתיק לבריאה<sup data-n=\"3247\">51</sup>, ובכל מקום מל' נק' בחי' סוף שהכוונה שמסיים ומעלים לגבי המקבלים שלא יאיר כמו שהוא, וזהו\"ע הנזכר במקובלים שיש ה\"ג לצורך עצמה, וגם ה\"ג לצורך בנינה, שהוא להיות מקור לבנין העולמות כו'.\n<b>וזהו</b> מ\"ש י\"ב בקר<sup data-n=\"3248\">52</sup> דקאי על ד' מחנות<sup data-n=\"3249\">54</sup> שכינה<sup data-n=\"3250\">53</sup> דבריאה, והים עומד עליהם מלמעלה כו', והיינו בחי' הים שהוא בחי' המל' כמו שהיא באצי' עומד עליהם מלמעלה בבחי' מקיף ובהעלם כו', וגם לבד הגבורה שבעצם המל' שהוא בחי' ה' אותיות דש' אלקים<sup data-n=\"3251\">55</sup> כידוע צ\"ל בחי' פרסא המפסקת בין אצי' לבי\"ע<sup data-n=\"3252\">56</sup> שהוא דוגמת המגן ונרתק על השמש כו'. ובזה יובן ענין פי' הב' דשיעור ה' היינו השיעורים",[["3243","47","<b>כי נשגב שמו לבדו</b>: תהלים קמח, יג. ראה לקמן ע' שיב."],["3244","49","<b>ומלאכים דאצי'</b>: ראה גם שע\"ת צב, ג הערה 32. אוה\"ת פסח כרך ד ע' א'ד."],["3245","48","<b>נשמות ומלאכים דאצי' נק' בשם נוני ימא</b>: ראה גם לעיל ע' פו. וש\"נ."],["3246","50","<b>כל מה שיש ביבשה</b>: חולין קכז, א. ראה גם תו\"ח שמות ח\"א יח, ג הערה 770."],["3247","51","<b>מל' דמל' דאצי' נעשה עתיק לבריאה</b>: ראה ע\"ח שער העקודים ש\"ו, פ\"ב. לקמן ע' שיב."],["3248","52","<b>י\"ב בקר</b>: מל\"א ז, כה. מד. דהי\"ב ד, טו."],["3249","54","<b>ד' מחנות שכינה</b>: זהר במדבר קיח, ב."],["3250","53","<b>י\"ב בקר דקאי על ד' מחנות שכינה</b>: ראה גם ביאוה\"ז ויצא י, ג ואילך. שלח צ, ד. לקו\"ת בלק סח, ג. לקמן מאמר ד\"ה והניף הכהן אותם הב' על יד הערה 25-29."],["3251","55","<b>הגבורה. . ה' אותיות דש' אלקים</b>: ראה לקו\"ת להאריז\"ל פ' נח ז, כ. ע\"ח שער מ\"ן ומ\"ד של\"ט, דרוש א (מ\"ק)."],["3252","56","<b>פרסא המפסקת בין אצי' לבי\"ע</b>: ראה ע\"ח שער דרושי נקודות ש\"ח, פ\"ב. לקוטי הש\"ס להאריז\"ל חולין ס, ב ד\"ה לכי ומעטי (כ, ב). הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתפא. וראה גם לקמן מאמר ד\"ה וזכרתי הר\"ת על יד הערה 29 ואילך."]]],[4801940387,"והצמצומים מבחי' עצם הה\"א כשנתגלה שיומשך ממנה בחי' מקור לבי\"ע הוא ג\"כ ע\"י שיעורים וצמצומים כו' כנ\"ל. וזהו\"ע שעורה מאכל בהמה כו' וד\"ל. נמצא שבחי' מל' היורדת בבי\"ע הוא כח אלקי המחשיך ומסתיר לגמרי עד שבריבוי השתל' יסתיר ויחשיך לגמרי עד שיתהווה חשך גמור דקליפות וסט\"א וכמ\"ש רגלי' יורדות<sup data-n=\"3253\">57</sup> כו' וכמ\"ש ומלכותו בכל משלה<sup data-n=\"3254\">58</sup> כו', וע\"ז כתיב אדם ובהמה תושיע<sup data-n=\"3255\">59</sup> ה' דקאי על בחי' זו\"נ כי בחי' ז\"א נק' ועל הכסא דמות<sup data-n=\"3256\">60</sup> כמראה אדם כו' ובחי' מל' נק' בשם בהמה רבה כו'. ולגבי בחי' מל' היורדת להיות עתיק לבריאה כו' גם בחי' מל' דאצי' נק' בשם אדם ששייך לומר ג\"כ על הכסא כו' דקאי על בחי' כורסייא דבריאה שנכללת ג\"כ בבחי' ציור אדם כו'.\n<b>והנה</b> ידוע שהאדם דלמטה נברא בדוגמא העליונה וכמ\"ש בצלם אלקים עשה את האדם<sup data-n=\"3257\">61</sup> וגם כמ\"ש נעשה אדם בצלמנו כדמותינו<sup data-n=\"3258\">62</sup> כו', וגם לידת הנשמות הוא מבחי' יחוד זו\"נ<sup data-n=\"3259\">63</sup> כידוע הענין על מ\"ש בנים אתם<sup data-n=\"3260\">64</sup> כו', וא\"כ גם בחי' הנה\"א שייך לקרותה בשם ה\"א כידוע שלזאת נק' בשם אשה יראת ה'<sup data-n=\"3261\">65</sup> כו' שהצירוף תיבת אשה הוא אש ה'<sup data-n=\"3262\">66</sup>, שהפי' הוא שהרשפי אש באהבה עזה אשר יש בהנשמה הוא מצד שרשה בבחי' ה' כמאמר כל ישראל בני מלכים הם<sup data-n=\"3263\">67</sup> כמבואר במ\"א, וא\"כ גם למטה בהנשמה שייך לומר שיעור ה' וב' הפי' דשיעור ה' כנ\"ל. והענין הוא כידוע דעצם הנשמה כמו שהיא בשרשה א\"א לבא כמו שהיא בגוף גשמי כידוע הראי' שאפי' מלאך שהוא למטה מן הנשמה נאמר עליו בשליש העולם עומד<sup data-n=\"3264\">68</sup> וא\"כ כ\"ש הנשמות שהם גבוהים ממלאכים כו' וא\"כ מוכרח לומר שרק הארה מצומצמת מן עצם הנשמה כמו שהיא למעלה מאירה בגוף, ועצם הנשמה נשארת למעלה בבחי' מקיף [ובזה נוכל לומר בד\"א שזהו הכוונה בתניא פ\"ב לשונו הזהב ונפש השנית היא חלק אלוק' ממעל ממש כו', שלכאורה קאי על עצם הנשמה וא\"כ למה קרא אותה בשם נפש<sup data-n=\"3265\">69</sup>, הלא עצם הנשמה נק' בחי' יחידה כידוע בענין ה' חלקי הנשמה נר\"נ ח\"י<sup data-n=\"3266\">70</sup> וא\"כ למה קרא בשם נפש, אלא שנוכל לומר שהכוונה דקדוק הלשון ונפש השנית",[["3253","57","<b>רגלי' יורדות</b>: משלי ה, ה. ראה זהר ויחי רכא, ב. אוה\"ת משלי כרך א ע' תקסד ואילך. קונט' עה\"ח ע' 27 אילך."],["3254","58","<b>ומלכותו בכל משלה</b>: תהלים קג, יט."],["3255","59","<b>אדם ובהמה תושיע ה'</b>: תהלים לז, ז."],["3256","60","<b>ועל הכסא דמות</b>: יחזקאל א, כו [בדילוג]."],["3257","61","<b>בצלם אלקים עשה את האדם</b>: נח ט, ו."],["3258","62","<b>נעשה אדם בצלמנו כדמותינו</b>: בראשית א, כו."],["3259","63","<b>לידת הנשמות. . זו\"נ</b>: ראה אגה\"ק ס\"כ. לקו\"ת שה\"ש יט, ג. לקמן מאמר ד\"ה את שבתותי תרי\"ב ובהערה 72."],["3260","64","<b>בנים אתם</b>: פ' ראה יד, א. לקמן ובהערה 231."],["3261","65","<b>אשה יראת ה'</b>: משלי לא, ל."],["3262","66","<b>אשה הוא אש ה'</b>: ראה סוטה יז, א. זהר בראשית מח, ב. ביאוה\"ז נח ז, ב. תו\"ח בשלח ח\"א רלח, ב. וש\"נ."],["3263","67","<b>כל ישראל בני מלכים</b>: שבת סז, א. ראה גם לעיל ע' קל ובהערה 33."],["3264","68","<b>מלאך. . בשליש העולם עומד</b>: ראה ב\"ר פס\"ח, יב. חולין צא, ב. מורה נבוכים ח\"ב, פ\"י. לקו\"ת נצבים עד, סע\"ד ובהנסמן במ\"מ לשם. מאמרי אדה\"ז תקס\"ו ע' ק ”שהוא ק\"ס שנה\". סידור שער החנוכה רעו, א ”קס\"ו וב\"ש שנה\"."],["3265","69","<b>בשם נפש</b>: ראה גם לקו\"ש כרך ה ע' 416 הערה נשמות. שיעורים בספר התניא פ\"א ע' 14 הערה 18."],["3266","70","<b>נר\"נ ח\"י</b>: ב\"ר פי\"ד, ט. ראה הנסמן במאמרי אדה\"א דברים ח\"ב ע' תכח."]]],[4801940431,"בישראל כו' שקאי על התלבשותה בגוף הוא בחי' נפש מעצם הנשמה שהוא בחי' אחרונה שבה ומ\"מ היא ג\"כ כלולה מה' חלקי הנשמה נר\"נ ח\"י כו']. וא\"כ מה שנק' בשם אות ה' הוא ע\"י שיעורים וצמצומים גדולים מעצם הנשמה. אך מ\"מ הרי בחי' נה\"א נק' בחי' אדם, וכמ\"ש ורוח האדם היא העולה למעלה<sup data-n=\"3267\">71</sup> דקאי על האהבה עזה כרשפי אש שישנה בבחי' נה\"א וכמ\"ש מי לי בשמים<sup data-n=\"3268\">72</sup> כו' כלה שארי ולבבי<sup data-n=\"3269\">73</sup> כו', שהוא מצד המקיפים דהנשמה שנק' בשם ח\"י שהם ג\"כ בבחי' הסתר והעלם תוך מצפוני לבבו, והראי' שהאהבה הטבעיות נק' בשם אהבה מוסתרת כו' וכ\"ש בחי' חי' יחידה כו', וא\"כ שייך ג\"כ לומר פי' הב' של שיעור ה' שקאי על ההסתר דגוף ונה\"ב שהוא ג\"כ ע\"י שיעורים וצמצומים מבחי' עצם הנשמה כמו שהיא מאירה בבחי' עש\"כ<sup data-n=\"3270\">74</sup> הנק' בשם נר\"נ כו' המלובשים בגוף שישנו לעומת זה עש\"כ דנה\"ב שמסתירים לגמרי, עד שיוכל להיות היפוך לגמרי בחי' ורוח הבהמה יורדת למטה<sup data-n=\"3271\">75</sup> כו' לעצמו ולגרמי' כו' אהבת עצמו כו', וגם עד שיוכל להיות ח\"ו רגלי' יורדות כו' שהוא ליפול בבחי' רע גמור דגקה\"ט ר\"ל באיסור דאורייתא או באיסור דרבנן ר\"ל, וא\"כ החשך דנה\"ב יוכל להחשיך ולהעלים לגמרי כו', ובחי' זה נק' בין למעלה ובין למטה בחי' עמר שעורים כי עמר בגימטריא יש ולמעלה בחי' מל' הוא כח ההסתר שיתהווה בחי' יש המסתיר ולמטה הוא בנה\"ב הוא בחי' המסתיר לגמרי שיהי' בבחי' יש נפרד ח\"ו. והגם שבחי' נה\"א הלא נק' בחי' אדם כו' אבל כיון שנתלבש בבחי' נה\"ב נק' ג\"כ בשם בהמה לגבי עצם המקיף דמזלי' שנשאר למעלה כו' ומ\"מ לגבי הגוף ונה\"ב ממש נק' גם הנה\"א המתלבש בגוף בשם אדם כו' וד\"ל.\n<b>אך</b> זה ידוע שבחי' החשך שלמעלה בבחי' המל' המסתיר כו' והן למטה בחי' חשך דנה\"ב אין הכוונה ח\"ו שישאר בבחי' חשך אלא אדרבה הכוונה שיהפכו החשך לאור, ויהי' יתרון האור מן החשך דוקא, וכמ\"ש צחוק עשה לי אלקים<sup data-n=\"3272\">76</sup> שידוע הפי' שהצחוק ועונג הנעלם יתגלה לעתיד דוקא מהסתר דשם אלקים אשר לזה מורה השם יצחק שמורה לעתיד<sup data-n=\"3273\">77</sup> כו', והיינו כאשר יתהפך החשך דש' אלקים לבחי' אור כו', וכמאמר הזוהר מאן מנכון דמהפכין<sup data-n=\"3274\">78</sup> חשוכא לנהורא, והכוונה שעצם החשך דנה\"ב יתהפך לאור, ואז יפעל בזה שגם למעלה בשרשו גם החשך דבחי' מל' כנ\"ל יתהפך לאור [שהרי אח\"כ תלוי במעשה התחתונים<sup data-n=\"3275\">79</sup> דוקא כידוע] וכאשר יתהפך עצם החשך דבחי' מל' לאור אז יהי' יתרון אור למעלה מעלה באין ערוך מן בחי' האור שקודם החשך כו', וכמו לעתיד כשיהי' שלימות הבירור של החשך, אז דוקא",[["3267","71","<b>ורוח האדם. . למעלה</b>: קהלת ג, כא [ושם: מי יודע רוח בני האדם. ראה גם ש\"א י, א הערה 36]."],["3268","72","<b>מי לי בשמים</b>: תהלים עג, כה."],["3269","73","<b>כלה שארי ולבבי</b>: תהלים עג, כו."],["3270","74","<b>עש\"כ</b>: עשר כחות."],["3271","75","<b>ורוח הבהמה יורדת למטה</b>: קהלת שם."],["3272","76","<b>צחוק עשה לי אלקים</b>: וירא כא, ו. ראה תו\"א תולדות יז, ג ואילך. לקו\"ת שלח מח, סע\"ג. ש\"ש סז, ב."],["3273","77","<b>יצחק שמורה לעתיד</b>: ראה תו\"א תולדות שם. תו\"ח ח\"ש קכח, א ובהערה 15."],["3274","78","<b>מאן מנכון דמהפכין</b>: ראה זהר בהקדמה ד, א. סה\"מ תרכ\"ט ע' פח ואילך. וש\"נ. מאמר ד\"ה זאת חוקת התורה ש\"פ פרה תשכ\"ו."],["3275","79","<b>תלוי במעשה התחתונים</b>: ראה ע\"ח שער דרושי הנקודות ש\"ח, ספ\"ו."]]],[4801940470,"בחי' מל' יגלה כל עצמותו למטה מטה דוקא, וכמאמר בתפלת ר\"ה ותמלוך אתה הוי' לבדך<sup data-n=\"3276\">80</sup> על כל מעשיך כו' והיינו שבחי' מעשיך הוא נשמות בגופים בעשי' גשמי' ירגישו בחי' אתה הוי' לבדך, וכמאמר גלה כבוד מלכותך עלינו<sup data-n=\"3277\">81</sup> כו', וא\"כ יתהפך החשך דבחי' מל', שעתה בכחה רק להסתיר ולהעלים כנ\"ל באריכות שבנינה רק מהגבורות ואז כל הגילוים דעצמותו ומהותו ממש יהי' דוקא ע\"י בחי' המל'.\n<b>וזהו\"ע</b> שעצם החשך יאיר כו', והכל תלה במעה\"ת<sup data-n=\"3278\">82</sup> דוקא כשיברר ויהפך עצם החשך דנה\"ב שהחשך יאיר, ואין הכוונה שרק יאיר את החשך ע\"ד דוגמא כשמכניסין אור במקום החשך הרי מעט אור דוחה הרבה מן החשך<sup data-n=\"3279\">83</sup> וכ\"ש הרבה אור כו' שהוא מאיר את החשך כו', וא\"כ לכאורה הרי נתהפך החשך לאור ואינו מחשיך כלל, אך באמת אין זה נק' כלל שעצם החשך נתהפך לאור, רק נק' בחי' דוחה הרבה מן החשך, אבל באמת הרי החשך עדיין הוא בתקפו וגבורתו רק שנדחה פעולת והתפשטות החשך שבכחו להחשיך ולהסתיר, שזהו בטבעיות האור לדחות שהרי כשמכניסין אור אינו מחשיך לגמרי, אבל עצם החשך עדיין הוא בתקפו וגבורתו בשלימות גם בעת הכנסת האור, ויש לזה ב' ראיות, הא' שאם נאמר שעצם החשך נתהפך לאור ולא נשאר מציאותו לגמרי שם, א\"כ הי' צריך להיות שאחרי הסתלקות האור מאותו המקום שלא יחזור החשך כלל כיון שנתהפך לגמרי ואינו במציאות כלל והרי אנו רואים כי תומ\"י בלי שום שהיות זמן כלל חוזר החשך בשלימות כמו בתחלה, וא\"כ מוכרח לומר שעצם החשך ישנו במציאות, רק הפעולות שלו וההתפשטות נדחה ולכן אין בכחו להתפשט להחשיך כו', ועוד ראי' ב' שהרי אנו רואים כשיודלק נר א' בבית, הגם שדוחה החשך ויוכלו לראות שם כל הענינים הנמצאים בבית, אך מ\"מ כשידלקו שם בבית מאה נרות, אז יהי' האור יותר גדול, וא\"כ האור של הנר א' בחי' חשך יחשב לגבי אור של המאה נרות, וא\"כ גם פעולת והתפשטות החשך עדיין ישנו קצת בבחי' נר א', וכן אור של המאה נרות בחי' חשך יחשב לגבי אור של אלף נרות, כיון שאז מאיר יותר הרבה, וכן עד רום המעלות. וא\"כ הרי החשך עדיין לא נתהפך לגמרי עצם מהות שלו כו' וד\"ל.\n<b>וכן</b> באור היותר גדול כמו מבחי' אור של היום שמן השמש, שגדול הרבה מאור הנר כמאמר שרגא בטיהרא מאי אהני<sup data-n=\"3280\">84</sup>, מ\"מ אינו ג\"כ רק דחיית החשך, וג\"כ כפי' ב' ראיות הנ\"ל שהרי בהסתלק מאור השמש תחת הכדור יהי' חשך כמו בתחלה, וגם ראי' הב' שהרי יש ענין הרואה חמה בתקופתה<sup data-n=\"3281\">85</sup>, שהאור מאיר יותר, וכמאמר תוקפא דשמשא<sup data-n=\"3282\">86</sup> וכנ\"ל, אבל שיתהפך עצם מהות של החשך לאור דהיינו שעצם החשך יאיר ולא בדרך דחיי' לא מצינו דוגמתו רק בבחי' אבנים טובות, שהרי עצם",[["3276","80","<b>בתפלת ר\"ה ותמלוך אתה הוי' לבדך</b>: ראה תפלת העמידה (בברכת אתה קדוש) לימים נוראים."],["3277","81","<b>גלה כבוד מלכותך עלינו</b>: מוסף ליו\"ט וימים נוראים."],["3278","82","<b>במעה\"ת</b>: במעשה התחתונים."],["3279","83","<b>מעט אור דוחה הרבה מן החושך</b>: ראה חובת הלבבות שער יחוד המעשה פ\"ה. תניא פי\"ב."],["3280","84","<b>שרגא בטיהרא מאי אהני</b>: חולין ס, ב."],["3281","85","<b>הרואה חמה בתקופתה</b>: ברכות נט, סע\"ב."],["3282","86","<b>תוקפא דשמשא</b>: זהר ויצא קמח, א. ויחי רמד, ב. ועוד."]]],[4801940505,"האבן טוב מאיר בלילה כידוע בענין צוהר תעשה כו' חד אמר אבן טוב<sup data-n=\"3283\">87</sup> שהי' מאיר להם בתיבה, וידוע דיסוד העפר הוא למטה מכל היסודות<sup data-n=\"3284\">88</sup>, וביסוד העפר בחי' אבנים למטה יותר, שהרי ביסוד העפר ישנו כח האלקי דמאמר תדשא<sup data-n=\"3285\">89</sup> להצמיח כל מיני צמח שהוא כח אלקי ורוחני, אבל בחי' אבן הוא קשה ביותר ואינו ראוי לצמיחה, ובאבנים גופא בחי' אבן טוב הוא יותר קשה משאר האבנים וכ\"ש אבן ספיר<sup data-n=\"3286\">90</sup> שהוא יותר קשה מכולם, וכדאי' במדרש שא' הביא סנפרינון<sup data-n=\"3287\">91</sup> וניסה אותו שנבקע הסדין והפטיש והסנפרינון לא זז ממקומו, רק מפני שהם במקומות החמים שהשמש מאיר בהם בתוקף<sup data-n=\"3288\">92</sup> נקלט בהם אור השמש ונתאחד בהם עד שהוא בעצמו יאיר, וגם בלילה כשנסתלק אור השמש אז דוקא מאיר האבן טוב בלילה דוקא, וא\"כ הרי נקלט ונתאחד עמו אור השמש עד שנתהפך עצם מהותו שהוא בחי' החשך היותר תחתון שהוא בעצמו יאיר כו' גם בהסתלקות מקורו, וא\"כ הרי נתהפך עצם מהות של החשך שלו שהוא בתקפו שהוא למטה מטה שיאיר דוקא גם בלעדי מקורו כו', אשר לזאת האבן טוב הוא ביוקר גדול יותר מכל החפצים, שהרי זהו דבר חידוש שיתהפך החשך היותר תחתון מן הקצה אל הקצה, שיאיר ג\"כ בהסתלקות מקורו, ולזה עושים מהם דוקא כתר ועטרה ע\"ג ראש המלך כו'.\n<b>וכן</b> עד\"ז יובן למעלה שזהו ההפרש בין קיום התומ\"צ שקיימו האבות קודם מ\"ת וכמאחז\"ל קיים אברהם כל התורה עד שלא ניתנה<sup data-n=\"3289\">93</sup>, ובין מתן תורה ומצות שנתנו לנו, והיינו כידוע שהקיום שלהם הי' רק ברוחניות<sup data-n=\"3290\">94</sup>, וכמבואר במ\"א שהוא רק להוסיף אור באצי', והיינו מפני הילוכם בקדש במס\"נ ממש והיו עוסקים ביחודים עליונים, עד שזכו והזדככו עצמם להיות מרכבה ממש כמארז\"ל האבות הן הן המרכבה<sup data-n=\"3291\">95</sup>, כאו\"א לשרשו עד רום המעלות וכמ\"ש באברהם הלוך ונסוע הנגבה<sup data-n=\"3292\">96</sup> וכמבואר בזוהר דרגא בתר דרגא כו' עד דאתעטר בחולקי' ועדבי', והיינו לשרש נשמתו בחסד<sup data-n=\"3293\">97</sup> דאצי', וכן יצחק כו' בעבודתו ומס\"נ שלו שהי' מלמטלמ\"ע בחפירת בארות<sup data-n=\"3294\">98</sup> כו' כידוע, זכה",[["3283","87","<b>צוהר תעשה. . אבן טוב</b>: ראה רש\"י נח ו, טז. לקו\"ש נח כרך י ע' 19 הערה 4."],["3284","88","<b>דיסוד העפר הוא למטה מכל היסודות</b>: ראה רמב\"ם הל' יסוה\"ת פ\"ג, ה\"י."],["3285","89","<b>דמאמר תדשא</b>: בראשית א, יא."],["3286","90","<b>אבן ספיר</b>: יחזקאל א, כו."],["3287","91","<b>הביא סנפרינון</b>: ראה איכ\"ר פ\"ד, י. וש\"נ. תוד\"ה מה שבת פח, ב."],["3288","92","<b>שהשמש מאיר בהם בתוקף</b>: ראה גם מאמרי אדה\"א דברים ח\"ב ע' תסז. וש\"נ."],["3289","93","<b>קיים אברהם. . ניתנה</b>: ראה יומא כח, ב. לקו\"ש תולדות כרך לה ע' 107 ואילך. פלח הרמון שמות ע' רכב."],["3290","94","<b>שהקיום שלהם הי' רק ברוחניות</b>: ראה גם סה\"מ תרכ\"ט ע' ק. וש\"נ. תו\"ח וארא ח\"א סג, ג. וש\"נ. פלח הרמון שם וע' שצה."],["3291","95","<b>האבות הן הן המרכבה</b>: ב\"ר פמ\"ז, ו. פפ\"ב, ו. ראה מאמרי אדה\"א דברים ח\"א ע' רטו. וש\"נ. תו\"ח נח מט, ד ובהערה 42. משפטים ח\"ב ש, ג. סה\"מ תרכ\"ט ע' רלח. וש\"נ."],["3292","96","<b>הלוך ונסוע הנגבה</b>: לך יב, ט. ראה זהר לך פ, א. פד, א."],["3293","97","<b>באברהם. . בחסד</b>: ראה זהר בראשית מז, ב. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקפ ובהנסמן במ\"מ לשם. מאמרי אדה\"א קונטרסים ע' ד. וש\"נ."],["3294","98","<b>יצחק. . בחפירת בארות</b>: ראה פלח הרמון תולדות עז, ב ואילך. תו\"א תולדות יז, ג. מאמרי אדה\"ז תקס\"ח ח\"א ע' תקיז ואילך. תו\"ח תולדות קמד, ד ואילך. אוה\"ת שם כרך ד ע' תתח ואילך. ע' 1628 ואילך. וראה גם סה\"מ תרע\"ח ע' עג ואילך. תרח\"ץ ע' קמז ואילך."]]],[4801940537,"להיות מרכבה לבחי' גבורה<sup data-n=\"3295\">99</sup> דאצי' וכמ\"ש פחד יצחק<sup data-n=\"3296\">100</sup> כו', ויעקב ע\"י מס\"נ שלו ובעסק המקלות<sup data-n=\"3297\">101</sup> כו' נעשה מרכבה לבחי' ת\"ת<sup data-n=\"3298\">102</sup> דאצי' קו האמצעי כו' בריח התיכון כו', נמצא שכל עבודתם הוא ע\"ד להוסיף אור באצי', אבל לא להפוך עצם החשך דהשתל' לאור, והגם שבהוספת תוס' אורות שלהם האירו גם החשך דהשתל', וכמ\"ש ואת הנפש אשר עשו בחרן<sup data-n=\"3299\">103</sup> אברהם מגייר אנשים, שרה מגיירת נשים כו', וגם כמ\"ש ויקרא בשם ה' אל עולם<sup data-n=\"3300\">104</sup> כו' שהודיע לכל באי עולם כו' כמאחז\"ל התחילו לברכו ואמר להם ברכו למי שאכלתם משלו כו', מ\"מ אין זה רק ע\"ד הנ\"ל שמעט אור דוחה הרבה מן החשך וכ\"ש ריבוי אור שהוסיפו אורות באצי' עד שהי' מאיר למטה מטה בחשך דעשי' לדחות החשך אפי' החשך של ערביים<sup data-n=\"3301\">105</sup> כו', וכמארז\"ל במדרש עד אברהם הי' העולם משמש באפילה<sup data-n=\"3302\">106</sup> בא אברהם והאיר את העולם כמ\"ש מי העיר<sup data-n=\"3303\">107</sup> כו' א\"ת העיר בעיי\"ן אלא האיר<sup data-n=\"3304\">108</sup>, בא יצחק והוסיף אור בא יעקב והוסיף אור כו' שהפי' הוא רק הוספת תוס' אור בשרשם, אבל עצם החשך של השתל' לא נהפך לאור, היינו שהבארות של יצחק, והמקלות של יעקב לא הי' בהם שום קדושה כלל<sup data-n=\"3305\">109</sup> הגם שעל ידם נמשכו האורות עליונים, כידוע בזוהר שע\"י המקלות המשיך המשכה דתפילין<sup data-n=\"3306\">110</sup> כו', והאיר למטה האור עליון הנ\"ל עד שנעשה מרכבה ממש, וגם למעלה נתעורר כל המשכת האורות דמוחין עליונים שממשיכים עכשיו ע\"י התפילין, אבל עצם המקלות לא נתאחדו עם המשכת אורות עליונים שנמשך על ידם [ויש לומר בדרך אפשר שהם היו כדוגמת המשפך שנק' בל\"א לייקע שהגם כל היין עובר על ידה, אבל לא נתאחד עמה כלל, ולא נשתנית עצם מהותה כלל כו' כידוע וכן המקלות לא נשתנו כלל כו'].\n<b>אבל</b> קיום התומ\"צ דעכשיו הלא ידוע כשכותבין התפילין על הקלף הגשמי וגם בדיו גשמי שהוא בחי' החשך התחתון דק\"נ, ומ\"מ הרי נתאחד האור אלקי בעצם הקלף הגשמי, ויש בהם ממש בחי' קדושה וכ\"ש כשכותבין ס\"ת בקלף גשמי ואותיות גשמיי' הלא נתאחד באור האלקי' ויש בה קדושה ממש, וכ\"ש וק\"ו כשאיש",[["3295","99","<b>יצחק. . גבורה</b>: ראה פרדס שער הכינויים שכ\"ב, פ\"ד. מאמרי אדה\"ז על פרשיות התורה שם ובהנסמן במ\"מ לשם."],["3296","100","<b>פחד יצחק</b>: ויצא לא, מב (ופחד). ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' תקסג."],["3297","101","<b>ויעקב. . המקלות</b>: נסמן להלן הערה 110."],["3298","102","<b>ויעקב. . ת\"ת</b>: ראה זהר ס\"ת ויצא קנז, ב. ח\"ג הוספות שב, א."],["3299","103","<b>ואת הנפש אשר עשו בחרן</b>: לך יב, ה. ראה ב\"ר פל\"ט, יד הובא ברש\"י לך שם. לקו\"ש ויצא כרך ה ע' 147 ואילך ובהערות שם. כרך י ע' 89 הערה 14."],["3300","104","<b>ויקרא בשם ה' אל עולם</b>: וירא כא, לג [בדילוג]. ראה סוטה י, ב."],["3301","105","<b>החשך של ערביים</b>: ראה ב\"מ פו, ב. תו\"ח לך פג, ד הערה 57."],["3302","106","<b>עד אברהם. . באפילה</b>: ראה ב\"ר פ\"ב, ג. שמו\"ר פט\"ו, כו."],["3303","107","<b>מי העיר</b>: ישעי' מא, ב."],["3304","108","<b>א\"ת העיר בעיי\"ן אלא האיר</b>: ראה ב\"ר פ\"ב, ג."],["3305","109","<b>לא הי' בהם שום קדושה כלל</b>: ראה לקו\"ש וירא כרך ה ע' 326. נשא כרך ח ע' 59 הערה 54."],["3306","110","<b>המקלות. . דתפילין</b>: ויצא ל, לז-ח. ראה זהר ס\"ת ויצא קסב, א. מאמרי אדה\"ז תקס\"ב ח\"א ע' יב. תו\"ח בראשית מה, ד הערה 45. לקמן מאמר ד\"ה את שבתותי תרי\"ב על יד הערה 68."]]],[4801940560,"ישראלי מניח את התפילין ע\"ג הראש או קורא בס\"ת או שארי מצות כמו נתינת הצדקה וכה\"ג הרי נתאחד אור האלקי במוחו ולבו הגשמי' של הגוף גשמי שהוא חשך היותר תחתון כמבואר בתניא שמצד הגוף אפי' יתוש קדמך<sup data-n=\"3307\">111</sup> כו', והם מתאחדים ממש באור האלקי וכמ\"ש בתניא שהיד הגשמי<sup data-n=\"3308\">112</sup> הנותן הצדקה והרגל גשמי שמהלך לדבר מצוה נעשים מרכבה לרצה\"ע שהוא בחי' סוכ\"ע שלא בהסתר פנים כלל כו' ע\"ש, וגם כמבואר בפכ\"ג בתניא וז\"ל הזהב וא\"כ החכמה שהיא התורה כו' והיא היא רצונו ית' הנק' סובב כל עלמין שהיא בחי' מה שאינו יכול להתלבש בתוך עלמין רק כו' בבחי' מקיף והיא היא המתלבשת בנפש ולבושי' בבחי' גילוי ממש כו' ואע\"ג דאיהו לא חזי כו' ומשום הכי יכול לסבול משום דלא חזי משא\"כ בעליונים כו', ועוד שם בפ' הנ\"ל וז\"ל, ומזה יוכל המשכיל להמשיך עליו יראה גדולה בעסקו בתורה כשיתבונן איך שנפשו ולבושי' שבמוחו ובפיו הם מיוחדים ממש בתכלית היחוד ברצה\"ע ואא\"ס ב\"ה ממש המתגלה בהם מה שכל העולמות עליונים ותחתונים כל\"ח קמי' כאין<sup data-n=\"3309\">113</sup> ואפס ממש עד שאינו מתלבש בתוכם ממש אלא סוכ\"ע בבחי' מקיף כו' רק איזה הארה כו' שלא יתבטלו במציאות לגמרי כו' ע\"ש, עכ\"ל הזהב. הרי נוכל להבין מזה שבחי' אור עצמותו ממש מתאחד ממש במוחו ובפיו ואברי' הגשמי' של הגוף ונה\"ב, וע\"ז מורה ל' יחוד ר\"ל שנתאחד ממש בלי הסתר פנים כלל.\n<b>וזהו\"ע</b> ברכת המצות שמברכין אק\"ב וצונו כו', קדשנו דוקא שבחי' קדש העליון עד רום המעלות מאיר בגילוי בגוף גשמי שלזה מורה ג\"כ הלשון וצונו שמורה צוותא<sup data-n=\"3310\">114</sup> והתחברות כו' כידוע, וגם זהו\"ע מאחז\"ל שכר מצוה מצוה<sup data-n=\"3311\">115</sup>, שידוע הפי' של אדמו\"ר הזקן נבג\"מ שתכלית הקבלת שכר של המצוה הוא המצוה גופא, שהפי' הוא כי לעתיד כשיוסר הכנף ולבוש של המצות שמסתירים כעת וכמ\"ש ולא יכנף עוד מוריך<sup data-n=\"3312\">116</sup> וגם כמ\"ש ונגלה כבוד ה'<sup data-n=\"3313\">117</sup> כו' שהפי' הוא בחי' לבוש, כמאחז\"ל ר' יוחנן קארי למני' מכבדותא<sup data-n=\"3314\">118</sup>, והיינו שיוסר הלבוש של התומ\"צ ויתגלה ש' הוי' העצמי' שמלובש בתומ\"צ שהאיר ונתייחד במוחו ואברי' הגשמיי' דייקא בעת עשיית המצוה בעוה\"ז דוקא וא\"כ כשתרגיש הנשמה לעתיד הגילוי הזה של עצמותו זהו תכלית של הקבלת שכר שאין למעלה הימנו אפי' בג\"ע עליון עד רום המעלות שאין נהנין אלא מזיו<sup data-n=\"3315\">119</sup> תורתן ועבודתן כידוע, אבל עצם הגילוי של התומ\"צ שנתייחד בהגוף גשמי בעת עשיי' המצוה כנ\"ל זה לא תוכל להתקבל כי הרי גם הג\"ע הוא מוגבל וכמאמר כל צדיק יש לו מדור<sup data-n=\"3316\">120</sup> כו' וגם ש\"י עולמות<sup data-n=\"3317\">121</sup> כו',",[["3307","111","<b>כמבואר בתניא שמצד הגוף אפי' יתוש קדמך</b>: ראה שם פכ\"ד."],["3308","112","<b>וכמ\"ש בתניא שהיד הגשמי</b>: פכ\"ג."],["3309","113","<b>כאין</b>: בתניא: וכאין."],["3310","114","<b>וצונו שמורה צוותא</b>: ראה גם לעיל ע' רלט ובהערה 80."],["3311","115","<b>שכר מצוה מצוה</b>: אבות פ\"ד, מ\"ב. ראה תניא פל\"ט. לקמן מאמר ד\"ה את שבתותי תקצ\"ח הערה 88."],["3312","116","<b>ולא יכנף עוד מוריך</b>: ישעי' ל, כ."],["3313","117","<b>ונגלה כבוד ה'</b>: ישעי' מ, ה."],["3314","118","<b>ר' יוחנן קארי למני' מכבדותא</b>: ראה שבת קיג, א."],["3315","119","<b>בג\"ע. . שאין נהנין אלא מזיו</b>: ראה ברכות יז, א. תניא שם."],["3316","120","<b>כל צדיק יש לו מדור</b>: ראה רו\"ר פ\"ג, ד. שבת קנב, א."],["3317","121","<b>ש\"י עולמות</b>: עוקצי' בסופה."]]],[4801940578,"אבל הגילוי הנ\"ל הוא מבחי' בלתי בע\"ג וא\"כ איך תוכל לקבל אותו, אבל לעתיד שהעולם יופשט מבחי' הגבלה וכמ\"ש פרזות תשב ירושלים<sup data-n=\"3318\">122</sup>, וגם כמאחז\"ל נחלה בלי מצרים<sup data-n=\"3319\">123</sup> וא\"כ יתאחד אז הגבול ובחי' בלתי בע\"ג והיינו שהגבול לא יסתיר אז על גילוי של בלי גבול כו', והיינו מפני שאז יאיר בחי' עצמותו ממש שלמעלה ג\"כ אפי' מבחי' בבע\"ג שנק' בחי' א\"ס כו', ולזאת יתחבר בחי' הגבול שיאיר בו בלי גבול, וכידוע הענין על מ\"ש והי' מספר בנ\"י<sup data-n=\"3320\">124</sup> כו' אשר לא ימד ולא יספר כו' כידוע.\n<b>ובזה</b> יובן ממילא הענין של יפה שעה א'<sup data-n=\"3321\">125</sup> בתשומע\"ט בעוה\"ז מכל חיי העוה\"ב וכנ\"ל, וגם כידוע הענין בשם אדמו\"ר האמצעי נבג\"מ על הפסוק שמח נפש עבדך<sup data-n=\"3322\">126</sup> כי אליך ה' נפשי אשא כו' שביקש דוד זאת בגילוי דלעתיד שהוא בחי' עונג הנעלם בעצמותו ית', שמאיר היום בעוה\"ז דייקא בעת עשיי' המצוה דוקא כמאחז\"ל נחת רוח לפני<sup data-n=\"3323\">127</sup> שאמרתי ונעשה רצוני כו' בחי' נעשה דוקא שהוא בגוף גשמי ובקלף גשמי כו' וגם זהו\"ע הידוע שהעיקר כדעת הרמב\"ן שעיקר קבלת השכר של המצות יהי' דוקא בעולם התחי' שיחי' הגוף גשמי<sup data-n=\"3324\">128</sup> דוקא, וכל הנשמות שהיו בג\"ע אפי' נשמות האבות ונשמת משה רבינו שהם יותר משלשה אלפים שנה בגעה\"ע ומתענגי' שם בעילוי אחר עילוי יצאו מג\"ע ויתלבשו בגופים גשמים דוקא, וזהו עיקר הקבלת שכר שלהם והיינו שאז תרגיש נשמתם הגילוי של עצמותו שהאיר ונתאחד בהגוף גשמי דוקא בעת עשיית המצוה שהוא בחי' גילוי עצמותו כנ\"ל, וא\"כ אין לך קבלת שכר למעלה מזו כו' וד\"ל. וא\"כ היוצא מכל הנ\"ל שהגוף גשמי ואברי' גשמיי' כו' שהוא חשך היותר אחרון של השתל', וכמאמר אחור למע\"ב<sup data-n=\"3325\">129</sup> כו', יתברר ויתלבן ע\"י מעהמ\"צ הגשמיי' שהאברי' גשמיי' בעצמם יתאחד ויוקלט בהם האור של עצמותו ית' עד שהם גופא יאירו לעתיד בעולם התחי' עד שהנשמה תקבל האור והשעשועי' דוקא מבחי' האור של אברי' הגשמיי' דוקא. וא\"כ ז\"ע לאהפכא חשול\"נ היינו כנ\"ל שהחשך בעצמו יאיר באור גדול כנ\"ל, וזהו דוגמת אבנים טובים כנ\"ל שהגם שהם בחי' חשך היותר אחרון כנ\"ל נתאחד ונקלט בהם האור שהם בעצמם מאירים כו' כנ\"ל אשר לזה הוא יקר המציאות יותר מכל החפצים שבעולם ועושים מהם בחי' עטרה וכתר למלך כו'. וכ\"ה ע\"ד דוגמא בחי' מצות שעש\"ז נק' בשם מע\"ט שהוא כמו אבנים טובות, דהיינו שהם טובים ומאירים כנ\"ל וכמ\"ש את האור כי טוב<sup data-n=\"3326\">130</sup> כו', ובאמת נתהפך החשך לאור בעת עשיי' המצוה בעוה\"ז דוקא כנ\"ל, רק שהנפש לא תרגיש הגילוי כעת מפני שלא נזדכך העולם, וכמ\"ש בתניא<sup data-n=\"3327\">131</sup> וז\"ל הזהב כי<sup data-n=\"3328\">132</sup> לית מח' תפיסא בי' כו' כ\"א כאשר תפיסא ומתלבשת בתומ\"צ אזי היא תפיסא",[["3318","122","<b>פרזות תשב ירושלים</b>: זכרי' ב, ח."],["3319","123","<b>נחלה בלי מצרים</b>: שבת קיח, סע\"א."],["3320","124","<b>והי' מספר בנ\"י</b>: הושע ב, א. ראה מאמרי אדה\"א במדבר ח\"א ע' קיג ואילך ובהנסמן בריש המאמר שם."],["3321","125","<b>יפה שעה א'</b>: אבות פ\"ד, מי\"ז."],["3322","126","<b>שמח נפש עבדך</b>: תהלים פו, ד."],["3323","127","<b>נחת רוח לפני</b>: ספרי שלח טו, ז. י. ראה לקו\"ש ויקרא כרך לב ע' 1. וש\"נ."],["3324","128","<b>כדעת הרמב\"ן. . השכר. . הגוף גשמי</b>: ראה שער הגמול [כתבי הרמב\"ן ח\"ב ע' שט]. לקמן מאמר ד\"ה וזכרתי הר\"ת ובהערה 106."],["3325","129","<b>אחור למע\"ב</b>: ברכות סא, א."],["3326","130","<b>את האור כי טוב</b>: בראשית א, ד."],["3327","131","<b>וכמ\"ש בתניא</b>: פ\"ד."],["3328","132","<b>כי</b>: בתניא ליתא."]]],[4801940590,"בהן ומתלבשת בהקב\"ה ממש דאוריי' וקוב\"ה כולא חד, ואף שהתורה נתלבשה בדברים תחתונים גשמיי' ה\"ז כמחבק את המלך ד\"מ שאין הפרש במעלת התקרבותו ודביקותו במלך בין מחבקו כשהוא לבוש לבוש א' בין כשהוא<sup data-n=\"3329\">133</sup> לבוש כמה לבושים מאחר שגוף המלך בתוכם וכן אם המלך מחבקו כו' עכ\"ל הזהב. וא\"כ הרי מפורש שבעת עשיי' המצוה ולימוד התורה נתהפך החשך לאור כו', וז\"ע כיתרון האור מן החשך<sup data-n=\"3330\">134</sup> שיש בזה ג' פי' כו' הא' שבחי' היתרון ומעלה של האור ניכר מן החשך<sup data-n=\"3331\">135</sup> דוקא כי אם לא הי' בחי' חשך לא הי' ידוע מעלת האור כו', ופי' הב' שבבחי' אור יש לו יתרון ושליטה וממשלה על החשך לדחותו וכמאמר מעט אור דוחה הרבה מן החשך כו', ופי' הג' שיש יתרון להאור שנתגלה מן עצם החשך, היינו כשהחשך נתהפך לאור דוקא, אז יש יתרון לבחי' אור הזה דוקא יותר הרבה והרבה באין ערוך לגבי האור שקדם לחשך שרק הוא דוחה את החשך וכנ\"ל באריכות. והוא בחי' אור חדש לגמרי שלא הי' עדיין בבחי' גדר גילוי אור כו' וד\"ל.\n<b>והטעם</b> לזה י\"ל בד\"א כי הלא ידוע הענין דבחי' חשך התחתון שרשו בבחי' חשך העליון עד רום המעלות שע\"ז כתיב ישת חשך סתרו<sup data-n=\"3332\">136</sup> שכבי' עצמותו מוסתר בו, והגם שהוא בעצמו בחי' אור שהוא בחי' אור עצמותו כו', אבל לגבי המקבלים של כללות ההשתל' שלא יוכל להתקבל בבחי' גילוי ותפיסא כו' נק' בשם חשך כו', והיינו שהתפיסא למקבלים שהוא מושלל מכל מיני גילוי אור וגם גילוי זה הוא לבוש לעצמותו כידוע הענין במ\"א, אשר לזה נק' בשם חשך<sup data-n=\"3333\">137</sup> כו', ומזה דוקא הוא שרש חשך התחתון, וכמבואר בתו\"א במאמר יביאו לבוש מל' ששרש בחי' יש התחתון שהוא בחי' חשך התחתון שרשו הוא בבחי' יש העליון שהוא בחי' סוכ\"ע<sup data-n=\"3334\">138</sup> עד רום המעלות ע\"ש, וא\"כ כשנתברר ונתהפך חשך התחתון לאור והיינו כנ\"ל שבחי' החשך בעצמו יאיר כנ\"ל, אז ממילא נזדכך גם בחי' החשך עליון של בחי' ישת חשך סתרו הנ\"ל שלא יחשיך רק יגלה אור עצמותו כו' וזהו מ\"ש אור חדש על ציון תאיר<sup data-n=\"3335\">139</sup>, והיינו אור חדש לגמרי שלא הי' עדיין בבחי' גילוי אור עדיין אפי' בג\"ע עד רום המעלות שהי' שם רק בחי' זיו תורתן ועבודתן, אבל עצם בחי' האור של תומ\"צ שנתהפך עצם החשך לאור כנ\"ל, עדיין לא הי' בגדר גילוי אור כלל, רק לעתיד יתגלה בעולם התחי' כו' וד\"ל. וזהו כללות התומ\"צ.\n<b>ובזה</b> יובן מ\"ש וארא אל אברהם כו' באל שדי ושמי הוי' לא נודעתי להם<sup data-n=\"3336\">140</sup> כו' שידוע הקושי' כי הלא כמה פעמים נז' אצל האבות בחי' ש' הוי' וכמ\"ש ויאמר",[["3329","133","<b>כשהוא</b>: בתניא: שהוא."],["3330","134","<b>כיתרון האור מן החשך</b>: קהלת ב, יג."],["3331","135","<b>האור ניכר מן החשך</b>: ראה זהר תצוה קפז, סע\"א. תזריע מז, ב."],["3332","136","<b>ישת חשך סתרו</b>: תהלים יח, יב."],["3333","137","<b>אשר לזה נק' בשם חשך</b>: ראה גם לקו\"ת שה\"ש ד, ג."],["3334","138","<b>בתו\"א. . בחי' יש. . שרשו. . בחי' סוכ\"ע</b>: ראה שם מג\"א צ, ב ואילך."],["3335","139","<b>אור חדש על ציון תאיר</b>: נוסח אשכנז ברכת ק\"ש שחרית. ראה גם סידור שחרית סח, ב. מאמרי אדה\"ז תקס\"ז ע' לט. סה\"מ תרכ\"ט ע' קט. וש\"נ. סה\"מ תרל\"ח ע' רט. וש\"נ."],["3336","140","<b>וארא. . ושמי הוי' לא נודעתי להם</b>: וארא ו, ג. ראה פלח הרמון וארא ע' לג ואילך. ע' לח ואילך. ס\"ע מד ואילך."]]],[4801940599,"ה' אל אברם<sup data-n=\"3337\">141</sup> וירא אליו<sup data-n=\"3338\">142</sup> ה' כו' ויבן מזבח לה' הנראה<sup data-n=\"3339\">143</sup> כו' ויבן מזבח לה'<sup data-n=\"3340\">144</sup> סתם, וא\"כ איך אמר ושמי הוי' לא נודעתי להם, רק הלא ידוע התירוץ לזה בד\"ח<sup data-n=\"3341\">145</sup> בשני אופנים הא' שרק הארה מש' הוי' נתגלה להם ולא עצם ש' הוי', ואופן הב' שגם אם נאמר שעצם ש' הוי' נתגלה להם אבל רק מבחי' הוי' דלתתא כו' שאחר הפסיק טעמא אבל בחי' הוי' דלעילא שקודם הפסיק טעמא לא נתגלה להם כידוע הענין על הוי' הוי' ופסיק טעמא בינייהו<sup data-n=\"3342\">146</sup> כו', אשר לזאת ההמשכה שלהם הוא רק להוסיף אור באצי' וכנ\"ל שרק פעל לדחות את החשך אבל לא שיתהפך עצם החשך כמו הבארות כו' והמקלות של יעקב כו' שלא נקלט ונתאחד בהם בחי' קדושה וכנ\"ל אבל בתומ\"צ רוצה לגלות שם הוי' העצמי דלעילא כו' וגם העצם יתגלה כמו שהוא ולא רק הארה ממנו וא\"כ ממילא פעל שעצם החשך של דברים התחתונים וגשמיי' יתהפכו לאור כו', וכמ\"ש ברש\"י לא הודעתי<sup data-n=\"3343\">147</sup> אין כתי' כו' לא ניכרתי להם במדת אמיתית שלי שהוא כמ\"ש אמת הוי' לעולם<sup data-n=\"3344\">148</sup> ובחי' אמת הלא מורה שבחי' א' הוא בחי' אני ראשון ובחי' ת' הוא בחי' אני אחרון<sup data-n=\"3345\">149</sup> ומ\"ם באמצעיתא הכל בהשוואה בלי שום שינוי כלל, היינו שבחי' אור עצמותו יאיר למטה מטה בלי שום הסתר כלל כו', היינו אמיתית ש' הוי' דלעילא כו'.\n<b>וזהו\"ע</b> מ\"ש אבן מאסו הבונים<sup data-n=\"3346\">150</sup> היתה לראש פינה, שידוע הפי' כי בחי' אבן הוא הצירוף א' ב\"ן<sup data-n=\"3347\">151</sup> דקאי על בחי' מל' שנרמזת בשם ב\"ן דוקא בגימט' בהמה כנ\"ל, וגם אפשר לומר כי הלא אבנים נק' אותיות וכמ\"ש בס\"י שני אבנים בונות<sup data-n=\"3348\">152</sup> שתי בתים כו' ובחי' מל' הלא היא בחי' מקור של צירופי אותיות כמאמר מל' פה<sup data-n=\"3349\">153</sup> כו', שמבחי' צירופי אותיות ודבור שבמל' הוא מקור של כל הנבראים בבחי' יש דוקא, וגם בחי' החשך של היש שיסתיר לגמרי עד שיתהווה מזה חשך התחתון כו', וזהו בדרך אפשר שבחי' אבן זה מאסו הבונים שהם בחי' האבות שנק' בונים<sup data-n=\"3350\">154</sup> כידוע, והיינו להשפיל א\"ע לברר החשך התחתון רק שהוסיפו אור באצי' כי הרי הם היו מרכבה לבחי' חג\"ת דאצי' כו' כידוע, אבל דהע\"ה הי' מרכבה דוקא לבחי' המל'<sup data-n=\"3351\">155</sup> וכמ\"ש ויעש דוד שם<sup data-n=\"3352\">156</sup> וכמ\"ש נאום הגבר הוקם ע\"ל<sup data-n=\"3353\">157</sup> שהוא בחי' עולה של תורה<sup data-n=\"3354\">158</sup> עולה של",[["3337","141","<b>ויאמר ה' אל אברם</b>: לך יב, א."],["3338","142","<b>וירא אליו ה'</b>: וירא יח, א."],["3339","143","<b>ויבן מזבח לה' הנראה</b>: לך יב, ז [בדילוג]."],["3340","144","<b>ויבן מזבח לה'</b>: לך יב, ח־ יג, יח [בדילוג]."],["3341","145","<b>בד\"ח</b>: בדרושי חסידות."],["3342","146","<b>הוי' הוי' ופסיק טעמא בינייהו</b>: תשא לד, ו. זהר אד\"ר נשא קלח, רע\"א. ראה הנסמן במאמרי אדה\"א נ\"ך ע' תקעז. תו\"ח בשלח ח\"א קנז, ב הערה 361."],["3343","147","<b>וכמ\"ש ברש\"י לא הודעתי</b>: רש\"י וארא שם."],["3344","148","<b>אמת הוי' לעולם</b>: תהלים קיז, ב [ושם: ואמת]."],["3345","149","<b>אני ראשון. . אני אחרון</b>: ישעי' מד, ו."],["3346","150","<b>אבן מאסו הבונים</b>: תהלים קיח, כב. ראה סידור שער התפלה כא, סע\"ג ואילך."],["3347","151","<b>אבן. . א' ב\"ן</b>: ראה שער היחוה\"א פ\"ז. תו\"ח בא ח\"א קטו, ג. וש\"נ."],["3348","152","<b>שני אבנים בונות</b>: ראה ס\"י פ\"ד, מי\"ב."],["3349","153","<b>מל' פה</b>: ת\"ז בהקדמה יז, א."],["3350","154","<b>האבות שנק' בונים</b>: ראה סידור שער התפלה כא, ד."],["3351","155","<b>דהע\"ה הי' מרכבה. . המל'</b>: ראה פרדס שעה\"כ שכ\"ג, פ\"ד מערכת דוד. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתקט."],["3352","156","<b>ויעש דוד שם</b>: שמו\"ב ח, יג."],["3353","157","<b>נאום הגבר הוקם על</b>: שמו\"ב כג, א [ושם: ונאום — ראה שע\"ת עג, ג הערה 67]."],["3354","158","<b>עולה של תורה</b>: ראה במדב\"ר פי\"ח, כא. הנסמן במאמרי אדה\"א שמות ח\"א ע' רכה."]]],[4801940605,"תשובה<sup data-n=\"3355\">159</sup>, שבחי' עול הוא בבחי' מל'<sup data-n=\"3356\">160</sup> ולזה נק' בזוהר רגלא רביעאה<sup data-n=\"3357\">161</sup> כו', וע\"ז כתיב היתה לראש פינה כו' והיינו לעתיד יתעלה דוקא בחי' מל' שהוא בחי' אבן הנ\"ל ויהי' לראש פינה, והיינו כשיהי' שלימות הבירור אז דוקא בחי' החשך של מדת המל' יתהפך לאור והיינו לאהפכא חשול\"נ דוקא וכנ\"ל ואז היתה לראש פינה כו' היינו שאז דוקא בחי' החשך של בחי' המל' שהיום הוא כח המחשיך ומסתיר ומעלים שיתהווה היש גשמי אבל לעתיד הלא דוקא כל הגילוים של עצמותו יתגלה ע\"י בחי' מל' דוקא וכמאמר ותמלוך אתה ה' לבדך על כל מעשיך, היינו מעשיך שהוא בחי' נשמות בעשי' גשמי' ובגוף גשמי ירגישו בחי' אתה ה' לבדך כו', וזהו א\"ח עט\"ב<sup data-n=\"3358\">162</sup> שקאי על בחי' מל' דוקא כידוע, והיינו כנ\"ל שדוקא בחי' החשך בעצמו יאיר, שזהו יתרון האור מן החשך דוקא כנ\"ל כשנתגלה הפנימי' של החשך ששרשו עד רום המעלות באור עצמותו ית', שזה שייך לומר ג\"כ על בחי' מל' כידוע המאמר בזוהר כ\"ע איהו כתר מל'<sup data-n=\"3359\">163</sup> דוקא, ובחי' כתר עליון הוא עד רום המעלות כו' כידוע במ\"א באריכות.\n<b>ועוי\"ל</b> בד\"א שזהו הטעם הנאמר כי לע\"ל כשיתנו הכוס לברך להאבות לאברהם ליצחק וליעקב לא ירצו לברך כמבואר אבל כשיתנו לדוד יאמר לי נאה לברך<sup data-n=\"3360\">164</sup> ואני אברך, והיינו הטעם כנ\"ל כי דוקא דוד שהי' מרכבה לבחי' מל' היינו לאהפכא חשוכא לנהורא הוא דוקא שייך לבחי' הכוס דלעתיד, שהוא דוקא בחי' אבן שיאיר ע\"ד אבנים טובות כנ\"ל, שזהו כללות התומ\"צ שנעשים דוקא בגוף גשמי ובקלף גשמי ובצמר גשמי, שלעתיד יאירו בכללות נש\"י, וא\"כ היוצא מכ\"ז שעיקר המכוון של כללות התומ\"צ הוא דוקא לאהפכא חשול\"נ שהחשך בעצמו יאיר בבחי' גילוי אור חדש שעומד בהעלם דחשך הגוף גשמי וקלף וצמר גשמי שע\"י נר מצוה ותו\"א נתאחד עם החשך התחתון ומהפכו לאור שזה הי' תכלית המכוון למעלה, ובזה ממילא נשלם הכוונה עליונה שנתאווה להיות לו דירה בתחתונים<sup data-n=\"3361\">165</sup> לו ממש, ובחי' דירה ממש, וכמ\"ש ושכנתי בתוכם<sup data-n=\"3362\">166</sup> כו' בתוכו לא נאמר אלא בתוכם בתוך לב כאו\"א כמאחז\"ל, והיינו כשמטהר מוחו ולבו וממשיך בהם אור התומ\"צ, אז נעשה משכן ומכון לשבתו ית' וכמ\"ש אוה למושב לו<sup data-n=\"3363\">167</sup>, ולזאת ראשית כל צריכים לטהר הגוף ונה\"ב מכל מיני לכלוך ורע וע\"ד דוגמא דירה למלך ראשית צריכים לנקות אותה מכל מיני לכלוך וצואה כו', אשר בלא זה אינה ראוי' לדירת המלך כלל.",[["3355","159","<b>עולה של תשובה</b>: ע\"ז ה, ב."],["3356","160","<b>עול הוא בבחי' מל'</b>: מאו\"א מערכת עול מלכות שמים אות ס\"ה."],["3357","161","<b>רגלא רביעאה</b>: ראה זהר משפטים קז, א. בלק רי, סע\"ב. ז\"ח יתרו לא, ב. זהר בהקדמה ה, ב. ויחי רלז, א."],["3358","162","<b>א\"ח עט\"ב</b>: משלי יב, ד. ראה גם ש\"א כ, ב ובהערה 33."],["3359","163","<b>כ\"ע איהו כתר מל'</b>: ת\"ז בהקדמה יז, א."],["3360","164","<b>לע\"ל כשיתנו הכוס לברך. . לי נאה לברך</b>: ראה פסחים קיט, ב. תו\"ח תולדות קס, א הערה 7. בשלח ח\"א קסא, א. ש\"א לג, ב."],["3361","165","<b>שנתאווה. . דירה בתחתונים</b>: ראה תניא רפל\"ו. לעיל ע' עב. וש\"נ."],["3362","166","<b>ושכנתי בתוכם</b>: תרומה כה, ח. ראה אלשיך שם. לקו\"ש בא כרך כו ע' 83 הערה 49. טור ברקת הל' יו\"ט סתק\"כ (סג, א). טור יהלום יו\"ד סשס\"ג, ס\"ז (ב, ג). מאמרי אדמו\"ר הצ\"צ תרי\"ד ע' ו בשם הה\"מ."],["3363","167","<b>אוה למושב לו</b>: תהלים קלב, יג."]]],[4801940611,"<b>וכ\"ה</b> ע\"ד דוגמא שההכנה למ\"ת שיהי' כל איש ישראלי כלי לבחי' אנכי הוי' אלקיך<sup data-n=\"3364\">168</sup> אלוק' שלך כידוע במ\"א לכאו\"א בפרט דוקא כו', ולזאת צריכים לספור ספירת העומר ומתחלה תנופת העומר והקרבת עומר שעורים ע\"ג המזבח, כי הרי מבואר לעיל כי שעורה הוא מאכל בהמה כו' שיעור ה' כו' דקאי על התלבשות הנה\"א בנה\"ב דוקא וכנ\"ל באריכות, ובחי' נה\"ב כמו שהוא למטה ה\"ה חשך גמור של קליפה וס\"א מצד המדות רעות שבו כידוע, והגם שפנימי' המדות דנה\"ב אינם רע, רק כח המתאווה, ויוכל להתהפך<sup data-n=\"3365\">169</sup> עצם כח המתאווה לאלקות דוקא וכמאמר בכל לבבך בשני יצריך<sup data-n=\"3366\">170</sup> כו', רק שהוא מלביש אותם בבחי' רע מפני הלבושים הצואים של מו\"ד אשר לא לה' המה כו' ואז נעשים המה מדות רעות אשר מסתירים לגמרי על אלקות, ולזאת צריכים לברר ולזכך בחי' הרע שבהם שיהופכו לטוב ולהסיר מהם הלבושים הצואים, ועושים זאת בג' מדריגות של תנופת העומר ע\"י הכהן והקרבתו ואח\"כ ספה\"ע, והיינו שבחי' כהן הוא הנה\"א כי הנשמה נק' בזוהר בת כהן<sup data-n=\"3367\">171</sup> כו' ובעבודה הוא שבחי' נה\"א תניף את הנה\"ב לשרשו, והיינו שתסביר לה אשר שרש נה\"ב גבוה מאד מאד למעלה הרבה משרש נה\"א בחשך העליון כנ\"ל וכידוע ששרש הבהמה שהיא הנה\"ב שרשו נעלה משרש האדם שהוא בחי' נה\"א כו', וכידוע המשל שהאבן הגבוה נופל למרחוק יותר כו', וא\"כ הנפילה של הנה\"ב גדלה מאד שנפלה למטה מטה עד חשך התחתון שמסתיר ומעלים לגמרי, וא\"כ גדלה הרחמנות מאד כמו מאיגרא רמה לבירא עמיקתא<sup data-n=\"3368\">172</sup> כו', וא\"כ ממילא גדל הרחמנות גם על הנה\"א ששרשה חלק אלוק' ממעל<sup data-n=\"3369\">173</sup> ונתלבשה במשכא דחויא<sup data-n=\"3370\">174</sup> בהגוף הגשמי וחשך התחתון שלמטה מטה וא\"כ על שניהם תגדל הרחמנות מאד כו', וזהו בחי' תנופת העומר שעורים שהנה\"א מעלה אותה לשרשה בהסבר הנ\"ל, והלא ידוע כי אין הדינים נמתקי'<sup data-n=\"3371\">175</sup> אלא בשרשן כו', וא\"כ ממילא נתעורר צעקה גדולה בלב נשבר ויצעקו אל ה' בצר להם<sup data-n=\"3372\">176</sup> מן מיצר הגוף ונה\"ב המחשיך לגמרי שמצד זה הרחמנות גדלה על שניהם כנ\"ל, וא\"כ ממילא נולד ונתעורר מזה רצון חזק ותשוקה נפלאה לצאת מן החשך הגס דלמטה ולעלות למעלה מעלה ליכלל בשרשו שהוא בחי' לפני ה' כנ\"ל, ואז נתאחד הרצון דנה\"ב והרצון דנה\"א",[["3364","168","<b>אנכי הוי' אלקיך</b>: יתרו כ, ב. ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' שכב. תו\"א תצוה פב, רע\"ג. לקו\"ת שה\"ש מב, ב."],["3365","169","<b>כח המתאווה ויוכל להתהפך</b>: ראה לקו\"ת חוקת נו, סע\"ג ואילך. סה\"מ תרל\"ח ע' קסג. וש\"נ."],["3366","170","<b>בכל לבבך בשני יצריך</b>: ואתחנן ו, ה ובספרי שם. ברכות נד, א במשנה. ראה מאמרי אדה\"א בראשית ע' שסג ואילך. שערי אורה ו, א הערה 9."],["3367","171","<b>הנשמה נק' בזוהר בת כהן</b>: זהר סבא משפטים צה, א. אגה\"ק סי\"ב."],["3368","172","<b>מאיגרא רמה לבירא עמיקתא</b>: ראה חגיגה ה, ב. רש\"י איכה ב, א. תו\"ח שמות ח\"א ד, ג. וש\"נ."],["3369","173","<b>הנה\"א ששרשה חלק אלוק' ממעל</b>: ראה איוב לא, ב. תניא רפ\"ב. תו\"ח וארא ח\"א נא, ד. וש\"נ."],["3370","174","<b>במשכא דחויא</b>: ראה תניא פל\"א (מ, ב). הנסמן באוה\"ת חוקת כרך ו ע' א'תתצג־ מאמרי אדה\"א נ\"ך ע' תלד."],["3371","175","<b>אין הדינים נמתקי' אלא בשרשן</b>: ראה פע\"ח שער השופר שכ\"ו, פ\"א. תניא עם מ\"מ הגהות והע\"ק לפל\"א. מאמרי אדה\"א דברים ח\"ב ע' תרטו. וש\"נ. תו\"ח וירא קח, ב ובהערה 14."],["3372","176","<b>ויצעקו אל ה' בצר להם</b>: תהלים קז, ו. כח."]]],[4801940616,"בבחי' רצון פשוט לאביו שבשמים שמתחלה הי' ב' רצונות הפכיי' כי רצון של הנה\"א הוא לעלות למעלה ורצון דנה\"ב הוא לירד למטה להחשיך ולהסתיר וכמ\"ש ורוח האדם היא העולה כו' ורוח הבהמה היורדת למטה כו' שהם ב' רצונות הפכיי' ממש, אבל עתה אחרי התנופה כנ\"ל נתאחדו הרצונות דנה\"א ונה\"ב.\n<b>ובזה</b> ממילא יתורץ הקושיא הנ\"ל שמתחלה כתיב והניף הכהן<sup data-n=\"3373\">177</sup> ל' יחיד לפני הוי' לרצונכם ל' רבים, שהכוונה הוא שהמניף הוא בחי' נה\"א, וכידוע הענין אדם כי יקריב מכם קרבן היינו שבחי' אדם שהוא הנה\"א<sup data-n=\"3374\">178</sup> הוא המקריב והמניף לשרשם, אבל אח\"כ נתאחד הרצון דנה\"א ונה\"ב ולזה אמר לרצונכם דקאי על ב' הרצונות כנ\"ל, ואח\"כ ההקרבה ע\"ג המזבח, היינו לזבוח את יצרו<sup data-n=\"3375\">179</sup> בבחי' לב נשבר ונדכה<sup data-n=\"3376\">180</sup> שנתעורר מגודל הרחמנות על שניהם כנ\"ל וכמבואר בזוהר שנק' לב נשבר ע\"ש שנשברה רוח הס\"א, וגם כמ\"ש בתניא בשער התשובה<sup data-n=\"3377\">181</sup> ע\"ד רוח עברה ותטהרם<sup data-n=\"3378\">182</sup> שמפרש כשרוח נשברה עברה מטהר את המוח והלב כו', רק שזה הוא הכל בכלל היינו בחי' ביטול הרצון בכלל ברצון ותשוקה נפלאה ליכלל בשרשו, אבל מוכרח עדיין לברר בפרט כל הרע שישנו בנה\"ב היינו בחי' ז' מדות הרעות שכאו\"א כלולים מכולם שהוא זפ\"ז מספר מ\"ט, ולזה מוכרח אח\"כ לספור ספה\"ע שהוא בחי' בירור הז\"מ בפרט לברר ולזכך כל מדה בפרט דוקא ולהפכה לאלקות, היינו להסיר החשך והרע שלה שבכחם להחשיך ולהסתיר לגמרי הן על עצמה ושרשה, וגם על המדות דנה\"א שלא תאיר כי הגם שאצל הנה\"א האהבה היא טבעיות ועצמיי' כמ\"ש כי נר הוי' נשמת אדם<sup data-n=\"3379\">183</sup> כו' מ\"מ הלא האהבה טבעי' היא נק' אהבה מוסתרת כמבואר בתניא<sup data-n=\"3380\">184</sup> כו', ולזאת צריכים מתחלה להמשיך ריבוי אור לדחות את החשך, שהרי יש יתרון ושליטה וממשלה לאור על החשך לדחותו וכנ\"ל באריכות היינו הפעולה החיצוני' שלו היינו להחשיך לגמרי אפי' על המדות דנה\"א כנ\"ל וזה עושים ע\"י שממשיכים ריבוי אור ע\"י ספה\"ע אשר שרשם בבחי' מ\"ט שע\"ב כו', ושרש שרשם בבחי' שער הנו\"ן [היינו בבחי' מ\"ט שערים הכלולים בשעה\"נ כו' שהוא פנימי' בינה כו'] ששרשו בפנימי' הכתר כו' אשר משם אין יניקה לחיצונים כידוע כי השבירה הי' בז\"ת<sup data-n=\"3381\">185</sup> דשם ס\"ג שבבינה<sup data-n=\"3382\">186</sup> אבל בג\"ר כמו שמיוחדים בבחי' חכמה לא הי' השבירה<sup data-n=\"3383\">187</sup> וכמ\"ש",[["3373","177","<b>והניף הכהן</b>: תיבת הכהן שהיא הוספה על הכתוב — ראה לעיל קרוב להתחלת המאמר: דקאי על הכהן."],["3374","178","<b>אדם כי יקריב. . שהוא הנה\"א</b>: ראה מאמרי אדה\"א הנחות תקע\"ז ע' יד. וש\"נ."],["3375","179","<b>לזבוח את יצרו</b>: ראה סנהדרין מג, ב."],["3376","180","<b>לב נשבר ונדכה</b>: תהלים נא, יט. ראה זהר פינחס רמ, א. תניא פי\"ז. וש\"נ. וראה גם במ\"מ הגהות והע\"ק לשם."],["3377","181","<b>בתניא בשער התשובה</b>: אגה\"ת פ\"ח. ועד\"ז בסה\"מ תרנ\"א ע' קמ."],["3378","182","<b>רוח עברה ותטהרם</b>: איוב לז, כא."],["3379","183","<b>כי נר הוי' נשמת אדם</b>: משלי כ, כז [בהוספת תיבת: כי — ראה גם תו\"ח בשלח ח\"א רכו, א. וש\"נ]."],["3380","184","<b>האהבה טבעי' היא נק' אהבה מוסתרת. . בתניא</b>: פי\"ח. פי\"ט."],["3381","185","<b>השבירה הי' בז\"ת. . שבבינה</b>: ראה גם תו\"ח בראשית כו, סע\"ג. נח מו, ב."],["3382","186","<b>השבירה. . דשם ס\"ג שבבינה</b>: ראה מאמרי אדה\"א דברים ח\"ב ע' שעט. וש\"נ. תו\"ח וארא ח\"א פה, ג. וש\"נ."],["3383","187","<b>בג\"ר. . לא הי' השבירה</b>: ראה ע\"ח שער דרושי הנקודות ש\"ח, פ\"ב. מאמרי אדה\"א דברים ח\"א ע' ט. וש\"נ."]]],[4801940621,"ימותו ולא בחכמה<sup data-n=\"3384\">188</sup> כו', אדרבה כשנמשך הארה משם פועל להעביר יניקת החיצונים ולהסיר החשך שלהם ולדחותו לגמרי כו'.\n<b>ויובן</b> הענין במה שמצינו מאחז\"ל ע\"פ אם רחץ ה' את צואת בת ציון<sup data-n=\"3385\">189</sup> א\"ת אם אלא א ם משל לבן שפחה שטנף פלטין של מלך, אמר המלך תבוא<sup data-n=\"3386\">191</sup> האם<sup data-n=\"3387\">190</sup> ותקנח צואת בנה כו', שהרי אין המלך מצווה לגרשו מפלטין כו', והענין הוא כי שפחה הוא בחי' הנה\"ב שמקבל מבחי' ק\"נ כמבואר בתניא<sup data-n=\"3388\">192</sup>, ובן שפחה הוא בכלל המדות דנה\"ב וכידוע כי המדות נקראים בשם בנים<sup data-n=\"3389\">193</sup>, ובחי' פלטין של מלך הוא כללות הגוף ונה\"ב שבישראל שדוקא מצד הגוף ראוים המה להיות פלטין ודירה לעצמותו וכמ\"ש ושכנתי בתוכם ואחז\"ל בתוכו לא נאמר אלא בתוכם בתוך לב של כאו\"א וזה דוקא הי' עיקר המכוון כידוע כי נתאוה הקב\"ה להיות לו דירה בתחתונים ותחתונים הוא דוקא מצד הגוף ונה\"ב כנ\"ל, רק דוקא כשמטהר מוחו ולבו מכל מיני רע כי אם לאו הלא לא יגורך רע<sup data-n=\"3390\">194</sup> כו', וע\"ד דוגמא למטה עיקר ענין המלוכה הוא דוקא על עבדים שהם בחי' עם וכמאמר אין מלך בלא עם<sup data-n=\"3391\">195</sup> כו', אבל על בנים וב\"ב אפי' יהי' לו הרבה הגם שהם יהיו בבחי' ביטול בתכלית אליו לא יתחשב בחי' מלוכה<sup data-n=\"3392\">196</sup> ולא נק' מלך, וכ\"ה על בחי' נה\"א שנק' בשם בנים אתם כו' בני בכורי<sup data-n=\"3393\">197</sup> הגם שהם בתכלית הביטול וכמאמר ברא כרעא דאבוה<sup data-n=\"3394\">198</sup> כו' מ\"מ לא שייך בחי' מלוכה רק דוקא ע\"י התלבשות הנה\"א בגוף ונה\"ב, שמצד הגוף תוכל להיות בבחי' נפרד מצד ההסתר שלה על הנה\"א, אבל כשתפעול הנה\"א לברר הנה\"ב שיהי' גם בה בחי' ביטול בבחי' אתכפי' לכה\"פ ולקיים כללות התומ\"צ, אז נעשה בחי' דירה ופלטין לעצמותו וכנ\"ל, וזהו דוקא ע\"י בן שפחה כנ\"ל, אבל אם ח\"ו כשטינף פלטין של מלך, דהיינו שהלביש המדות דנה\"ב בלבושים צואים של מחדו\"מ אשר לא לה' המה וכ\"ש כשח\"ו כשנפל ברע גמור של שלש קה\"ט לגמרי שהם בחי' צואה ממש, וא\"כ הרי טינף פלטין של מלך, ואז אינה ראוי' לדירת מלך כלל, וכ\"ש כשנכשל בגאוה וגס רוח ח\"ו שאחז\"ל ע\"ז אין אני והוא יכולין לדור<sup data-n=\"3395\">199</sup> כו', וא\"כ ח\"ו ה\"ה כדוגמא שגירש המלך מדירתו ח\"ו, והעצה לזה אמר המלך תבוא אם ותקנח צואת",[["3384","188","<b>ימותו ולא בחכמה</b>: איוב ד, כא. ראה הנסמן במאמרי אדה\"א דברים ח\"א ע' רצט."],["3385","189","<b>אם רחץ ה'. . בת ציון</b>: ישעי' ד, ד [ושם: בנות]."],["3386","191","<b>משל. . תבוא האם</b>: ראה במדב\"ר פי\"ט, ח. תנחומא חוקת ו."],["3387","190","<b>א\"ת אם אלא אם</b>: פע\"ח שער השבת שי\"ח, פ\"ג. טור ברקת הל' יו\"ט סתק\"כ (סג, סע\"ב). ראה מאמרי אדה\"א ויקרא ח\"ב ע' תקיב. וש\"נ."],["3388","192","<b>הנה\"ב שמקבל מבחי' ק\"נ כמבואר בתניא</b>: פ\"א. פ\"ז."],["3389","193","<b>המדות נקראים בשם בנים</b>: ראה בסמוך הערה 200."],["3390","194","<b>לא יגורך רע</b>: תהלים ה, ה. ראה לקו\"ת במדבר ג, ג."],["3391","195","<b>אין מלך בלא עם</b>: בחיי וישב לח, ל. ראה הנסמן במ\"מ למאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תרלא."],["3392","196","<b>על בנים וב\"ב. . לא יתחשב בחי' מלוכה</b>: ראה שער היחוה\"א פ\"ז."],["3393","197","<b>בני בכורי</b>: שמות ד, כב."],["3394","198","<b>ברא כרעא דאבוה</b>: ראה ע\"ח שער פרקי הצלם שכ\"ד, פ\"א בשם רז\"ל. מאמרי אדה\"א קונטרסים ע' שלט. וש\"נ. תו\"ח ויקהל ח\"ב שצו, א הערה 118."],["3395","199","<b>אין אני והוא יכולין לדור</b>: סוטה ה, א. ערכין טו, ב."]]],[4801940626,"בנה כו', וידוע כי בחי' אם הוא בחי' בינה שנקראת אם הבנים<sup data-n=\"3396\">200</sup> כו' [והגם שהמדות דנה\"ב נק' בן שפחה כנ\"ל, אבל שרש שרשם נמשכו מבחי' בינה וכמאמר בינה מינה דינין מתערין<sup data-n=\"3397\">201</sup> כו'] וא\"כ בתחלה כשממשיך אור הבינה מלמעלה למטה להאיר את החשך, ואח\"כ מעלה את המדות לשרשם ואז ממילא נמתקו הדינים בשרשם כידוע הענין.\n<b>וזהו\"ע</b> ספה\"ע שאו' היום יום, היום הוא בחי' יום הגדול שהיא בחי' שרש המדה כמו שהוא במ\"ט שע\"ב כו' וכנ\"ל, ונמשכת בבחי' יום אחד לעומר שהוא בחי' עומר שעורים מאכל בהמה, שהוא ההמשכה לבחי' מדות דנה\"ב דוקא, ואז ממילא ריבוי אור דוחה החשך של הנה\"ב, וזהו ותקנח צואת בנה דהיינו להסיר הלבושים צואים וכמ\"ש הסירו הבגדים הצואים מעליו<sup data-n=\"3398\">202</sup> ויאמר כו' העברתי מעליך<sup data-n=\"3399\">203</sup> עונך והלבש אותך מחלצות כו', שאמר המלאך ליהושע הכהן גדול, הרי שבחי' עוונות נק' בגדים הצואים כו', וזהו ע\"י המשכת האור גדול שע\"י ספה\"ע כנ\"ל, וע\"ד העבודה היינו כשתסביר הנה\"א לנה\"ב גודל הרחמנות עלי' איך שתוכל להיות פלטין ודירה של מלך מה\"מ הקב\"ה כנ\"ל, והיא בעצמה תגרום ח\"ו לגרשו מן הדירה ח\"ו וא\"כ כשתרגיש זאת אז נתעורר צעקה גדולה ותתמרמר מאד כו', ויצעקו אל ה' בצר להם יתעורר ר\"ר על עוצם הירידה שלה וידוע המבואר בתניא שכשמעורר ר\"ר<sup data-n=\"3400\">204</sup> מלמטה הגם שהרחמים מוגבלים המה מנברא בע\"ג, אבל מזה יתעורר ר\"ר מלמע' שהמה בלתי מוגבלים מדתו של יעקב<sup data-n=\"3401\">205</sup> הנק' בשם בריח התיכון<sup data-n=\"3402\">206</sup> שמבריח מן הקצה אל הקצה היינו משני הקצוות הן להעלותן מקצה התחתון עד רום המעלות ואח\"כ להמשיך מלמעלה למטה מקצה דלעילא כו', וכמו ביצי\"מ דכתי' ואשא אתכם על כנפי נשרים<sup data-n=\"3403\">207</sup> ואביא אתכם אלי היינו בחי' ר\"ר העליונים שהוא בחי' נשרים כי נשר רחמני<sup data-n=\"3404\">208</sup> כידוע פעל להעלות אותם מבחי' מצרים ערות הארץ<sup data-n=\"3405\">209</sup> כו' לבחי' מ\"ת וזהו ג\"כ ספה\"ע, דהלא היום שהוא יום הגדול אפשר לומר שהוא בחי' הר\"ר שמלמעלה וכידוע בכתבי האריז\"ל כי יום בגימט' אל הוי'<sup data-n=\"3406\">210</sup>, ובחי'",[["3396","200","<b>בינה שנקראת אם הבנים</b>: ראה זהר ויחי ריט, א. יתרו פד, א. פה, ב. פרדס שעה\"כ שכ\"ג, פ\"א מערכת אם הבנים. לקו\"ת שמ\"ע פח, ד. שעה\"י קי, ב ובהערה 19. לעיל מאמר ד\"ה להבין ההפרש בין שליו\"ט תר\"ב על יד הערה 108."],["3397","201","<b>בינה מינה דינין מתערין</b>: ראה זהר ויקרא י, סע\"ב. יא, רע\"א. מאמרי אדה\"א דברים ח\"ב ע' שעז. וש\"נ."],["3398","202","<b>הסירו הבגדים הצואים מעליו</b>: זכרי' ג, ד."],["3399","203","<b>ויאמר כו' העברתי מעליך</b>: המשך הכתוב הסירו."],["3400","204","<b>המבואר בתניא שכשמעורר ר\"ר</b>: פמ\"ה."],["3401","205","<b>ר\"ר. . מדתו של יעקב</b>: ראה זהר לך פז, ב. הנסמן במאמרי אדה\"א בראשית ע' קנו."],["3402","206","<b>יעקב הנק' בשם בריח התיכון</b>: ע\"ד תרומה כו, כח. ראה זהר בשלח נא, ב. הנסמן במאמרי אדה\"א שמות ח\"א ע' יט. סה\"מ תרכ\"ט ע' קיז. וש\"נ."],["3403","207","<b>ואשא אתכם על כנפי נשרים</b>: יתרו יט, ד."],["3404","208","<b>נשר רחמני</b>: ראה ירושלמי פאה פ\"א, ה\"א. תנחומא עקב ב. לקו\"ת האזינו עז, ג. עח, א ואילך. מאמרי אדה\"א דברים ח\"ג ע' תתעט. וש\"נ. תו\"ח בשלח ח\"א ריג, ב ובהערה 213."],["3405","209","<b>מצרים ערות הארץ</b>: מקץ מב, ט. יב. קה\"ר פ\"א, ד (בסופה). ע\"ח שער ציור עולמות שמ\"ג, פ\"א."],["3406","210","<b>יום בגימט' אל הוי'</b>: ראה פע\"ח שער ספה\"ע שכ\"ב, פ\"ו. מאמרי אדה\"א ויקרא ח\"א ע' שז. וש\"נ."]]],[4801940631,"אל הלא היא מדה ראשונה של יגמה\"ר<sup data-n=\"3407\">211</sup>, שזה נתעורר מהתעוררות רחמים שמלמטה כו'.\n<b>וזהו</b> פי' הא' של וספרתם ל' מספר, שבבחי' מספר הנ\"ל שמעורר אור גדול מלמעלמ\"ט וגם הר\"ר שמלמטלמ\"ע, ה\"ה מסיר ודוחה החשך ולבושי' צואים של הגוף ונה\"ב כנ\"ל באריכות, וא\"כ ממילא יבא לפי' הב' של וספרתם ל' אבן ספיר ובהירות, היינו שעצם החשך דנה\"ב יתברר ויזדכך ויהי' כלי לבחי' תומ\"צ, שהוא בחי' אתהפכא חשוכא לנהורא, היינו שעצם החשך יאיר בגילוי אור ע\"י תומ\"צ שיעשה בגוף גשמי שהדוגמא לזה הוא בחי' אבן ספיר כנ\"ל שנקלט ונתאחד האור בעצם האבן שהוא החשך היותר תחתון כנ\"ל באריכות, שהוא יקר המציאות שמזה עושים עטרה למלך, ובחי' זאת דפי' הב' של וספרתם נעשה ממילא מצד הספירה שפועל לדחות החשך ולהסיר הלבושים הצואים וכנ\"ל תבוא אם ותקנח צואת בנה כו', אז ממילא נתהפך עצם החשך והרע של נה\"ב לאור וטוב והיינו שיתגלה האור שמלובש בהעלם בהחשך התחתון דוקא ששרשו בחשך העליון כנ\"ל, שיהי' מעשים טובים ומאירים כמו האבן טוב, וכמבואר בתניא פ\"ט וז\"ל הזהב וכמ\"ש בע\"ח שער נ' פ\"ג בשם הזוהר שהרע נהפך להיות טוב גמור כמו יצר טוב ממש בהסיר הבגדים הצואים ממנו שהם תענוגי עוה\"ז שהוא מלובש בהם עכ\"ל, וכן בפ' יו\"ד מבואר וז\"ל כי הנה צ\"ג שנהפך הרע שלו לטוב כו' הוא ע\"י הסרת הבגדים הצואים לגמרי מהרע דהיינו למאוס מאד בתענוגי עוה\"ז להתענג בם כו' עכ\"ל, הרי מבואר שרק בהסיר ממנו הלבושים הצואים לגמרי שזה פועלים ע\"י ספה\"ע, ובתחלה התנופה לשרשו וההקרבה ע\"ג המזבח שהוא ביטול הרצון בכלל כנ\"ל ואח\"כ הבירור בפרט בז\"מ ובכל מדה בפרט וכמאחז\"ל מצוה לממני יומא ומצוה לממני' שבועות<sup data-n=\"3408\">212</sup> שזהו ע\"י המספר כנ\"ל אז ממילא נתהפך עצם הרע לטוב שזהו פי' הב' של וספרתם בחי' אבן ספיר ע\"י קיום התומ\"צ שנתאחד היד גשמי שמחלק הצדקה, והרגל שמהלך לדבר מצוה וכ\"ש בעסק התורה שנעשה יחוד נפלא ועצום שאין כמוהו כמבואר בתניא<sup data-n=\"3409\">213</sup>, עד שלעתיד תקבל הנשמה תענוג גדול, כשתרגיש האור הגדול שהאיר בגוף גשמי בעת עשיית המצוה בעוה\"ז דוקא וכמבואר לעיל על פי' של אדמו\"ר הזקן נבג\"מ על מאמר חז\"ל שכר מצוה מצוה כו' שזהו עיקר הקבלת שכר כנ\"ל באריכות.\n<b>ועתה</b> י\"ל פי' הג' של וספרתם לכם שתמשיכו לכם להיות בגדר קדושת הספי' עליונות שנז' פי' זה בלק\"ת<sup data-n=\"3410\">214</sup> שהוא ג\"כ ע\"י ספה\"ע דוקא, יש להקדים ענין שבנוסח הרבש\"ע שאחר ספה\"ע מבקשים ולטהרנו ולקדשנו בקדושתך העליונה, מהו בקדושתך העליונה דוקא, וגם משמע שבספה\"ע פועלים זאת וכלשון",[["3407","211","<b>אל. . מדה ראשונה של יגמה\"ר</b>: ראה זהר אד\"ר נשא קלא, ב. לקו\"ש אלול כרך ד ע' 1348 ואילך."],["3408","212","<b>מצוה לממני יומא ומצוה לממני' שבועות</b>: ראה מנחות סו, א. ראה גם לעיל מאמר ד\"ה וספרתם תרי\"ט על יד הערה 102. פלח הרמון יתרו ע' רמה."],["3409","213","<b>בעסק התורה. . כמבואר בתניא</b>: פ\"ה."],["3410","214","<b>שנז' פי' זה בלק\"ת</b>: ראה לקו\"ת אמור כאן לו, ב."]]],[4801940636,"שבזכות ספה\"ע שספרנו יתוקן כו' איך פועלים זה בספה\"ע, ולהבין כל הנ\"ל ילה\"ק מתחלה להבין מ\"ש בתניא באגה\"ק<sup data-n=\"3411\">215</sup> במאמר איהו וחיוהי חד כו', שמבואר שם אפילו על נשמות דאצי' שאפשר שלא נשתנה מהותן אפי' כשיורדים בגוף גשמי כו', וכ' שם עוד וז\"ל אך אינן אלקות ממש לברוא יש מאין מאחר שכבר יצאו ונפרדו מהכלים די\"ס שבהן מלובש הקו מאא\"ס שהאור הוא מעין המאור הוא מהוע\"צ של המאציל ב\"ה כו' עכ\"ל.\n<b>ולהבין</b> הענין הנה מתחלה י\"ל ענין יתרון מעלה של נשמות דאצי' על נשמות דבי\"ע, שמבואר בתניא שלא נשתנית מהותה, והענין הוא בד\"כ כי יש כמה מדריגו' בבחי' ביטול לאא\"ס ב\"ה, יש בחי' ביטול שנק' בשם ביטול היש, והיינו שהוא נראה לבחי' יש ומציאות, רק שמרגיש שהיש שלו בטל לגבי אא\"ס שהוא בחי' אין המחייהו ומהוה אותו מאין ליש, ויש בזה גופא ב' מדריגו', הא' שאינו מרגיש רק איכות התהוות היש מאין, אבל עצם בחי' אין לא ישיג כלל והיינו הרגשת האין איך שנתעלם ביש, וע\"ד דוגמא הנפש המחי' הגוף שגם שמרגיש שבכל אבר פרטי החיות הוא מהנפש, אבל אינו מרגיש רק מציאת הדבר, ולא מהות החיות כלל וזהו בחי' ביטול של מלאכים דיצי' שאו' ברוך כבוד ה' ממקומו שנמשך ומחי' ומהוה מאין ליש, ומצד זה מתפעלים ברעש גדול כמאמר והאופנים<sup data-n=\"3412\">216</sup> וחיות<sup data-n=\"3413\">217</sup> ברעש גדול מתנשאים, אבל לא ישיגו בחי' קדוש, היינו איך שהאין אלקי קדוש ומובדל מבחי' יש, וכמ\"ש ואתה מחי' את כולם<sup data-n=\"3414\">218</sup> וצבא השמים לך משתחוים דהא בהא תלי' לפי שמרגישים שהאור אלקי מחי' ומהוה אותם בכל עת ובכל רגע וממילא בטלים בתכלית לאור האלקי, אבל אחרי התהוותם ה\"ה בחי' יש ומציאות, א\"כ ה\"ה רק מרגישים האין אלקי שנתעלם בבחי' יש אבל בחי' שרפים דבריאה<sup data-n=\"3415\">219</sup> הם משיגים בחי' קדוש כו' היינו עצם האין אלקי שהוא קדוש ומובדל ומרומם מבחי' היש, והטעם כידוע דבחי' בריאה נק' בריאה מאין ליש וכיון ששם הוא ראשית הגילוי מאין ולזאת מאיר שם עצם האין אלקי כמו שהוא מרומם וקדוש מבחי' היש, ולזאת נתגלה אצלם שאגה וכלות הנפש לצאת מגדר הכלי ויש שלהם ליכלל בבחי' עצם האין אלקי, וז\"ש ארי שואג ושור גועה<sup data-n=\"3416\">220</sup> דקאי על ארי' ושור שבמרכבה דבריאה ששואגים בכלות הנפש ליכלל בעצם האין, וזהו שרפים עומדים ממעל לו<sup data-n=\"3417\">221</sup> כו' כידוע הענין והפי' ע\"ז כמו שאמר הבעש\"ט ז\"ל מקום רצונו<sup data-n=\"3418\">222</sup> כו' שם הוא כולו כמבואר במ\"א.",[["3411","215","<b>בתניא באגה\"ק</b>: ס\"כ (קל, א ואילך)."],["3412","216","<b>מלאכים דיצי'. . והאופנים וחיות</b>: ראה גם תו\"ח בא ח\"א צז, ג. וש\"נ. סה\"מ תרל\"ד ע' רמד."],["3413","217","<b>ברוך כבוד. . והאופנים וחיות</b>: יחזקאל ג, יב. ראה חולין צב, רע\"א ובתוד\"ה ברוך."],["3414","218","<b>ואתה מחי' את כולם</b>: נחמי' ט, ו."],["3415","219","<b>שרפים דבריאה</b>: ראה לקו\"ת להאריז\"ל ישעי' פ\"ו. ביאוה\"ז בשלח לט, ד. מאמרי אדה\"א דברים ח\"א ע' רסג. וש\"נ. שע\"ת סב, א הערה 10."],["3416","220","<b>ארי שואג ושור גועה</b>: ראה גם מאמרי אדה\"א במדבר ח\"ב ע' תתלה. ע' שצח-ט. אוה\"ת ברכה ע' א'תתקכה. סה\"מ עת\"ר ע' רלה."],["3417","221","<b>שרפים עומדים ממעל לו</b>: ישעי' ו, ב. ראה גם לעיל ע' רכה ובהערה 50."],["3418","222","<b>שא' הבעש\"ט ז\"ל מקום רצונו</b>: ראה גם לעיל ע' לז. ע' רכה. לקמן מאמר ד\"ה אם בחוקותי הג' ובהערה 50. ד\"ה והתהלכתי תרט\"ו על יד הערה 116. אוה\"ת נשא — כרך ד — ע' א'תמב [ובמהדורת תשנ\"ה כרך א ר\"ע 86] והוא הנחת ר' הלל מש\"פ נשא תר\"י יודפס בע\"ה בספרו פלח הרמון בפ' נשא. פלח הרמון שה\"ש קיג, א. קכח, ב. לקוטי ביאורים לשעה\"י קנב, ב ובהערה 2. כתר שם טוב קה\"ת מהדורת תשנ\"ט סמ\"ח. וש\"נ. וראה גם מאמרי אדה\"ז הקצרים ס\"ע קפט ואילך (בשם הר\"א — המלאך). שיחת חגה\"ש תשי\"'ד ס\"כ (תורת מנחם — התוועדויות חי\"ב ע' 37)."]]],[4801940639,"<b>אבל</b> מ\"מ גם הביטול שלהם נק' בשם ביטול היש, והיינו כי מצד עצמם ה\"ה בחי' נבראים, ויש שלהם חומר של ב' יסודות אש ורוח<sup data-n=\"3419\">223</sup> רק מפני שמשיגים עצם האין אלקי איך שהוא קדוש ומובדל רוצים לצאת מגדר הכלי וחומר שלהם וא\"כ מרחוק הוי' נראה להם<sup data-n=\"3420\">224</sup>, ואדרבה מזה גופא שיש להם תשוקה ושאגה ליכלל באין אלקי' מוכרח לומר שרחוקים בעצם וכידוע כי צמאון ותשוקה לדבר הוא דוקא כשרחוק ממנו הדבר וכמ\"ש צמאה לך נפשי בארץ צי' ועיף<sup data-n=\"3421\">225</sup>, כשרחוק מן המים דוקא, והיינו כי הלא פרסא מפסיק בין אצי' לבריאה, שהפרסא מסתיר על עצם האין אלקי כמ\"ש בבחי' אצי' כו', אשר לזאת נק' בשם בהמות וחיות כמ\"ש פני ארי' פני שור<sup data-n=\"3422\">226</sup> כו' י\"ב בקר כו' והים עומד עליהם מלמעלה דקאי על בחי' מל' דאצי' כו' הוא בחי' מקיף מלמעלה, וא\"כ הרי הוא ג\"כ בחי' ביטול היש, שהוא בחי' דעת תחתון של הנבראים מאין ליש<sup data-n=\"3423\">227</sup> כידוע, ועוד זאת הרי האין שישיגו הוא רק בחי' אין של היש היינו שהוא מקור ליש, שהוא בחי' מל' דמל' דאצי' שנעשה כתר לבריאה שהיא הארה דהארה מעצם האין האלקי כמ\"ש בבחי' אצי', וכמ\"ש כי נשגב שמו לבדו הודו על ארץ ושמים, וידוע כי שמו הוא בחי' מל' דאצי' כמ\"ש בבחי' אצי' נשגב ומרומם מבחי' בי\"ע רק הודו הארה דהארה מאיר אחר הפרסא שהוא בחי' האין שנעשה מקור ליש שנק' בשם מל' כל עולמים<sup data-n=\"3424\">228</sup> וא\"כ עצם האין האלקי כמו שהוא בבחי' אצי' הוא מרומם אצלם לגמרי שהוא בחי' ד\"ע איך דקמי' כו' מיש לאין<sup data-n=\"3425\">229</sup> שהפי' הוא שבחי' אין אלקי הוא המציאות אמיתי ולמטה הוא בחי' אין וכלא כו' כמבואר במ\"א באריכות, וא\"כ הביטול שלהם נחשב בשם ביטול היש לגבי ביטול דאצי' ששם מאיר עצם האין אלקי איך שהוא למעלה אפי' להיות בחי' מקור ליש כו' וד\"ל.\n<b>אבל</b> בחי' ביטול דנשמות דאצי' שנק' בשם זרע אדם<sup data-n=\"3426\">230</sup> ובחי' בנים אתם כו', והיינו לפי שלידתם הוא למעלה מבחי' פרסא וכמ\"ש בנים אתם לה' אלקיכם, שידוע הפי' בכהאריז\"ל<sup data-n=\"3427\">231</sup> שנולדו מבחי' יחוד זו\"נ דאצי' וא\"כ כיון שהלידה",[["3419","223","<b>חומר של ב' יסודות אש ורוח</b>: ראה מאמרי אדה\"א בראשית ע' קיב. וש\"נ. קונטרסים ע' רצב. וש\"נ."],["3420","224","<b>מרחוק הוי' נראה להם</b>: ע\"פ ירמי' לא, ב."],["3421","225","<b>צמאה. . בארץ צי' ועיף</b>: תהלים סג, ב [בדילוג]."],["3422","226","<b>פני ארי' פני שור</b>: ראה יחזקאל א, י."],["3423","227","<b>דעת תחתון. . מאין ליש</b>: ראה בסמוך הערה 229."],["3424","228","<b>מל' כל עולמים</b>: תהלים קמה, יג."],["3425","229","<b>ד\"ע. . מיש לאין</b>: ראה מאמרי אדה\"א ויקרא ח\"א ע' רסב. וש\"נ. תו\"ח בראשית יח, ג ובהערה 11."],["3426","230","<b>דנשמות דאצי'. . זרע אדם</b>: ראה תו\"א ותו\"ח ר\"פ משפטים. פלח הרמון פקודי ע' שלט ואילך. מאמר ד\"ה כמים הפנים תר\"ם ובהנסמן לשם."],["3427","231","<b>בנים. . בכהאריז\"ל</b>: ראה ע\"ח שער המלכים שי\"א, רפ\"ו. פע\"ח שער הק\"ש ש\"ח, פ\"ז. פי\"ב."]]],[4801940642,"וההתגלות שלהם הוא למעלה מהפרסא א\"כ הפרסא אינה מסתרת לפניהם כלל, וא\"כ מרגישים עצם האין אלקי כמ\"ש באצי' שהוא בחי' אין בעצם, ולא אין של היש כנ\"ל, וא\"כ מרגישים איך שהאין הוא הוא אמיתת המציאות וכולא קמי' כל\"ח<sup data-n=\"3428\">232</sup>, שהוא הרגשה דבחי' ד\"ע מיש לאין היינו שהאין אלקי הוא בחי' יש ומציאות, ולמטה הוא אין וכלא, וגם מרגישים זאת בבחי' ראי' מקרוב ולא בבחי' השגה מרחוק וכפי' אדמו\"ר הזקן נבג\"מ על מאמר חז\"ל איזהו חכם<sup data-n=\"3429\">233</sup> הרואה את הנולד, שחכם הוא בחי' נשמה דאצי' רואה מקרוב איך שנולד מאין ליש<sup data-n=\"3430\">234</sup> בבחי' ראי' מקרוב וא\"כ היא מרגשת עצם האין אלקי, וממילא הביטול הוא ביטול עצמי בבחי' ביטול במציאות ממש, ולא ביטול היש שהרי אין היש נראה להם בבחי' יש כלל רק כלא וכאין ממש כו', וא\"כ הביטול שלה הוא כעצם וגם ביטולם תמידי שהרי הם נק' בזוהר בשם נוני ימא רבא כמו הדגים שמובלעים תמיד בים ואינם יכולים לפרוש ממנו כלל, כך בחי' נשמות דאצי' ביטולם לא נפסק אפי' רגע כי הגוף אינו מסתיר אצלם, וכמו מ\"ש וידגו לרוב בקרב הארץ<sup data-n=\"3431\">235</sup>, היינו שגם בקרב הארץ שהוא התלבשות בגוף גשמי יהי' במדריגת דגים שבים בבחי' ביטול במציאות כו'.\n<b>ולקרב</b> אל השכל קצת ענין ההפרש בין ביטול היש לביטול במציאות, יובן ע\"ד דוגמא ממלכותא דארעא, כשאחד מתבונן התפשטות גדולת המלך על מדינות ארצות רבות והכל יראים ומפחדים לפניו כי בידו להרים ולהשפיל כו', ומחמת זה גם הוא ירא ומפחד ומבטל ומניח עצמותו להיות בטל בתכלית לרצון המלך ולגזרותיו שלא לעבור גזירת המלך אפי' כקוש\"י וא\"כ הוא ביטול עצמי, מ\"מ הביטול הזה נק' בשם ביטול היש, כי הרי הוא בחי' יש ומורגש בביתו כיון שהוא רחוק מהמלך, ואדרבה יכול להיות נפרד לגמרי שלא לשמוע לרצון המלך, רק שמניח ומבטל א\"ע וא\"כ הרי הוא רק ביטול היש, ועוד יש פי' בבחי' ביטול היש היינו כי לבד שהוא בעצמו בחי' יש, אלא שגם הביטול שלו הוא בבחי' יש ומורגש בנפשו, שהרי הביטול נסתעף מן ההשגה של התפשטות גדולתו, וההשגה הלא היא מורגשת בנפשו, וא\"כ מוכרח שגם הביטול הנתפשט מההשגה הוא ג\"כ בבחי' יש ומורגש בנפשו, רק זהו דוקא כשהוא רחוק מן המלך והביטול הוא רק מן ההשגה כנ\"ל, אבל כשנתקרב בהיכל המלך, ורואה עצם המלך ויקר תפארת גדולתו בהיכלו אז נתבטל לגמרי עד שאינו יכול לעמוד ונופל בפישוט ידים ורגלים ומשתחווה ונופל על פניו [און ווערט צו רירט לגמרי] עד שאינו יכול לדבר אלא א\"כ המלך נותן לו רשות לדבר וא\"כ ה\"ה בחי' ביטול במציאות מכל וכל וגם הביטול גופא אינו מורגש בנפשו, והטעם לזה הוא כי ההפרש בין מרחוק לבחי' קרוב בהיכל המלך, הוא בב' ענינים הן מצד המקבל והן מצד המשפיע, והיינו הביטול דמרחוק שמתבונן בבחי' התפשטות מלכותו כו' כנ\"ל הרי אינו מרגיש רק ההתפשטות של המלך שאינה",[["3428","232","<b>וכולא קמי' כל\"ח</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה פ\"א (ז, רע\"א). מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["3429","233","<b>איזהו חכם</b>: תמיד לב, א."],["3430","234","<b>הנולד. . מאין ליש</b>: ראה תניא פמ\"ג. לעיל ע' קנב ובהערה 38."],["3431","235","<b>וידגו לרוב בקרב הארץ</b>: ויחי מח, טז."]]],[4801940644,"ערוך לגבי עצם הרוממות בחדרי היכלו, שהוא ההפרש מצד המשפיע, וגם מצד המקבל נתקבל הביטול בכלי ההשגה במוחו ולא בבחי' ראי', שההשגה מורגשת כו' וא\"כ גם הביטול מורגש כנ\"ל, אבל כשנתקרב בהיכל המלך הרי רואה עצם רוממות המלך ולא ההתפשטות, גם הוא מקבל זאת בכלי הראי' דעין מקרוב, ובחי' ראי' דעין יש בכחה למשוך פנימי' הנפש בהדבר שרואה, וכידוע הענין על מאחז\"ל העין רואה ולב חומד<sup data-n=\"3432\">236</sup> כו', ולזה הביטול הוא ג\"כ ביטול עצמי בלי שום מורגש.\n<b>וכ\"ה</b> ע\"ד דוגמא ההפרש בין נשמות ומלאכים דבי\"ע שההשגה שלהם הוא רק בבחי' אין של היש שהוא בחי' מל' דמל' דאצי' אחר הפרסא, וא\"כ הוא רק ההתפשטות דעצם המל' כמו שהיא בבחי' אצי', וגם מקבלים זאת בבחי' השגה, וכמאמר אימא עלאה מקננא בכורסייא<sup data-n=\"3433\">237</sup> כו', ולזאת הביטול הוא מורגש, אבל נשמות דאצי' שרואים מקרוב עצם האין אלקי כמו שהוא למעלה מהיות מקור לבי\"ע כו', וגם מקבלים זאת בכח הראי' מקרוב, איזהו חכם הרואה כו', ולזאת פועל בחי' ביטול במציאות מכל וכל מאחר שנתקרב כנ\"ל, וזהו\"ע שלא נשתנית מהותה בגוף גשמי כי הגוף אינו מסתיר כלל, אבל מ\"מ אפי' בחי' הביטול דנשמות דאצי', אין זה רק בחי' ביטול המהות מכל וכל, אבל לא בחי' יחוד כמו הספי' שבהם מאיר בחי' יחוד עם אא\"ס וכמאמר איהו וחיוהי חד<sup data-n=\"3434\">238</sup> איהו וגרמוהי חד בהון, ובחי' יחוד הוא יתרון מעלה באין ערוך לגבי ביטול, אפי' לבחי' ביטול במציאות הנ\"ל.\n<b>והענין</b> הוא כי בחי' ביטול ה\"ה בעצם בחי' מהות בפ\"ע לגמרי שהרי אינו מתאחד עם המלך רק שמבטל מהותו מכל וכל, אבל כשבא לבחי' מהותו כבתחלה כמו כשנתרחק מהמלך אז הלא נתעלם אותו הביטול שהי' בעת עמדו בהיכל כו', וגם הדוגמא לדגים שבים שגם שהם מובלעים במקורם אך מ\"מ לא נתאחדים בעצם המים כי מים אינם דגים ודגים אינם מים כו', אבל בחי' יחוד של הע\"ס עד<sup data-n=\"3435\">239</sup> אא\"ס, הוא בחי' יחוד ממש ע\"ד דוגמא אברי הגוף עם הנפש בשעת מעשה, שהאבר הוא בעצם מהותו, ופועל פעולתו היינו היד בכח התנועה שלו בשעת מעשה גופא, ומ\"מ הם בתכלית היחוד לגבי רצון הנפש אפי' כקוש\"י, שלא נפרד היד מרצון הנפש ומתנענע כפי רצון הנפש, והלא זהו בחי' יחוד ממש, והטעם לזה כי הלא מי הוא המנענע היד הלא כח הנפש ממש כי בלא כח הנפש הלא הוא מוטל כאבן דומם כו', וא\"כ כיון שעצם הנפש הוא המנענע אותו לזאת לא נפרד מהנפש כלל כו' וד\"ל.\n<b>וכ\"ה</b> ע\"ד דוגמא למעלה יחוד הכלים דאצי' עם עצמי' אא\"ס ב\"ה הוא בחי' יחוד ממש ולא בחי' ביטול כנ\"ל אשר ע\"ז נק' בשם גופין תקינת לון בזוהר חסד דרועא ימינא<sup data-n=\"3436\">240</sup> כו', והיינו הראי' שמביא בתניא שהרי בכחם לברוא יש מאין, ולשונו",[["3432","236","<b>העין רואה ולב חומד</b>: רש\"י שלח טו, לט. ראה הנסמן במאמרי אדה\"א דברים ח\"ב ע' תרפד־ שמות ח\"א ע' כ. סה\"מ תרל\"ב ח\"ב ע' תקצח."],["3433","237","<b>אימא עלאה מקננא בכורסייא</b>: ת\"ז ת\"ו כג, א. ראה מאמרי אדה\"א דברים ח\"א ע' רסב. וש\"נ. קונטרסים ע' תכג. וש\"נ."],["3434","238","<b>איהו וחיוהי חד</b>: ראה ת\"ז בהקדמה ג, ב."],["3435","239","<b>עד</b>: כנצ\"ל: עם."],["3436","240","<b>גופין. . חסד דרועא ימינא</b>: ת\"ז בהקדמה יז, א."]]],[4801940646,"הזהב בתחלת המאמר הנ\"ל שהן אלקות לברוא יש מאין<sup data-n=\"3437\">241</sup> כמו הא\"ס כו' עכ\"ל ולכאורה הלא באמת הכח לברוא יש מאין הוא כח עצמותו ממש וכמבואר במאמר הנ\"ל וז\"ל ולכן הוא לבדו בכחו ויכולתו לברוא יש מאין ואפס המוחלט ממש בלא שם עילה וסיבה אחרת<sup data-n=\"3438\">242</sup> עכ\"ל, א\"כ הרי הכח לברוא יש מאין הוא מבחי' עצמותו ית', רק שהפי' הוא שהכח דבחי' הוא לבדו מתלבש בבחי' חסד דרועא ימינא בכדי להוות מאין ליש מחנה מיכאל בבריאה שעבודתו באהבה כו' וכן כח דהוא לבדו מתלבש ומתאחד בבחי' גבו' דרועא שמאלא דאצי' בכדי להוות מחנה גבריאל בבריאה שעבודתו ביראה כו', וזהו איהו וגרמוהי חד ממש והוא ע\"ד דוגמא הנ\"ל בבחי' אברי הגוף שכיון שעצם הנפש הלא הוא פועל התנועה בכח היד, ולזאת כלי היד מתאחד עם כח הנפש שמתלבש בו שע\"י שניהם כח הנפש והאברים נק' בשם אדם, וכידוע שעל הנפש כמו שהוא פשוט לא שייך לקרותו בשם אדם<sup data-n=\"3439\">243</sup>, וגם הוא רחוק בתכלית מכל הפעולות של הגוף כו' כידוע, וגם עצם כלי הגוף לא יתכן עליהם שם אדם, רק דוקא ע\"י התאחדותם יחדיו דוקא כנ\"ל אז שייך כל הפעולות גשמיי' וגם יתכן לקרות שם אדם כו' כ\"ה ע\"ד דוגמא למעלה על עצמות אא\"ס ב\"ה הלא אינו מקור ולא מקור למקור להשתל', וכמאמר ולאו מכל אינון מדות כלל<sup data-n=\"3440\">244</sup> כו', רק דוקא ע\"י התלבשות והתאחדות עצמו' אא\"ס עם ע\"ס בבחי' יחוד האור ויחוד הכלים, וזהו איהו וחיוהי חד איהו וגרמוהי חד, ולזה נק' על הכסא כו' כמראה אדם<sup data-n=\"3441\">245</sup> כו' שנק' ע\"ש פעולותיו כו', להוות בחי' אדם דהשתל' כמבואר במ\"א באריכות.\n<b>וזהו\"ע</b> הנ\"ל שנשמות דאצי' נפרדו מהקו שמדריגתם אינם בבחי' יחוד כנ\"ל, רק בבחי' ביטול במציאות כו', וזהו הטעם שנאמר בת\"ז במאמר פתח אליהו לבושין תקינת לון<sup data-n=\"3442\">246</sup> דמנייהו פרחין נשמתין לבני נשא כו', והיינו כי שרשי הנשמות הם מבחי' לבושין של ע\"ס, שהלבוש ידוע שאינו מתאחד עם נפש האדם כמו הגוף שהרי יכול לפושטו וללבשו, הגם שהעצם מתלבש בו ונק' לבוש של העצם כו', אבל לא בבחי' יחוד כו', אבל זהו רק מצד עצם הנשמה כמו שהיא מצד עצמה אבל כשיורדת בגוף גשמי ופועלת לברר ולזכך הגוף גשמי ונה\"ב כנ\"ל ע\"י ספה\"ע בכל המדריגות כנ\"ל מתחלה התנופה וההקרבה והמספר כנ\"ל בפרט, עד שפועלת בגוף בחי' אתכפיי' היינו להסיר החשך של נה\"ב ובחי' לבושים הצואים כנ\"ל, וממילא בא לבחי' אתהפכא חשוכא לנהורא, והיינו כנ\"ל שהחשך בעצמו יאיר בבחי' גילוי אור חדש שזהו ע\"י קיום התומ\"צ בשלימות, שזהו פי' הב' של וספרתם כנ\"ל לשון אבן ספיר, שהאבן טוב יאיר, והוא בחי' מעשים טובים כנ\"ל דהיינו שמאירים בבחי' אור כי טוב כו' כנ\"ל, הלא אז הגוף נעשה פלטין של מלך ממש היינו שעצמותו ומהותו",[["3437","241","<b>בתניא. . שהן אלקות לברוא יש מאין</b>: אגה\"ק ס\"כ (קכט, רע\"ב)."],["3438","242","<b>ולכן הוא לבדו. . אחרת</b>: שם (קל, רע\"ב)."],["3439","243","<b>הנפש. . לא שייך לקרותו בשם אדם</b>: ראה גם סה\"מ תרל\"ח ע' שכב ובהערה 64."],["3440","244","<b>ולאו מכל אינון מדות כלל</b>: ראה ת\"ז בהקדמה יז, ב."],["3441","245","<b>על הכסא כו' כמראה אדם</b>: ראה יחזקאל א, כו. ראה גם לעיל ע' קסה."],["3442","246","<b>בת\"ז. . לבושין תקינת לון</b>: בהקדמה יז, א."]]],[4801940648,"ית' ידור בו, וגם התאחדות ממש ע\"י עסק התורה כנ\"ל בשם התניא שנעשה יחוד נפלא ועצום שאין כמוהו כו' כנ\"ל, וא\"כ הרי נתעלית הנשמה והגוף באין ערוך עד שנתאחדו ממש בבחי' עצמו' אא\"ס ב\"ה בבחי' יחוד ולא במדריג' ביטול בלבד\nוזהו ירידת הנשמה בגוף היא צורך עלי'<sup data-n=\"3443\">247</sup> כידוע, שהוא תכלית עלי' כי הלא שרשה הוא רק מבחי' לבושין של הע\"ס כנ\"ל אבל מצד קיום התומ\"צ באתה למדריגת יחוד בחי' גופין, וזהו הענין הידוע בזוהר לאשתאבא בגופא דמלכא<sup data-n=\"3444\">248</sup>, היינו שנשתאבת ונכללת בגדר הע\"ס שנק' גופא דמלכא כנ\"ל בבחי' יחוד ממש, שהוא דוקא מצד קיום התומ\"צ בגוף גשמי וע\"י ההכנה לזה בספה\"ע כנ\"ל, וא\"כ זהו פי' הג' של וספרתם לכם היינו שתמשיכו לכם בגדר קדושת הספי' ממש, שהוא בחי' יחוד ולא רק בחי' ביטול שהוא בחי' כח עצם הנשמה מצד עצמה כנ\"ל, רק ההכנה לזה הוא ע\"י ב' פי' דוספרתם בחי' מספר ובחי' בירור וזיכוך שזהו בחי' אבן ספיר וכנ\"ל, רק ששלימות הגילוים יתגלה לעתיד דוקא ובעולם התחי' כשיהי' עיקר קבלת שכר של המצות שהנשמה תקבל האור מהגוף דוקא כנ\"ל.\n<b>וזהו</b> בקרבך קדוש<sup data-n=\"3445\">249</sup> בקרבך ממש כו', והוא ע\"ד מאחז\"ל עתידים צדיקים שיאמרו לפניהם קדוש, שידוע הפי' של אדמו\"ר הזקן<sup data-n=\"3446\">250</sup> נבג\"מ שלעתיד יאמרו מלאכים קדוש לפני הוי' שישכון בצדיקים בגופם הגשמי ע\"ד שאומרים קדוש לפני אור הוי' ששוכן ומתייחד בע\"ס דאצי' כן יאמרו לעתיד לפני הוי' ששוכן בצדיקים בגופים גשמיי', ובדרך אפשר באופן יותר נעלה כי הלא התלבשות אא\"ס בע\"ס הוא להוות בחי' היש גשמי, שהיש מסתיר ומעלים כו', אבל לעתיד הרי יתגלה היש אמיתי כנ\"ל בלא הסתר והעלם, שהוא בחי' האור חדש הנ\"ל שיתגלה מן בירור החשך דוקא וכנ\"ל, וא\"כ ממילא יובן הבקשה שמבקשים אחר ספה\"ע ולקדשנו בקדושתך העליונה<sup data-n=\"3447\">251</sup> דוקא, שהוא בגדר קדושת הספירות ממש כפי פי' הג' של וספרתם כנ\"ל, ונק' בשם קדושתך העליונה כידוע הענין בשם הזוהר כי כמה קדישאן אית לעילא<sup data-n=\"3448\">252</sup> ובכולהו אין קדוש כהוי'<sup data-n=\"3449\">253</sup> כו' וזהו בקדושתך העליונה דוקא. וא\"כ היוצא מכל הנ\"ל שבחי' ספה\"ע הוא בחי' הכנה וממוצע לבחי' מ\"ת שהוא אנכי הוי' אלקיך בפרט בכאו\"א מישראל שיהי' כלי לבחי' אנכי מי שאנכי<sup data-n=\"3450\">254</sup> בחי' אלקו' שלך דוקא ובבחי' תפיסא והלבשה והתאחדות בגוף גשמי דוקא וכמבואר בתניא לית",[["3443","247","<b>ירידת הנשמה בגוף היא צורך עלי'</b>: ראה הנסמן באוה\"ת עקב ע' תפא."],["3444","248","<b>לאשתאבא בגופא דמלכא</b>: זהר ויחי ריז, ב. ראה הנסמן במאמרי אדה\"א ויקרא ח\"א ע' מה. תו\"ח בראשית מ, ב הערה 25."],["3445","249","<b>בקרבך קדוש</b>: הושע יא, ט."],["3446","250","<b>עתידים צדיקים. . אדמו\"ר הזקן</b>: ב\"ב עה, ב. ראה פלח הרמון יתרו ר\"ע רנו. שה\"ש ע' מח וע' נ. לעיל ע' כח. וראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תר."],["3447","251","<b>ולקדשנו בקדושתך העליונה</b>: ראה גם לעיל מאמר ד\"ה וספרתם תקצ\"ח על יד הערה 8."],["3448","252","<b>כמה קדישאן אית לעילא</b>: ראה זהר תזריע מד, א."],["3449","253","<b>אין קדוש כהוי'</b>: שמו\"א ב, ב."],["3450","254","<b>אנכי מי שאנכי</b>: ראה תניא מהדו\"ק ספמ\"ט. לקו\"ת להאריז\"ל תולדות כז, יט בשם הזהר. אבן עזרא תולדות שם. מאמרי אדה\"ז תקס\"ב ח\"א ע' יד. פרשיות התורה ח\"א ע' רט ובהנסמן במ\"מ לשם."]]],[4801940650,"מחשבה תפיסא<sup data-n=\"3451\">255</sup> בי' כלל כ\"א כאשר תפיסא ומתלבשת בתורה ובמצותיה דוקא, ההכנה לזה הוא דוקא ע\"י ספה\"ע וכנ\"ל.\n<b>ועתה</b> יש להבין הענין הנ\"ל של וספרתם לכם הוא דוקא ממחרת השבת שאחז\"ל ע\"ז ממחרת יו\"ט הראשון של פסח דוקא, וכשהי' ביום ראשון יצי\"מ ואכילת מצה בלילה הראשונה, אז בליל ב' תתחיל ספה\"ע כו', הענין הוא כידוע כי בכל אתדל\"ת מלמטלמ\"ע מוכרח להיות מתחלה בחי'<sup data-n=\"3452\">256</sup> אתדל\"ע<sup data-n=\"3453\">257</sup> שהיא הנותנת כח ועוז שתוכל להיות אתדל\"ת וכמאחז\"ל אלמלא הקב\"ה עוזרו<sup data-n=\"3454\">258</sup> אינו יכול לו כו', וא\"כ הכח ועוז שיכול האדם לקיים בנפשו ענין של ספה\"ע בכל הפרטים הנ\"ל עד שיעשה כלי לעצמי' אא\"ס ב\"ה שהוא בחי' מ\"ת אנכי ממש בבחי' אלקיך ממש, מוכרח להתעורר מתחלה מבחי' אנכי הנ\"ל מצ\"ע בלא אתדל\"ת, וזהו\"ע יצי\"מ שהיו בחשך התחתון דקליפת מצרים ערות הארץ, וגם ר\"ל היו משוקעים במ\"ט שע\"ט<sup data-n=\"3455\">259</sup> כידוע, וגם הלא היו בתכלית הקטנות, וכמ\"ש כי נער ישראל<sup data-n=\"3456\">260</sup> כו', ולא הי' בכחם כלל לברר החשך לצאת ממנו ולדחותו וכ\"ש להפכו כנ\"ל, ולזה נגלה עליהם ממה\"מ הקב\"ה בכבודו ובעצמו<sup data-n=\"3457\">261</sup>, וכמאמר לא ע\"י מלאך ולא ע\"י שרף<sup data-n=\"3458\">262</sup> כו' רק בחי' עצמותו ומהותו ית' ממש, וזאת פעל בהם הכח ועוז לצאת מהחשך הגס הנ\"ל, רק שזה הגילוי הי' בבחי' דילוג מלמעלה והאיר עליהם רק בבחי' מקיף, וכידוע הענין בד\"ח ע\"פ גפן ממצרים תסיע<sup data-n=\"3459\">263</sup> כו' מה גפן הפרי מבחוץ והקליפה בפנים כו' וכך הרע של נה\"ב שלהם לא נתברר עדיין רק מפני תוקף הגילוי אור שהאיר אז על נפשם והקיף כל כחות נפשם אז הי' הרע דוגמת בחי' שינה שלא פעל פעולתו היינו לעכב על יצי\"מ כי המקיף דיחידה שהאיר בה גילוי אור עצמותו של אנכי כו' הקיף כללות הכחות דנר\"נ וגם נה\"ב כו', ולזה לא הקשו כלל איך נלך למקום מדבר וציה בלא שום מזון ומחי', שהרי לא הי' מי שיקשה כידוע כי כל הקושיות והספיקות הוא רק מצד הרע דנה\"ב<sup data-n=\"3460\">264</sup>, אבל מצד שנתבטל בבחי' המקיף והי' בבחי' שינה ולא פעל פעולתו כי הלא האיר בחי' מקיף דיחידה בנפשם וא\"כ ממילא הי' תוקף האמונה בה' ית' וכמ\"ש משכני אחריך נרוצה<sup data-n=\"3461\">265</sup> כו', והוא בחי' אנכי שנתגלה במ\"ת נתגלה ג\"כ בעת יצי\"מ כי הלא נאמר אנכי כו' אשר הוצאתיך מאמ\"צ כו', ואח\"כ אכילת מצה",[["3451","255","<b>בתניא לית מחשבה תפיסא</b>: ספ\"ד."],["3452","256","<b>אתדל\"ת. . מתחלה בחי' אתדל\"ע</b>: ראה סידור שער התפלה יט, ב. תו\"ח תרומה ח\"ב שטז, ג. וש\"נ."],["3453","257","<b>אתדל\"ת. . אתדל\"ע</b>: ראה זהר לך פח, א. תו\"ח שמות ח\"א מא, א ובהערה 189."],["3454","258","<b>אלמלא הקב\"ה עוזרו</b>: קדושין ל, ב. סוכה נב, ב. ראה תניא רפי\"ג."],["3455","259","<b>משוקעים במ\"ט שע\"ט</b>: ראה ז\"ח יתרו לא, א."],["3456","260","<b>כי נער ישראל</b>: הושע יא, א."],["3457","261","<b>נגלה עליהם ממה\"מ הקב\"ה בכבודו ובעצמו</b>: ע\"פ הגדה של פסח פיסקא מצה זו ופיסקא ויוציאנו. ראה גם תו\"ח בא ח\"א קט, רע\"ג. וש\"נ."],["3458","262","<b>לא ע\"י מלאך ולא ע\"י שרף</b>: הגדה של פסח."],["3459","263","<b>גפן ממצרים תסיע</b>: תהלים פ, ט. ראה גם לעיל ע' נח. לעיל מאמר ד\"ה וספרתם תקצ\"ח על יד הערה 47."],["3460","264","<b>כל הקושיות והספיקות. . הרע דנה\"ב</b>: ראה זהר רע\"מ נשא קכד, ב (אגה\"ק סכ\"ו)."],["3461","265","<b>משכני אחריך נרוצה</b>: שה\"ש א, ד."]]],[4801940652,"בלילה הראשונה שהיא חובה<sup data-n=\"3462\">266</sup> כו' והוא ג\"כ מיכלא דמהימנותא<sup data-n=\"3463\">267</sup> כמבואר בזוהר, והיינו שהמצה הוא בחי' כלי בבחי' קטנות ובהעלם לבחי' אנכי הנ\"ל, שיהי' לכה\"פ בחי' הכרה בקטנות כידוע הענין באריכות בסידור<sup data-n=\"3464\">268</sup> ובלק\"ת<sup data-n=\"3465\">269</sup> על מאחז\"ל אין התינוק יודע לקרות אבא<sup data-n=\"3466\">270</sup> עד שיטעום טעם דגן, שהידיעה היא בתכלית הקטנות רק בבחי' הכרה והלבשה הגם שבהכרה זו דקטנות מלובש כללות תכלית הגדלות כמבואר שם, מ\"מ הרי אין התינוק כלי לזה שיאיר אצלו בבחי' גילוי אור רק בהעלם, וכ\"ה בכללות נש\"י בעת יצי\"מ הגם שהי' אותו הגילוי ממש שבעת מ\"ת כנ\"ל, אבל הי' אצלם בתכלית הקטנות באכילת מצה שהוא בבחי' קטנות דאבא כמבואר שם ע\"ש, אבל מ\"מ הי' זה כח ועוז בנפשם וגם הכנה רבה שאח\"כ יוכלו לעשות כלי בנפשם מעט מעט ע\"י ספה\"ע מעט מעט בכל יום לברר ולזכך הרע דנה\"ב ולהסיר החשך, שגם הוא יתהפך לאור, שזהו נק' בחי' אתדל\"ת עד שהיו כלים ממש למ\"ת הגילוי של אנכי, שיתלבש במוחם ולבם בבחי' אור פנימי, אבל אם לא הי' מתחלה בחי' אתדל\"ע, לא הי' בכחם כלל לבוא לספה\"ע ומ\"ת כנ\"ל, וזה ידוע כי הימים האלה נזכרים ונעשים בכל דור<sup data-n=\"3467\">271</sup> ובכל שנה בפרט וא\"כ זהו\"ע שדוקא ממחרת השבת שהוא בחי' יו\"ט הראשון של פסח שהי' בחי' הגילוי דאנכי כו' לצאת ממצרים וגם הכלי לזה שיתלבש בהעלם ובקטנות כו' ע\"י אכילת מצה כנ\"ל אז יכולים לבוא לבחי' ספה\"ע וכל המדריגות עד מ\"ת כו', והטעם שנק' בשם מחרת השבת ידוע מ\"ש בלק\"ת כי מעלי דשבתא הוא בחי' מל' ויומא דשבתא הוא בחי' ז\"א, ומחרת השבת היינו שלמעלה מבחי' שבת הוא בחי' בינה<sup data-n=\"3468\">272</sup> עכ\"ל, רק הכוונה הוא על בחי' פנימי' בינה שהוא שער הנו\"ן דבינה, ששרשו בפנימי' הכתר, שמשם הי' שרש ומקור יצי\"מ כמבואר בזוהר שעל טעם זה נזכר נ' פעמים בתו' נס דיצי\"מ<sup data-n=\"3469\">274</sup> להורות שמבחי' זאת שהוא בחי' עלמא דחירו<sup data-n=\"3470\">273</sup> כידוע נמשך שרש דיצי\"מ, וגם בחי' מ\"ת גילוי אנכי הוא ג\"כ מבחי' שער הנו\"ן הנ\"ל, ולזה הי' דוקא ביום החמישים כו', וגם ענין ספה\"ע הוא ג\"כ הכח ע\"י שער הנו\"ן, וזהו תספרו חמישים יום<sup data-n=\"3471\">275</sup> כידוע באריכות על ענין זה דהקושיא כי אינם סופרים רק מ\"ט יום כו' וד\"ל.",[["3462","266","<b>אכילת מצה בלילה הראשונה שהיא חובה</b>: פסחים קכ, א. מכילתא ורש\"י בא יב, טו. רמב\"ם הל' חו\"מ רפ\"ו. שו\"ע אדה\"ז הל' פסח סתע\"ה, סל\"ב."],["3463","267","<b>מצה. . מיכלא דמהימנותא</b>: ראה זהר רע\"מ בא מא, א. מאמרי אדה\"א ויקרא ח\"ב ע' תרלו. וש\"נ."],["3464","268","<b>בסידור</b>: שער חג המצות רפד, ד."],["3465","269","<b>ובלק\"ת</b>: צו יג, ד."],["3466","270","<b>אין התינוק יודע לקרות אבא</b>: ראה ברכות מ, סע\"א. לעיל ע' קה. וש\"נ."],["3467","271","<b>הימים. . בכל דור</b>: ע\"פ אסתר ט, כח."],["3468","272","<b>בלק\"ת כי מעלי דשבתא. . בינה</b>: אמור לו, ב (בשינוי קצת)."],["3469","274","<b>בזוהר. . נ' פעמים. . דיצי\"מ</b>: זהר ואתחנן רסב, א (ובדרך אמת שם ס\"ב). ת\"ז סתל\"ט (עט, ב). ניצוצי זהר לת\"ו כב, א אות ו."],["3470","273","<b>דבינה. . עלמא דחירו</b>: ראה מאו\"א מערכת דרור אות יג."],["3471","275","<b>תספרו חמישים יום</b>: ראה לקו\"ת במדבר יב, א. שה\"ש לה, ג. פלח הרמון שה\"ש סה, ב."]]],[4801940117,"<b>כתבי תורות ששמענו מאדמו\"ר בנסיעתינו על חג השבועות תקפואו לפ\"ק</b>\n<b>והניף</b> הכהן אותם<sup data-n=\"3472\">1</sup> על לחם הביכורים תנופה לפני ה'<sup data-n=\"3473\">2</sup> כו'. הנה ענין תנופת שתי הלחם הוא ענין הבירור דשתי תורות תורה שבכתב ושבע\"פ<sup data-n=\"3474\">3</sup> והוא ענין מאכל אדם<sup data-n=\"3475\">4</sup> שבא אחר מאכל בהמה דתנופת העומר<sup data-n=\"3476\">5</sup> וספירה דייקא כמאמר אסור לאדם שיטעום כלום עד שיתן מאכל לבהמתו<sup data-n=\"3477\">6</sup> תחילה. ולהבין ביאור עניינם הנה יש שלשה דיעות בגמ'<sup data-n=\"3478\">7</sup> לחד מ\"ד מניח הכבשים על הלחם כפשוטו של מקרא ולחד מ\"ד מניח לחם על כבשים ויליף מקרא ע\"ש, ורבי ס\"ל בברייתא שם דמניח אותם זה בצד זה, ומפרש שם בגמ' אליבי' מאי על בסמוך כו', וכ\"ה כמו שפסק הרמב\"ם<sup data-n=\"3479\">8</sup>. ולהבין איך שכולם אמת ברוחני', יש להקדים מתחילה ענין מתן תורה בשבועות שהוא ענין שתי הלחם הנ\"ל שנק' מנחה חדשה<sup data-n=\"3480\">9</sup> הלא לכאורה אין שום חידוש בנתינת התורה כי כבר קדמה לעולם<sup data-n=\"3481\">10</sup> וכן אברהם אבינו קיים אותה כבר ברוחני'<sup data-n=\"3482\">11</sup> וראי' לזה ממה שמברכין נותן התורה<sup data-n=\"3483\">12</sup> שמשמעות לשון נותן הוא כדבר הניתן מיד ליד שאין כל חדש בזה רק שמתחילה היתה ביד המשפיע ואח\"כ ניתנה ליד המקבל, וכן משה קיבל<sup data-n=\"3484\">13</sup> כו', וא\"כ למה קורא לנתינת התורה בשם מנחה חדשה וכן בכל יום יהיו בעיניך כחדשים<sup data-n=\"3485\">14</sup> אינו מובן יותר דהלא כבר ניתנה בסיני.\n<b>אך</b> הנה ידוע דתלת קשרין הם<sup data-n=\"3486\">15</sup> ישראל מתקשראן באורייתא ואורייתא בקוב\"ה ובכ\"א יש בחי' סתים וגלי'<sup data-n=\"3487\">16</sup> כי קוב\"ה סתים היינו מה שהוא סדכ\"ס<sup data-n=\"3488\">17</sup> שמובדל מכל ההשתלשלות אפי' מבחי' מח' הקדומה כמאמר לית מח' תפיסא בך<sup data-n=\"3489\">18</sup> וירד בבחי' גליא באמרו אנכי מי שאנכי<sup data-n=\"3490\">19</sup> בדיבור, וכן אורייתא סתים שהוא בחי' חכ' כמו",[["3472","1","<b>והניף הכהן אותם</b>: הנחת ר\"ה ממאמר ד\"ה והניף את העומר שנדפס במאמרי אדה\"א במדבר ח\"ב (ע' תנח) ע' תסט ואילך.\nראה עוד ע\"ד המאמר לקמן ברשימת הכת\"י כאן."],["3473","2","<b>והניף הכהן. . לפני ה'</b>: אמור כג, כ."],["3474","3","<b>שתי הלחם. . תורה שבכתב ושבע\"פ</b>: ראה זח\"א השמטות רס, א."],["3475","4","<b>שתי הלחם. . מאכל אדם</b>: ראה מאמרי אדה\"א במדבר ח\"ב ס\"ע שטז ואילך."],["3476","5","<b>מאכל בהמה. . העומר</b>: ראה מל\"א ה, ח. פסחים ג, סע\"ב. סוטה יד, א (במשנה)."],["3477","6","<b>אסור לאדם. . מאכל לבהמתו</b>: ראה ברכות מ, א. לקו\"ת בחוקותי מט, ב. תו\"ח משפטים ח\"ב רפב, ד ובהערה 54."],["3478","7","<b>שלשה דיעות בגמ'</b>: מנחות סא, א (במשנה). סב, א."],["3479","8","<b>שפסק הרמב\"ם</b>: הל' תמידין ומוספין פ\"ח, הי\"א."],["3480","9","<b>שתי הלחם. . מנחה חדשה</b>: אמור כג, טז. יז. פינחס כח, כו וברש\"י."],["3481","10","<b>התורה. . קדמה לעולם</b>: פסחים נד, א."],["3482","11","<b>התורה. . אברהם אבינו קיים. . ברוחני'</b>: ראה יומא כח, ב. לעיל מאמר ד\"ה וספרתם הה' ובהערות 93-94."],["3483","12","<b>שמברכין נותן התורה</b>: נוסח ברכת התורה."],["3484","13","<b>משה קיבל</b>: אבות רפ\"א."],["3485","14","<b>בכל יום יהיו בעיניך כחדשים</b>: ראה לקח טוב ואתחנן ו, ו. לעיל ע' קמב הערה 14."],["3486","15","<b>דתלת קשרין הם</b>: ראה זהר אחרי עג, א. הנסמן במאמרי אדה\"א קונטרסים ע' שלט."],["3487","16","<b>ובכ\"א. . סתים וגלי'</b>: ראה זהר אחרי עא, ב. עג, א. ש\"א ב, ב הערה 24. לקמן מאמר ד\"ה אם בחוקותי הג'."],["3488","17","<b>סדכ\"ס</b>: ראה זהר בהקדמה ב, א. ועוד."],["3489","18","<b>לית מח' תפיסא בך</b>: ראה ת\"ז בהקדמה יז, א."],["3490","19","<b>אנכי מי שאנכי</b>: יתרו כ, ב. ראה תניא מהדו\"ק ספמ\"ט. לקו\"ת להאריז\"ל תולדות כז, יט בשם הזהר. אבן עזרא תולדות שם. מאמרי אדה\"ז תקס\"ב ח\"א ע' יד. פרשיות התורה ח\"א ע' רט ובהנסמן במ\"מ לשם."]]],[4801940181,"שהיא כלולה בעצמות סדכ\"ס הנ\"ל וירדה למטה בבחי' גליא בעשרת הדברות, וישראל סתים שהוא שורש נשמתן כמו שעלה במח'<sup data-n=\"3491\">20</sup> עצמי' שהוא למעלה ממחה\"ק רק מיוחדים בעצמותם ומהותם ממש וירדו למטה להתלבש בגופים. ויובן מזה למשכיל שכמו שבבחי' סתים ישראל מתקשראן באורייתא כו' כך בבחי' גליא בנשמות שבגופים כששמעו עשרת הדברים שהוא ענין שרש אותיות התורה כמו שירדה בבחי' גליא נתקשרו עי\"ז לבחי' קוב\"ה כמ\"ש בבחי' גליא שהוא בחי' אנכי מי שאנכי הנ\"ל המדבר עשרת הדברות [וכמאמר על כל דיבור פרחה נשמתן<sup data-n=\"3492\">21</sup> ], וזהו ענין חדש בנתינת התורה שהוא ענין תלת קשרין הנ\"ל שהמה בבחי' סתים שירדו למטה בבחי' גליא בדיבור שעי\"ז ניתוסף אור חדש מבחי' קוב\"ה סדכ\"ס בעצמו בבחי' חכ' שבעצמו' שהוא בחי' תוה\"ק שלא הי' מאיר בה אור כזה מקדם כשקדמה לעולם כידוע שנעוץ תחילתן בסופן<sup data-n=\"3493\">22</sup> ששלימות התחלה הוא ע\"י הסוף וכן בכל יום ויום כשאדם מדבר דבר הלכה שעי\"ז הקב\"ה קורא ושונה<sup data-n=\"3494\">23</sup> שהוא ענין ירידתו בדיבור שעי\"ז ניתוסף אור חדש לגמרי בעצמי' חכמתו<sup data-n=\"3495\">24</sup> וזהו בכל יום יהיו בעיניך כחדשי\"ם כו' וד\"ל.\n<b>והנה</b> להבין כל הנ\"ל איך ע\"י הדיבור שהוא ענין הגשמת השכל עי\"ז יתוסף אור בעצמו' החכ' הרוחני' שאין ערוך לירידת השכל בדיבור אילי', יש להבין מתחילה איך דומה ירידת התורה בדיבור ללחם שהוא חיות הבא ע\"י בירור מתחילה דייקא הענין הוא שכמו שבלחם הגשמי יש בו ב' בירורים הא' מה שלוקחים החטה וטוחנין ומרקדים ואופין עד שנעשית ראוי למאכל אדם ונק' תיקון המאכל בלבד ואח\"כ כשנצרך לחיות בו מוכרח בתחילה ללועסו ולפררו בשינים דק דק לחלקים ועי\"ז כשבא אח\"כ באצטומכא נתברר בטוב הפסולת מן האוכל והפסולת נדחה לחוץ והטוב שבו נתברר ונעשה דם שבכבד ומשם נתברר מובחר הדם ונשלח מלמטה למעלה אל הלב ומהלב נתברר בבירור אחר בירור ונשלח אל המוח ומכל הבירורים ועליות הנ\"ל נעשה רק הכנת החומר שהוא ענין חיזוק כלי הכבד [שהוא כלי המעשה שהוא נותן כח וחיזוק בחיצוני' האברים] והלב והמוח ואח\"כ אחר עיכול המאכל לגמרי שהוא אחר ו' שעות<sup data-n=\"3496\">25</sup> נתאחד בעצמו' אור הנפש וגורם משם המשכת אור וחיות מהמוח אל כל האברים דרך גידים המלאים רוח [כי מתחילה סיבוב והילוך",[["3491","20","<b>וישראל. . שעלה במח'</b>: ראה ב\"ר פ\"א, ד. שע\"ת קטו, ב. תו\"ח שמות ח\"א לב, ב ובהערה 248."],["3492","21","<b>על כל דיבור פרחה נשמתן</b>: ראה שבת פח, ב. מאמרי אדה\"א ויקרא ח\"א ע' ג. וש\"נ. נ\"ך ע' שפא וש\"נ. תו\"ח בראשית יז, ב."],["3493","22","<b>שנעוץ תחילתן בסופן</b>: ראה ס\"י פ\"א, מ\"ז."],["3494","23","<b>כשאדם. . הקב\"ה קורא ושונה</b>: ראה תדא\"ר רפי\"ח. מאמרי אדה\"א דברים ח\"ב ע' שפז. וש\"נ. תו\"ח וארא ח\"א נח, ג. וש\"נ."],["3495","24","<b>בדיבור. . אור חדש. . חכמתו</b>: ראה גם ביאוה\"ז פינחס קיג, ב ואילך. מאמרי אדה\"א דברים ח\"ד ע' א'תלד. תו\"ח שמות ח\"א מז, ג. וש\"נ. סה\"מ תרל\"ה ח\"ב ע' שמ. וש\"נ."],["3496","25","<b>עיכול המאכל. . ו' שעות</b>: ראה זהר רע\"מ פינחס רלה, א. שו\"ע יו\"ד רספ\"ט ובנ\"כ שם. מאמרי אדה\"א דברים ח\"א ר\"ע קנו. תו\"ח בא ח\"א קד, ג ובהערה 375."]]],[4801940238,"הדמים הוא ע\"י גידים המלאים דם] ואז הוא בחי' המשכת הצורה בחומר כו' וד\"ל. והנה איכות הבירור בכי טוב תלוי באופן ההתחלקות שבשינים שכשלועסו היטב בשינים עי\"ז נתברר באצטומכא בכי טוב ומחמת זה גורם אח\"כ חיזוק האברים יותר וזהו ענין דוק בככי ותשכח בנגרי<sup data-n=\"3497\">26</sup> כו'.\n<b>וככה</b> יובן למשכיל בענין לחמה של תורה שע\"י שמדבר דברי תורה בחילוקי דינים שבה כשר או פסול כו' הוא כענין הגירסא בשינים כמאמר גרסה נפשי<sup data-n=\"3498\">27</sup> כו', ועי\"ז נתברר אח\"כ הסברא בתכלית הבירור לתכליתה ולעומקה וכ\"ז נעשה ע\"י הגירסא בדיבור לברר כל איכות פרטי חילוקי דינים שבכל הלכה והלכה עי\"ז נעשה ממילא בירור עומק הסברא להבדילה מבחי' הגסות שבה שלא יוקלט במוח רק תמצית הברור שבה וזהו כענין ליבון הילכתא<sup data-n=\"3499\">28</sup> והוא ענין בירור הטוב מתוך הרע [כדוגמת בישול המאכל באצטומכא כו']. וזהו ותורתך בתוך מעי<sup data-n=\"3500\">29</sup> לברר כו', ועי\"ז נעשה אח\"כ מזון לנשמה בב' אופנים הנ\"ל דהיינו מתחילה נעשה הכנת החומר דהיינו שיהיו אברים הרוחני' של הנשמה מוכנים לקבלת אלקו' בתוך תוכן דהיינו שהלב יהי' כלי מוכן לקבל כל מיני התפעלות אהוי\"ר שכליי' והמוח יהי' כלי שהוא בחי' חומר היולי מוכן לקבל כל מיני השגות אלקות ואח\"כ נעשה בחי' המשכת הצורה בכל אברי הנשמה דהיינו תוס' גילוי אלקות במוח בהשגה ובלב בהתפעלות [כענין הלומד תורה לשמה<sup data-n=\"3501\">30</sup> מגלין לו רזי תורה כו'] עד שגם כח ההילוך שברגל שהוא ענין ההסכם לסו\"מ וע\"ט גם כן נתחזק מזה שמזה נעשה אח\"כ ההילוך בנשמה כשהיא בג\"ע בלי שיעור בעצמותו כמו ענין ילכו מחיל אל חיל<sup data-n=\"3502\">31</sup> כו'. וככה יובן למעלה ברוחני' שע\"י שירד בבחי' חכמתו העצמי' בדיבור להבדיל בין טוב לרע כמו לא תרצח<sup data-n=\"3503\">32</sup> כו' כבד את אביך<sup data-n=\"3504\">33</sup> כו' עי\"ז נעשה בירור הדיבור לעלו' לשרשו בבחי' מקיפים דחכמה להוסיף תוס' אור בבחי' חכמה שבעצמותו וזהו ענין מנחה חדשה של שתי הלחם שהן תושב\"כ ושבע\"פ כנ\"ל וד\"ל.\n<b>ומעתה</b> יש להבין ענין הכבשי' שהמה על הלחם לחד מ\"ד, דהנה לחם בגי' מזלא<sup data-n=\"3505\">34</sup> שהוא בחי' מזל ונוצר<sup data-n=\"3506\">35</sup> המצמיח גילוי שכל מקור החכמה הנק' ח\"ס, שהוא רק בחי' מותרי ח\"ס הבאים בבחי' מקיפים לחכמה ומשם נמשך תוס' אור",[["3497","26","<b>דוק בככי ותשכח בנגרי</b>: שבת קנב, א."],["3498","27","<b>גרסה נפשי</b>: תהלים קיט, כ. ראה גם מאמרי אדה\"א בראשית ע' תקעה. וש\"נ."],["3499","28","<b>ליבון הילכתא</b>: ראה זהר בראשית כז, א. רע\"מ בהעלותך קנג, א. פינחס רכט, ב. רמח, ב. מאמרי אדה\"א שמות ח\"א ע' קפד. וש\"נ. תו\"ח שמות ח\"א ג, א ואילך."],["3500","29","<b>ותורתך בתוך מעי</b>: תהלים מ, ט."],["3501","30","<b>הלומד תורה לשמה</b>: ראה אבות רפ\"ו."],["3502","31","<b>ילכו מחיל אל חיל</b>: תהלים פד, ח."],["3503","32","<b>לא תרצח</b>: יתרו כ, יג. ואתחנן ה, יז."],["3504","33","<b>כבד את אביך</b>: יתרו שם, יב. ואתחנן שם, טז."],["3505","34","<b>לחם בגי' מזלא</b>: ראה סידור שער בהמ\"ז קז, ד בשם הע\"ח. פע\"ח שער יוה\"כ שכ\"ז, פ\"ג. מאמרי אדה\"א ויקרא ח\"א ע' קכב. וש\"נ. תו\"ח בא ח\"א קי, ד. וש\"נ."],["3506","35","<b>מזל ונוצר</b>: כ\"ה בכ\"מ ומהם — מאמרי אדה\"א בראשית ע' רנה. במדבר כאן ע' תעו. דברים ח\"ב ע' שעז. וש\"נ."]]],[4801940291,"בחכמה מבחי' המקיף בלבד, ועי\"ז לא נמשך רק תוס' שכל השייך למדות בלבד דהיינו להכיר במהות הטוב והרע ולהבדיל ביניהם רק שהכרה זאת היא הכרה שכלית ולא כבהמה שבורחת מדבר המזיק ואוהבת דבר המועיל מצד טבעי' בלבד [ע\"י כלי המדמה שבמוחה], וזהו אין התינוק יודע לקרות אבא עד שיטעום טעם דגן<sup data-n=\"3507\">36</sup> ואז מתחיל ג\"כ לדבר<sup data-n=\"3508\">37</sup> וממילא מובן שהמשכות האותיות המה מבחי' מקיפים הנ\"ל ונמשכים ע\"י טעימת טעם דגן, אבל הכבשים שהוא בשר בהמה כשנתברר ונתהפך במהות אדם [כמו ע\"י האכילה שנהפך להיות בשר כבשרו] אז עולה לשרשו בבחי' התוהו שקדם לתיקון<sup data-n=\"3509\">38</sup> דהיינו בבחי' מדות שברצון שלמעלה מן הטעם לגמרי ועי\"ז נמשך תוס' אור בבחי' עצם הח\"ס שיומשך בבחי' גילוי בבחי' חכמה בעצם ולא בחכמה השייך למדות בלבד וכמאמר עד לא אכילנא בשרא דתורא<sup data-n=\"3510\">39</sup> כו', ולכן ע\"ה אסור לאכול בשר<sup data-n=\"3511\">40</sup> רק לחם מותר לו לאכול מחמת שהבירור שלו אינו רק בשכל השייך למדות בלבד משא\"כ בבחי' ת\"ח שהבירור שלו הוא בבחי' שכל בעצם [רק בשר זבחי שלמים מותר לע\"ה לאכול מצד שכבר נתברר ע\"י הכהן בזריקת דמו והקטר חלביו כו' וד\"ל], וזהו ג\"כ ענין כבשי התמידין שהוא ענין הבירור דבהמה שנעשה אדם ועי\"ז נמשך תוס' אור בבחי' חכמה בעצם כנ\"ל, רק שבא בגילוי באותיות המחשבה והדיבור. וזהו את הכבש האחד תעשה בבוקר<sup data-n=\"3512\">41</sup> להמשיך בחי' החכמה באותיות המחשבה ואת הכבש השני תעשה בין הערבים שיומשך בחי' חכ' הנ\"ל בבחי' אותיות הדיבור רק שלא היו צריכין לתנופה שהוא ענין הבירור ע\"י הכהן כי כבר נעשה תנופה זאת בדרך כלל בכבשי עצרת שהמה כוללים כבשי התמידים דכל השנה.\n<b>וזהו</b> ענין עולת תמיד העשויה מכבר בהר סיני<sup data-n=\"3513\">42</sup>, ולכאורה מה ענין הר סיני לעולת תמיד, אך הענין הוא כנ\"ל דבהר סיני הוא ענין נתינת התורה שהוא ענין תוס' אור דלחם שנתחזק בתוס' כח ע\"י הכבשים שלמעלה מהם שהמה הכנה כוללת לכבשי התמידין דכל השנה, וכ\"ה עכשיו בתפילה במקום קרבן<sup data-n=\"3514\">43</sup> שהוא ענין התהפכות המדות הטבעיו' לה' לבדו שהוא כמו ענין הבהמה שנתהפך להיות במהות אדם שעי\"ז נעשה אח\"כ תוס' כח וחיזוק בבחי' אדם מה שלא יהי' חיזוק כזה מצד התורה עצמה הנק' לחם והיינו תוס' כח בבחי' השגות אלקות בעצם שאינו שייך",[["3507","36","<b>אין התינוק. . טעם דגן</b>: ראה ברכות מ, סע\"א. מאמרי אדה\"א דברים ח\"א ע' רמה. וש\"נ. תו\"ח בא ח\"א צה, ב. וש\"נ."],["3508","37","<b>התינוק. . טעם דגן. . לדבר</b>: ראה גם תו\"ח בא שם. קכט, א."],["3509","38","<b>התוהו שקדם לתיקון</b>: ראה תו\"א בשלח סה, ד. לקו\"ת אמור לז, ד. וש\"נ."],["3510","39","<b>עד לא אכילנא בשרא דתורא</b>: ראה ב\"ק עב, רע\"א. מאמרי אדה\"א הנחות תקע\"ז ע' קמט. שמות ח\"א ע' ה. וש\"נ. תו\"ח בא ח\"א צג, ב וש\"נ. תשא ח\"ב שפד, ג. סה\"מ תרכ\"ז ע' תיב."],["3511","40","<b>ע\"ה אסור לאכול בשר</b>: ראה פסחים מט, ב. מאמרי אדה\"א דברים ח\"ב ע' תקעו. וש\"נ. במדבר ח\"ג ע' תתצה. ע' תתקא. ע' תתקטו. ע' תתקכג. לקו\"ש לך ח\"ב ע' 455."],["3512","41","<b>את הכבש האחד תעשה בבוקר</b>: תצוה כט, לט."],["3513","42","<b>עולת תמיד העשויה. . בהר סיני</b>: פינחס כח, ו."],["3514","43","<b>בתפילה במקום קרבן</b>: ברכות כו, א-ב. ראה מאמרי אדה\"א ויקרא ח\"א ע' ד. וש\"נ. אוה\"ת תשא ע' א'תתפג."]]],[4801940341,"עדיין להתפעלות אהבה ולכן כל האומר אין לי אלא תורה<sup data-n=\"3515\">44</sup> [בלא תפילה] אפי' תורה אין לו כו' וד\"ל. [רק לכאורה אינו מובן מה צורך להקרבת הכבשים ותנופתם הלא כבר נעשה בירור בחי' בהמה ע\"י תנופת העומר שהוא מאכל בהמה, הענין הוא דע\"י הנפת העומר שעורים הוא עולה לשרשו בבחי' שעורה שיעור ה\"א<sup data-n=\"3516\">45</sup> שהוא ענין ה' מוצאות הפה ה' גבורות שבמל'<sup data-n=\"3517\">46</sup> שמשם שרש התחלקות הנבראים בהתהוותן וחיותן לאין שיעור מחנה מיכאל ק\"פ אלף<sup data-n=\"3518\">47</sup> כו' וכמאמר מה רבו מעשיך ה'<sup data-n=\"3519\">48</sup>, וע\"י הנפת העומר הוא גורם תוס' כח וחיות מבחי' ה' גבורות הנ\"ל לכל נברא ונברא שיתחזק במציאותו כמו מחנה מיכאל באהבה שהוא בבחי' יש מי שאוהב<sup data-n=\"3520\">49</sup> ואפי' בבחי' הביטול שבאהבה יש מי שבטל וכן מחנה גבריאל ביראה כו' והוא ענין חיזוק נפש הבהמה שתתחזק במציאותה ומשם נמשך ג\"כ תוס' כח וחיות לנה\"ט שהוא בחי' הרגשת אלקות בבחי'<sup data-n=\"3521\">50</sup> [... ובכלל<sup data-n=\"3522\">51</sup> הוא בחי' התפעלות חיי בשר בלבד] ולכן נק' מאכל בהמה שהוא לחזק נפש הבהמה בלבד, אבל הקרבת הכבשים הוא ביטול והפשטת נפש הבהמה שתוכלל בבחי' אדם העליון דאצי' וע\"י התהפכותה לבחי' אדם היא עולה בשרשה בבחי' התוהו שלמעלה מבחי' אדם דתיקון וגורם תוס' אור וחיות בבחי' אדם העליון דאצי' עצמו כנ\"ל וד\"ל.\n<b>וזהו</b> כמ\"ד כבשים על הלחם, אבל מ\"ד לחם על הכבשים טעמו נימוקו שבבחי' התוהו עצמו שקדם לתיקון שם שרש הלחם גבוה יותר מבחי' בהמה. והענין הוא שיש ב' מיני השתלשלות שנק' בחי' תוהו ותיקון או עיגולים ויושר<sup data-n=\"3523\">52</sup> ובכ\"א יש ע\"ס שנק' דצח\"מ בכלל רק שבבחי' התיקון מדבר גבוה מכולם וראי' לד\"ז שכולם נכללים בו ובטלים אליו כי במדבר יש בחי' חי ג\"כ שהוא נפש החיוני' הטבעי' שיש בו כמו בבהמה שהוא בחי' מדות טבעים כמו בבהמה, רק שנגררים אחר השכל, וכן בחי' צומח הוא בחי' הצמיחה שבו מקטנות לגדלות בחומר גופו ונפשו ועצם הגשם שלו הוא בחי' הדומם שבו, אבל בחי אין שם בחי' מדבר רק צומח ודומם כלול בו, ובצומח ניטל ממנו חלק החי ואין שם רק הדומם שבו שהוא הגשם שלו רק שהוא צומח בהתפשטות, ובדומם אין שם אפי' בחי' הצמיחה, ונמצא שהמדבר הוא ראשון והדומם הוא אחרון בהשתלשלו' דתיקון",[["3515","44","<b>כל האומר אין לי אלא תורה</b>: ראה יבמות קט, ב. לקו\"ת ויקרא ה, א. תו\"ח משפטים ח\"ב רפו, ב. וש\"נ."],["3516","45","<b>שעורה שיעור ה\"א</b>: זהר בלק קפח, ב. ראה גם לקמן מאמר ד\"ה בסוכות תשבו תרכ\"ב הערה 38."],["3517","46","<b>ה' מוצאות הפה ה' גבורות שבמל'</b>: ראה ע\"ח שער טנת\"א ש\"ה, פ\"ג."],["3518","47","<b>מחנה מיכאל ק\"פ אלף</b>: ראה זהר בהעלותך קנד, א. לעיל מאמר ד\"ה וספרתם תקצ\"ח ובהערה 79."],["3519","48","<b>מה רבו מעשיך ה'</b>: תהלים קד, כד."],["3520","49","<b>יש מי שאוהב</b>: ראה גם תו\"א וארא נו, א. יתרו סז, ג. סה\"מ תרל\"ח ע' קלה ובהערה 714."],["3521","50","<b>בבחי'</b>: חסר ההמשך בגוכת\"י. ד ניתוסף: יש. אבל כנראה שהוסיפו מדעתו, וראה גם בסמוך הערה 59."],["3522","51","<b>[ובכלל</b>: יש להעיר שהסגול נסמן רק בהתחלת החצאי ריבוע. וראה גם בסמוך הערה 59. לקמן ברשימת הכת\"י כאן."],["3523","52","<b>תוהו ותיקון או עיגולים ויושר</b>: ראה גם תו\"א שמות נב, א. ביאוה\"ז עקב קכ, א. סידור שחרית לשבת קעט, ב. לעיל מאמר ד\"ה וספרתם תרי\"ט על יד הערה 68."]]],[4801940388,"שהוא מבחי' חכמה אבל בהשתלשלות דתוהו<sup data-n=\"3524\">53</sup> שהוא בחי' הכתר<sup data-n=\"3525\">54</sup> שנק' רצון<sup data-n=\"3526\">55</sup> הוא להיפך שכתר שבכתר הוא בחי' דומם<sup data-n=\"3527\">56</sup> שהוא בחי' העצמיו' שמובדל מגדר התפשטות ומה שבכחו ההיולי להצמיח כל בחי' שכל בגילוי הוא בחי' ח\"ס הכלולה בעצמי' הכתר הוא בחי' צומח שבו ומדות שברצון הוא בחי' חי ואותיות שבכתר הוא בחי' אחרונה שבו הנק' מדבר שנעשה מקור לבחי' נפש השכלי' שהמה עשר כחות מחכמה ולמטה נמצא שמבחי' אחרונה דתוהו [או עיגולי'] נעשה ראש ומקור לבחי' ראשונה דיושר ותיקון<sup data-n=\"3528\">57</sup> אבל בחי' היותר עליונה שבבחי' התוהו היא בתיקון בבחי' אחרונה שבו [ולכן נאמר על האדם אחור וקדם צרתני<sup data-n=\"3529\">58</sup> כי מצד נשמתו שהוא מבחי' התיקון הוא קדם למע\"ב ומצד חומר גופו הוא אחור למע\"ב כי חומר גופו שרשו בבחי' התוהו ששם הוא אחרון בהשתלשלות] [... ולכן הוא בחי' ממוצע להמשיך מבחי' התוהו לתיקון כי הוא מבחי' אחרונה שבעליון וראש ומקור לתחתון כו' וד\"ל]<sup data-n=\"3530\">59</sup>.\n<b>והענין</b> הוא כידוע מענין ואלה המלכים<sup data-n=\"3531\">60</sup> שבחי' נקודות דתוהו נפלו ונשברו וכל דבר היותר עליון כשנופל למטה הוא נופל למרחוק יותר<sup data-n=\"3532\">61</sup> כידוע ממשל החומה<sup data-n=\"3533\">62</sup> כו' אבל מ\"מ שרשו בהעלם ישנו בו עדיין לכן כשנתברר אזי עולה לשרשו הגבוה יותר ומוסיף כח בעליון הימנו בהשתלשלות דתיקון, ולכן אנו מוצאים שעיקר חיות שיחי' האדם הוא על הלחם דייקא ולכן נצרך לברך עליו שלש ברכות<sup data-n=\"3534\">63</sup> אבל על הבשר אומר שנ\"ב ובנ\"ר שהוא רק תוס' התפשטות חיות בלבד לא עיקר החיות שבו יחי' האדם. וזהו טעם דמ\"ד לחם על הכבשים כי אחר שנתבררו הכבשים ועלו לשרשם בבחי' מדות שבכתר וגרמו תוס' חיות בבחי' הלחם ששרשו בבחי' מזלא שהוא בחי' מותרי ח\"ס דתיקון אזי עולה הלחם לשרשו",[["3524","53","<b>דצח\"מ. . התיקון. . דתוהו</b>: ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תתפד. וש\"נ. לעיל ע' קעח ובהערה 98."],["3525","54","<b>דתוהו. . הכתר</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"א."],["3526","55","<b>הכתר שנק' רצון</b>: ראה פרדס שער עצמות וכלים ש\"ד, פ\"ח. שער הצחצחות שי\"א, פ\"ה. פ\"ו. אגה\"ק סכ\"ט. מאמרי אדה\"א הנחות תקע\"ז ע' עב. וש\"נ."],["3527","56","<b>שכתר שבכתר הוא בחי' דומם</b>: ראה גם לעיל ע' קעח ובהערה 99."],["3528","57","<b>דתוהו. . ראש ומקור. . ותיקון</b>: ראה גם לעיל ע' קסג. ע' קעה. פלח הרמון בשלח ע' קצב."],["3529","58","<b>אחור וקדם צרתני</b>: תהלים קלט, ה. ב\"ר פ\"ח, א. ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תרנז. דברים ח\"ד ע' א'שסד. וש\"נ."],["3530","59","<b>וד\"ל]</b>: ד: וד\"ל. ..]. אבל כנראה הוסיף את הסגול מדעתו. ראה גם לעיל הערות 50-51."],["3531","60","<b>ואלה המלכים</b>: וישלח לו, לא. ראה זהר אד\"ר נשא קכח, א. ע\"ח שער הכללים פ\"א. שער דרושי הנקודות ש\"ח, פ\"ד."],["3532","61","<b>וכל דבר היותר עליון. . למרחוק יותר</b>: ראה ש\"א שער הפורים נח, א. סה, א. תו\"ח שמות ח\"א כא, ב הערה 863. סה\"מ תרל\"ב ח\"א ע' קכב. וש\"נ. לעיל ע' מד."],["3533","62","<b>ממשל החומה</b>: ראה גם ביאוה\"ז תרומה נ, ד. לקו\"ת מטות פא, ב. מאמרי אדה\"ז אתהלך לאזניא ע' קעב. תקס\"ג ח\"א ע' שע. תקס\"ד ע' קצב. תקס\"ה ח\"א ע' תק. מאמרי אדה\"א ויקרא ח\"ב ע' תשמז. במדבר ח\"ב (כאן) ע' תפ וע' תשנג."],["3534","63","<b>הלחם. . לברך עליו שלש ברכות</b>: בברכת המזון. ראה ברכות מח, ב. שו\"ע אדה\"ז הלכות ברכת המזון רסקפ\"ט."]]],[4801940432,"הראשון שהוא בחי' חכ' שבעצם הכתר דתוהו ואזי הוא למעלה מהכבשים כו' וד\"ל.\n<b>וזהו</b> ג\"כ ענין מחלוקת דשמים קדמו וארץ קדמה, דמ\"ד שמים קדמו הוא בבחי' התיקון ומ\"ד ארץ קדמה הוא בבחי' התוהו שקדם לתיקון ששם הדומם יותר עליון כו', אבל לחד מ\"ד שמים וארץ כא' נבראו<sup data-n=\"3535\">64</sup> כי הנה כל בחי' הנ\"ל דתוהו ותיקון או עיגולים ויושר הוא רק בבחי' ההשתלשלות שם שייך לומר ארץ קדמה או שמים קדמו אבל קמי' עצמותו שלמעלה מהשתלשלות דתוהו ותיקון או עיגולים ויושר שם שניהם שוין. וראי' לד\"ז ממה שאנו מוצאים בבחי' ההשתלשלו' דמחכמה ולמטה כמאמר בראשית ברא ות\"י בחוכמתא<sup data-n=\"3536\">65</sup> וכמאמר כולם בחכמה עשית<sup data-n=\"3537\">66</sup> ואעפ\"כ הצומח קדם לחי שהוא מאמר דתדשא הארץ<sup data-n=\"3538\">67</sup> שקודם למאמר תוצא הארץ נפש חי'<sup data-n=\"3539\">68</sup> ומאמר תוצא הארץ קדם למאמר נעשה אדם<sup data-n=\"3540\">69</sup> וכולם נתהוו מבחי' העפר כמאמר הכל הי' מן העפר<sup data-n=\"3541\">70</sup> כו' שזהו כמו בבחי' התוהו שדומם למעלה מהכל כו' וע\"כ לומר שזהו מצד גילוי בחי' התוהו בתיקון שאין זה אלא מחמת שבחי' עצמותו יתברך שהוא למעלה משניהם יחד יוכל להיות בחי' התכללות דתוהו ותיקון כי קמי' שניהם שוים [ומדריגה זאת ישנה באדם ג\"כ שאע\"פ ששרשו הוא בבחי' התיקון מ\"מ יש בו בהעלם בחי' שם מ\"ה החד\"ש<sup data-n=\"3542\">71</sup> שהוא גילוי אא\"ס שלמעלה מבחי' תוהו ותיקון ולכן כתיב וייצ\"ר ה' אלקי\"ם<sup data-n=\"3543\">72</sup> עפר מן האדמה שהוא בחי' דומם ממש אחרון שבהתשלשלות ויפח באפיו נשמת חיים שהוא נשמתא דפרחא מחי העולמים<sup data-n=\"3544\">73</sup> שהוא בחי' ראשון בהשתלשלות שנכללו בו כא' בבחי' חומר וצורה מטעם הנ\"ל כו' וד\"ל], וזהו ג\"כ טעם דמ\"ד דס\"ל זה בצד זה שהוא המכריע והלכה כמותו כי אחר שנעשה ענין שני הבירורים דלחם וכבשים בתכלית השלימות בב' אופנים דלחם על הכבשים וכבשים על הלחם אזי נגלה בחי' גילוי עצמי' אא\"ס ששם המה זה בצד זה כו' וד\"ל.",[["3535","64","<b>מחלוקת דשמים קדמו וארץ קדמה. . כא' נבראו</b>: חגיגה יב, א. ראה גם מאמרי אדה\"א במדבר כאן ע' תפא."],["3536","65","<b>בראשית ברא ות\"י בחוכמתא</b>: בראשית א, א. כ\"ה בכ\"מ בדא\"ח ובתרגום שם: בחוכמא — סה\"מ מלוקט ג ע' קסד."],["3537","66","<b>כולם בחכמה עשית</b>: תהלים קד, כד."],["3538","67","<b>דתדשא הארץ</b>: בראשית א, יא."],["3539","68","<b>תוצא הארץ נפש חי'</b>: שם א, כד."],["3540","69","<b>נעשה אדם</b>: בראשית שם, כו."],["3541","70","<b>הכל הי' מן העפר</b>: קהלת ג, כ."],["3542","71","<b>שם מ\"ה החד\"ש</b>: ראה ע\"ח שער התיקון ש\"י, פ\"ב."],["3543","72","<b>וייצ\"ר ה' אלקי\"ם</b>: בראשית ב, ז [בדילוג]."],["3544","73","<b>ויפח באפיו. . נשמתא דפרחא מחי העולמים</b>: בראשית שם. ראה זהר תרומה קלח, א."]]],[4801940118,"<b>והניף</b> הכהן אותם<sup data-n=\"3545\">1</sup> על לחם הביכורים<sup data-n=\"3546\">2</sup> כו'. להבין ענין תנופת הלחם והכבשים ולמה צריך להיות הלחם למעלה והכבשים למטה כמבואר במשנה דמנחות<sup data-n=\"3547\">3</sup>. ויש להקדים ענין מארז\"ל אילן שאכל אדה\"ר חטה היתה<sup data-n=\"3548\">4</sup>. ויש להבין למה נחשב לו לחטא על שאכל חטה הלא חטה הוא כ\"ב אתוון דאורייתא<sup data-n=\"3549\">5</sup>, ועוד האיך קורא לחטה בשם עה\"ד טוב ורע, הלא אמרת ה' צרופה<sup data-n=\"3550\">6</sup> כו'. וצריך להקדים ענין שרש אדה\"ר שהי' נשמה גבוה מאוד כמבואר בס' הגלגולים שנשמתו גבוה מנשמת משה רבע\"ה, כי דוד הי' בבחי' נפש<sup data-n=\"3551\">8</sup> דאצי' ומשה רבע\"ה הי' בבחי' נשמה<sup data-n=\"3552\">9</sup> דאצי', אבל אדה\"ר הי' הכולל לכל הנשמות שיבואו אחריו והי' כולל מיחידה דאצי' עד נפש דעשי'<sup data-n=\"3553\">7</sup> וידוע דנשמת משיח שיבא בב\"י הוא בחי' יחידה<sup data-n=\"3554\">10</sup> וכידוע שיהי' כמה עליות למשיח בעילוי אחר עילוי וכמאמר ישכיל עבדי<sup data-n=\"3555\">11</sup> ירום ונשא כו' ועלי' היותר אחרונה הוא בחי' מאד שזהו בחי' עצם היחידה, ובחי' זאת הי' גם באדה\"ר, וזהו מאד אותיות אדם<sup data-n=\"3556\">12</sup> וכידוע דאדם ר\"ת אדם דוד משיח<sup data-n=\"3557\">13</sup> להיות כולל מבחי' נפש דוד עד בחי' נשמת משיח שהוא בחי' יחידה כו' וכידוע, וא\"כ הדבר שהי' הגבה מאד נעלה מצד עצם נשמתו א\"כ מה הי' עבודתו בקדש להוסיף אור כי מה יתן ומה יוסיף על מדריגה גבוה כזאת, אך ידוע מה דכתיב וינחהו בגן עדן<sup data-n=\"3558\">14</sup> לעבדה ולשמרה שכל עבודתו הי' לתקן את הג\"ע וענין תיקונו הי' להמשיך מבחי' עדן עצמו (... שלמעלה מנהר היוצא מעדן ממנו כו'. ..) דכתיב בי' עין לא ראתה<sup data-n=\"3559\">15</sup>, ועל ידי עבודתו והילוכו בקדש בבחי' השתחוואה וביטול במציאות (... כמאמר רז\"ל שהי' אומר בואו ונשתחווה<sup data-n=\"3560\">16</sup> כו'. ..) המשיך בחי' ההעלם דעדן הנ\"ל לבא לידי ראי'",[["3545","1","<b>והניף הכהן אותם</b>: הנחת ר\"ה ממאמר כ\"ק אדמו\"ר הצ\"צ.\nלמאמר זה ראה לקו\"ת צו טז, ד ואילך."],["3546","2","<b>והניף הכהן אותם על לחם הביכורים</b>: אמור כג, כ."],["3547","3","<b>הלחם למעלה. . במשנה דמנחות</b>: סא, א."],["3548","4","<b>אילן שאכל אדה\"ר חטה היתה</b>: ברכות מ, סע\"א. ראה גם לקמן מאמר ד\"ה בשברי לכם הא' על יד הערה 14 ואילך. לקו\"ת צו יז, ד. מאמרי אדה\"א במדבר ח\"ב ע' תיח."],["3549","5","<b>חטה הוא כ\"ב אתוון דאורייתא</b>: ראה זהר בלק קפח, ב. ת\"ז תס\"ט (קיד, א. ב)."],["3550","6","<b>אמרת ה' צרופה</b>: תהלים יח, לא."],["3551","8","<b>דוד. . נפש</b>: ראה גם מבוא שערים ש\"ב ח\"ג, פ\"ט. ע\"ח שער תיקון הנוקבא של\"ד, פ\"ג. סידור שחרית נו, ג. סה\"מ תרל\"ה ח\"א ע' רסו. וש\"נ."],["3552","9","<b>ומשה. . נשמה</b>: ראה גם סה\"מ תרל\"ה שם. ס' הגלגולים פע\"ב (מהרח\"ו זלה\"ה)."],["3553","7","<b>אדה\"ר. . בס' הגלגולים. . מיחידה דאצי'. . דעשי'</b>: ראה שם פ\"א. וראה גם מג\"ע אופן קעה. תו\"ח שמות ח\"א יז, א הערה 705."],["3554","10","<b>משיח. . יחידה</b>: ראה לקוטי הש\"ס להאריז\"ל קדושין (יא, סע\"ב). ס' הגלגולים פ\"ס. כס\"מ לת\"ז תי\"ב ס\"ח (הובא באוה\"ת לך כרך ד ע' 1460). סתכ\"ב. סה\"מ תרל\"ה שם. סה\"מ ליקוט ח\"ב ע' סח בשם המד'. עזר\"ת ע' נה: במד\"ר. סה\"מ מלוקט ח\"ד ע' מ. וש\"נ. סה\"ש תנש\"א ח\"ב ע' 776. וש\"נ. לקמן מאמר ד\"ה והתהלכתי תרכ\"ב בסופו."],["3555","11","<b>ישכיל. . עבדי</b>: ישעי' נב, יג."],["3556","12","<b>מאד אותיות אדם</b>: ראה זהר רע\"מ פינחס רמו, ב. ב\"ר פ\"ח, ה. פ\"ט, יב."],["3557","13","<b>דאדם ר\"ת אדם דוד משיח</b>: ראה ס' הגלגולים פ\"א. תו\"ח שמות ח\"א מז, ב ובהערה 157."],["3558","14","<b>וינחהו בגן עדן</b>: בראשית ב, טו."],["3559","15","<b>עדן. . עין לא ראתה</b>: ראה ברכות לד, ב. ישעי' סד, ג."],["3560","16","<b>שהי' אומר בואו ונשתחווה</b>: תהלים צה, ו. ראה זהר ויחי רכא, ב. אמור קז, ב. ת\"ז תנו (צ, ב). מאמר ד\"ה זה היום תחלת מעשיך תשמ\"א פ\"ו. וש\"נ (קונט' ר\"ה תשמ\"ח — נדפס בסה\"מ מלוקט ח\"ב ע' קג)."]]],[4801940182,"והתגלות בג\"ע וע\"ד שיהי' לימות המשיח ענין הגילוי דרזין ורזי דרזין דאורייתא, ועד\"ז הי' באדה\"ר קודם החטא להמשיך בחי' רזין שבהעלם דעדן שלמעלה מבחי' ראי' והתגלות כנ\"ל שיבא לידי ראי' והתגלות לנשמות ומלאכים הנהנין מזיו השכינה כו' וד\"ל.\n<b>ולהבין</b> ענין זה בתוס' ביאור צריך להבין מתחלה ענין ההפרש בין מתן תורה שהי' בימי משה שלא נתנה רק תורה הנגלית ובין מתן תורה דעתיד על ידי משיח שהוא ענין הנתינה דסתים דאורייתא, ויובן בהקדים ענין ההפרש בין קי\"ס דמשה ובין בקיעת הנהר דלעתיד כמ\"ש והניף ידו על הנהר<sup data-n=\"3561\">17</sup> כו', דהנה ענין קי\"ס לא הי' רק להעביר את ישראל דרך הים שזה הי' יכול להיות על ידי תחבולה אחרת שע\"פ טבע ולמה הי' צריך להפוך הטבע. אך עיקר הכוונה כדי שעי\"ז יהי' הכנה למתן תורה<sup data-n=\"3562\">18</sup>, וכן בקיעת הנהר דלעתיד יהי' הכנה למ\"ת דלעתיד, וא\"כ יש להבין למה הי' קי\"ס לי\"ב גזרים כנגד י\"ב שבטים כידוע בענין לגוזר ים סוף לגזרים<sup data-n=\"3563\">19</sup> שהי' י\"ב גזרים לי\"ב שבטים שכל אחד עבר בגזר מיוחד כנגדו ולעתיד נאמר והכהו לשבעה נחלים<sup data-n=\"3564\">20</sup> בלבד, וידוע שזהו נגד ג' אבות וד' אמהות<sup data-n=\"3565\">21</sup> ולמה לא יהי' לעתיד ג\"כ י\"ב גזרים כנגד י\"ב שבטים או הי' צריך להיות בקי\"ס ג\"כ ז' גזרים נגד מספר האבות ואמהות כו'.\n<b>אך</b> ידוע דבחי' ים סוף הוא מדריגת הדבור<sup data-n=\"3566\">22</sup> עליון שהוא בחי'<sup data-n=\"3567\">23</sup> מל'<sup data-n=\"3568\">24</sup> דאצי', כי כמו שהים הוא מכסה ומסתיר על כל הברואים שבתוכו כך הדבור הוא מכסה ומסתיר על כל מיני שפע וגילוי אור הנמשכים מעשר כחות הנפש לזולתו שלא נמשך פנימיותם כמו שהוא רק הארה חיצוני' בלבד ועי\"ז יוכל המקבל לקבל כו' כמו השכל המתלבש באותיות הדבור לזולתו הנה האותיות מסתירים לגמרי על השכל, וראי' שכל מי שאין לו שכל כמו הקטן אע\"פ שהוא מבין את האותיות מ\"מ לא יבין את השכל המלובש בהם רק מי שהוא בר שכל הוא מבין ע\"י שכלו השכל הגנוז באותיות כו' ונמצא שהאותיות מסתירים לגמרי את השכל כו'. וכך הוא למעלה בבחי' דבר הוי' שכל השפעות דע\"ס דאצי' מתלבשים בו ונסתרים בו לגמרי והוא המכסה עליהם כמו הים המכסה על הברואים שבתוכו, ונמצא שעצם אור האלקי הוא מוסתר ונעלם לגמרי ולא נגלה ממנו רק הארה דהארה להוות ולהחיות",[["3561","17","<b>והניף ידו על הנהר. . למ\"ת דלעתיד</b>: ראה גם לעיל מאמרי ד\"ה הפך ים הא'־ הב'־ הג' בתחלתם."],["3562","18","<b>קי\"ס. . הכנה למתן תורה</b>: ראה שער האמונה לב, ב ובהערה 9. תו\"ח בשלח ח\"א קמח, ג. וש\"נ. הערה שלפנ\"ז. פלח הרמון בשלח ע' קס."],["3563","19","<b>קי\"ס לי\"ב גזרים. . לגוזר ים סוף לגזרים</b>: תהלים קלו, יג וברש\"י שם. ראה שער האמונה סח, ב ובהערה 22."],["3564","20","<b>והכהו לשבעה נחלים</b>: ישעי' יא, טו."],["3565","21","<b>נגד ג' אבות וד' אמהות</b>: ראה לקו\"ת צו כאן טו, ד. יז, ב."],["3566","22","<b>ים. . הדבור</b>: ראה גם לקו\"ת צו כאן טז, ד. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רנו וע' רסח."],["3567","23","<b>ים סוף. . בחי' מל'</b>: זהר רע\"מ פינחס רנו. ב."],["3568","24","<b>הדבור. . מל'</b>: ראה זהר לך פו, ב. ע\"ח שער מוחין דצלם שכ\"ג, ספ\"ה. מאמרי אדה\"א דברים ח\"ב ע' שפה. וש\"נ."]]],[4801940239,"הנבראים כו' ולכן אין ערוך לבחי' הנבראים לגבי מקורם האלקי כמו מלאך מיכאל דבריאה שהוא בחי' אה' ושרשו מחסד דאצי' כו' אין ערוך אה' זאת שהיא בגדר וסוג נברא בע\"ג לגבי מקורה האלקי הבלתי מוגבל וכן אין ערוך מבחי' גבריאל שהוא מלאך נברא מאין ליש לגבי מקורו האלקי בחי' גבו' דאצי', וזהו בחי' י\"ב בקר והים עומד עליהם מלמעלה<sup data-n=\"3569\">25</sup> כי ד' מחנות<sup data-n=\"3570\">26</sup> כנגד ב' ידים וב' רגלים<sup data-n=\"3571\">27</sup> כ\"א כלול מג' פרקין<sup data-n=\"3572\">28</sup> הו\"ע י\"ב בקר הנמשכים מבחי' חו\"ג נו\"ה<sup data-n=\"3573\">29</sup> דאצי' (... כי אע\"פ שהם בחי' ח\"ג ת\"מ ידוע דאיהו בנצח ואיהי בהוד<sup data-n=\"3574\">30</sup> כו' וד\"ל. ..) המה נמשכים דרך הדבור העליון נמצא שהדבור הוא בחי' מקיף עליהם מלמעלה ורק הארה בעלמא נמשך ממנו שעי\"ז התהוותם וחיותם מאין ליש כו' וד\"ל.\n<b>ועד\"ז</b> יובן ג\"כ ענין הי\"ב שבטים שהם לנגד ד' מחנות שכינה<sup data-n=\"3575\">31</sup> רק שהמה בפנימי' ששרשם באצי'<sup data-n=\"3576\">32</sup> נמשך מבחי' חג\"ת והמה בחי' ענפי המדות שהם האבות אברהם יצחק ויעקב ששרשם בחי' חג\"ת דאצי'<sup data-n=\"3577\">33</sup> והשבטים הם ענפים והאורות<sup data-n=\"3578\">34</sup> הנמשכים מן המדות דאצי' ומשתלשלים למטה ע\"י הדבור עליון בעולם הבריאה ולכן נק' שבטים כמו השבטים של האילן שיוצאים להלאה מן האילן אעפ\"כ בשרשם המה מקושרים בעיקר האילן עד שע\"י כפיפת בשבט<sup data-n=\"3579\">36</sup> למטה מטה נכפף עיקר האילן<sup data-n=\"3580\">35</sup> עמו כך השבטים המה בעולם הבריאה<sup data-n=\"3581\">37</sup> בבחי' נבראים מאין ליש משרשם שבאצי' והמה בבחי' ריחוק בתכלית משרשם כי אין ערך בע\"ג לגבי בלתי בע\"ג, אך אעפ\"כ יש להם שרש באצי' עצמו בבחי' המדות דאצי' הנק' אבות וכאשר יתעורר מהות מדריגתם שבעולם הבריאה יתעורר עי\"ז שרשם שבאצי' כו' וד\"ל.\n<b>אך</b> להבין ענין מדריגותם מהו, הנה ידוע דהשבטים נמשכים מבחי' יעקב שמדתו הוא מדה\"ר<sup data-n=\"3582\">38</sup> ונמצא שהשבטים הם ג\"כ בחי' הרחמים<sup data-n=\"3583\">39</sup> רק שמדריגתם הוא",[["3569","25","<b>י\"ב בקר והים עומד עליהם מלמעלה</b>: מל\"א ז, כה. מד. דהי\"ב ד, טו."],["3570","26","<b>ד' מחנות</b>: זהר במדבר קיח, ב."],["3571","27","<b>ד' מחנות. . רגלים</b>: ראה רמ\"ז לזהר במדבר קיח, ב."],["3572","28","<b>ידים. . רגלים. . מג' פרקין</b>: ראה זהר ויחי רמא, א. לקמן ביאור מאמר ד\"ה והתהלכתי תר\"ב על יד הערה 25. ביאוה\"ז במדבר פה, א. שה\"א פנ\"ה פז, א ובהערה 16."],["3573","29","<b>חו\"ג נו\"ה</b>: ראה רמ\"ז שם."],["3574","30","<b>דאיהו בנצח ואיהי בהוד</b>: ראה ע\"ח שער אנ\"ך שי\"ט, פ\"ט. לקו\"ת שה\"ש כח, ב ובהנסמן במ\"מ לשם. מאמרי אדה\"ז הקצרים ע' ה. מאמרי אדה\"א נ\"ך ע' מ. וש\"נ."],["3575","31","<b>הי\"ב שבטים. . ד' מחנות שכינה</b>: ראה זהר במדבר קיח, ב. וביאוה\"ז לשם פה, א."],["3576","32","<b>שבטים. . ששרשם באצי'</b>: ראה גם לקמן הערה 67. לקו\"ת צו כאן יז, א. וש\"נ. ביאוה\"ז במדבר פה, ד. תו\"ח בא ח\"א קכז, ד. וש\"נ. אוה\"ת (יהל אור) תהלים ע' תפב ואילך. לעיל ע' עט. לקמן מאמר ד\"ה אם בחוקותי תר\"י על יד הערה 96. פלח הרמון יתרו ע' רנד."],["3577","33","<b>האבות. . חג\"ת דאצי'</b>: ראה מאו\"א מערכת אבות סכ\"ז. תו\"ח וארא ח\"א סא, ד. וש\"נ."],["3578","34","<b>והאורות</b>: אוצ\"ל: והארות."],["3579","36","<b>בשבט</b>: אוצ\"ל: השבט."],["3580","35","<b>שבטים כמו השבטים של האילן. . נכפף עיקר האילן</b>: ראה גם תו\"א ויצא כד, א. מאמרי אדה\"ז תקס\"ד ע' יד. תו\"ח ויצא לה, ד."],["3581","37","<b>השבטים המה בעולם הבריאה</b>: ראה לעיל הערה 32."],["3582","38","<b>יעקב. . מדה\"ר</b>: ראה זהר לך פז. ב. הנסמן במאמרי אדה\"א בראשית ע' קנו."],["3583","39","<b>יעקב. . שהשבטים. . הרחמים</b>: ראה גם תו\"א ויצא כד, א. לקו\"ת כאן יז, סע\"ג. במדבר ג, סע\"א ואילך."]]],[4801940292,"בחי' רחמים על השפלת וירידת הנשמה שבגוף (... או על מציאות הנבראים דבי\"ע שהם בחי' מ\"ת<sup data-n=\"3584\">40</sup> בוכים<sup data-n=\"3585\">41</sup> כו' כמבואר במ\"א. ..), אבל מדריגת יעקב הוא בחי' רחמים על עולמות עליונים שבעולם האצי' ששם אינו שייך הירידה וההשפלה רק שהרחמנות הוא על ריחוק הערך דאין ערוך ממאציל לנאצלים כו', והנה ידוע דאתדל\"ת זאת דהתעוררות רחמים הוא מעורר המשכת הדעת כידוע דדעת מקור הרחמים כי כל מי שיש בו דעת יותר יש בו רחמנות יותר, וכן בכלי המקבל כל מי שיש בו דעת יותר הוא כלי לקבל גילוי הרחמנות ביותר משא\"כ מי שאין בו דעת אסור לרחם עליו<sup data-n=\"3586\">42</sup> כו', וכך יובן למעלה דע\"י התעוררות הרחמים עליונים על עולם האצי' איך דאין ערוך לך מעורר המשכת ותוס' אור מבחי' אא\"ס המלובש בח\"ע דאצי' להיות נמשך ע\"י הדעת עליון דאצי' בכל עולם האצי' כל הון יקר ונעים כו', אבל ע\"י הרחמים דמדות השבטים יעורר מבחי' אא\"ס שבאצי' להיות נמשך למטה בבי\"ע רק הארה חיצוני' בעלמא ע\"י הדבור עליון הנק' ים המכסה ומסתיר כנ\"ל, וזהו בחי' המשכת אא\"ס שבחכ\"ת ע\"י ד\"ת כו' וד\"ל. אך ע\"י מה יתעורר רחמים עליונים דמדת יעקב בעל עולם האצי'<sup data-n=\"3587\">43</sup> הוא ע\"י רחמים שלמטה על השפלת וירידת הנשמה (... או השפלת וירידת הנבראים מאין ליש כנ\"ל. ..) וכנ\"ל במשל דשבטים שבאילן שכופפי' עי\"ז עיקר האילן כו' אך לא נמשך רק הארה בעלמא מאצי' לבי\"ע בדרך העלם והסתר ע\"י בחי' המל' הנק' ים כנ\"ל וד\"ל.\n<b>וזהו</b> מה שאנו אומרים בת\"ח למה תתעינו ה' מדרכיך תקשיח לבינו מיראתך שוב למען עבדיך שבטי נחלתך<sup data-n=\"3588\">44</sup>, שאצלינו בחי' מדריגות תחתונות דעשי' שנתמעט הארת האצי' מאד שזהו בחי' אה' דאברהם ויראה דיצחק (... שנכללים בבחי' רחמים עליונים שבאצי' שזהו מדת יעקב כו'. ..), לכן מבקשים שישוב אלינו ע\"י התעוררות רחמים על השפלה וירידה דנשמתינו בגוף שזהו<sup data-n=\"3589\">45</sup> מדריגות השבטים כו' וד\"ל. ..). אך ידוע ההפרש בין קיום התורה דאבות ובין מ\"ת<sup data-n=\"3590\">46</sup> דיוצאי מצרים שהאבות ע\"י עבודתם והילוכם בקדש בעילוי אחר עילוי ע\"י התעוררות רחמים כ\"א לפי מדריגתו כאו\"א המשיך הארת אא\"ס שבחכ\"ע דאצי' להאיר בבחי' תוס' אור בכל עולם האצי' אבל בבי\"ע לא נמשך רק הארה בעלמא מבחי' תוס' האור שבאצי' והארה זאת נמשכת על ידי דבור העליון המסתיר ומכסה על האור שבאצי' להיות נמשך רק הארה בעלמא ממנו כנ\"ל, אבל בחי' מתן תורה ליוצאי מצרים זה הי'",[["3584","40","<b>הנבראים דבי\"ע. . מ\"ת</b>: ראה גם לקו\"ת במדבר ג, ב."],["3585","41","<b>מ\"ת בוכי'</b>: ראה ת\"ז ת\"ה (יט, ב). הנסמן במאמרי אדה\"א בראשית ע' קג. שמות ח\"א ר\"ע לו."],["3586","42","<b>מי שאין בו דעת אסור לרחם עליו</b>: ברכות לג, א. ראה תו\"ח ויצא קעז, ד ובהערה 46."],["3587","43","<b>יעקב בעל עולם האצי'</b>: ראה ע\"ח שער העקודים ש\"ו, פ\"א."],["3588","44","<b>שאנו אומרים בת\"ח למה. . נחלתך</b>: בתיקון חצות מישעי' סג, יז. ראה תו\"ח ויצא קעז, א ובהערה 12."],["3589","45","<b>שזהו</b>: אוצ\"ל: (... שזהו."],["3590","46","<b>ההפרש. . דאבות ובין מ\"ת</b>: ראה תו\"א יתרו סח, א ואילך. מאמרי אדה\"א שמות ח\"א ע' רנז. וש\"נ. פלח הרמון שמות ע' שצח. ע' תיז ואילך."]]],[4801940342,"בבחי' גילוי למטה כמו למעלה שזהו בחי' המצות כמו מצות תפילין שמעורר המשכת אא\"ס בבחי' תוס' אור בחב\"ד דאצי' ומשם נמשך האור להתלבש בתפילין הגשמי' המונחים בראשו של האדם והאור בהם הוא מלובש למטה כמו למעלה, וכן עד\"ז בכל המצות כמו ציצית בל\"ב נתיבות<sup data-n=\"3591\">47</sup> כו', ועם זה יובן הקדמה הנ\"ל מה שהי' צריך להיות קי\"ס הכנה למ\"ת היינו בכדי שיתלבש בבחי' רחמים שלמטה בחי' רחמים עליוני' דשרש השבטים כמו שהם באצי' ועל יד<sup data-n=\"3592\">48</sup> רחמים דשבטים שבעולם דאצי' להיות נמשך ומאיר בכל עולם האצי' וגם מאיר למטה בבי\"ע כמו למעלה, ולכן הי' קי\"ס שהוא בחי' קריעת הפרסא להאיר בשבטים שרש השבטים כמו שהוא למעלה ועי\"ז יומשך המשכת התורה דאצי' למטה ממש בעשי' גשמי' במצות הגשמי' כו', ולכן הי' י\"ב גזרים לנגד י\"ב שבטים שבכל שבט ושבט יאיר עליו משרשו כמ\"ש למעלה כו' וד\"ל.\n<b>ומעתה</b> יובן ענין בקיעת הנהר דלעתיד, כי הנה בחי' נהר הוא בחי' מחשבה<sup data-n=\"3593\">49</sup> שבבחי' בינה<sup data-n=\"3594\">50</sup> דאצי', כי הנה עד\"מ בגשמי' ההפרש בין נהר לים<sup data-n=\"3595\">51</sup> שמי הים המה קוו וקיימו<sup data-n=\"3596\">53</sup>, אך מי הנהר המה נובעים בבחי' התחדשות בכל עת ורגע מבחי' המעיין, כך הוא ההפרש בין דיבור למחשבה<sup data-n=\"3597\">52</sup> שבדבור ההשפעה מוגבלת מצד שכבר הוגבלה מקודם בדבור שבמחשבה בעת שחשב איך לדבר והוא כמו הים ד\"מ, אך המחשבה עצמי' בלתי מוגבלת כלל ומאירה מן השכל בכל עת ורגע בבחי' התחדשות, והוא כמו הנהר שנמשך בבחי' התחדשות בכל עת ורגע בבחי' נביעתו מן המעיין כו'. אך גם המחשבה אף שמאיר בה אור השכל בבחי' התחדשות בתמידי' מ\"מ הוא ג\"כ בבחי' פרסא להסתיר אור השכל, כמו שאנו רואים שברק המבריק<sup data-n=\"3598\">54</sup> דחכמה אינו נתפס בבחי' התיישבות בכלי המוח, והטעם הוא מצד תוקף הגילוי של אור השכל שלא יוכל להתקבל בכלי המוח, אך כאשר נמשך ונתלבש באותיות המחשבה הנ\"ל אז מתיישב בכלי המוח והיינו מצד שאותיות המחשבה הנ\"ל מסתירים עצם אור השכל שלא יאיר כמו שהוא רק הארה חיצוני' ממנו ואותה הארה תוכל להתקבל בכלי המוח, (... כידוע דגילוי סיבת ההעלם והעלם סיבת הגילוי כו'. ..) אבל עצם אור החכמה כמו שהוא בבחי' ברק המבריק לא יוכל להתקבל בכלי המוח ומכ\"ש עצם כח המשכיל שהוא בבחי' העלם לגמרי מכל וכל ומכ\"ש בחי' מקור התענוג שהוא כח נעלם מאד ואינו מתקבל כלל בבחי' גילוי בכלי המוח רק הארה בעלמא ממנו מאיר בעת הארת השכל בכלי המוח הוא בבחי'",[["3591","47","<b>ציצית בל\"ב נתיבות</b>: ראה זח\"ג תוספת שא, א. מאמרי אדה\"א בראשית ע' שצד. וש\"נ."],["3592","48","<b>יד</b>: אוצ\"ל: ידי."],["3593","49","<b>נהר. . מחשבה</b>: ראה שה\"א צ, א ובהערה 10."],["3594","50","<b>נהר. . בינה</b>: זהר אדרא דמשכנא משפטים קכג, ב."],["3595","51","<b>ההפרש בין נהר לים</b>: ראה גם לקו\"ת כאן יז, א."],["3596","53","<b>שמי הים המה קוו וקיימו</b>: ראה פרה פ\"ח, מ\"ח. מקואות פ\"ה, מ\"ד."],["3597","52","<b>ההפרש בין נהר לים. . בין דיבור למחשבה</b>: ראה גם לעיל ע' ע."],["3598","54","<b>שברק המבריק</b>: ראה גם לקו\"ת חוקת סב, ג ובהנסמן במ\"מ לשם. תו\"ח בשלח קצז, ב. וש\"נ. לעיל ס\"ע מד."]]],[4801940389,"התיישבות על ידי אותיות המחשבה דבינה (... וכידוע בענין ועבד הלוי הוא<sup data-n=\"3599\">55</sup> דהתגלות עתיק הוא בבינה<sup data-n=\"3600\">56</sup> דוקא כו' וד\"ל. ..).\n<b>והנה</b> עם זה יובן ענין ונהר יוצא מעדן<sup data-n=\"3601\">57</sup> להשקות את הגן כו', כי הנה בחי' גליא דתורה הוא בחי' אא\"ס המלובש בחכ' עלאה בבחי' יש דחכמה שמאיר ומתפשט בכל עולם האצי' ומאיר בבי\"ע למטה כמו למעלה מצד בקיעת הדבור כנ\"ל, אבל בחי' אין דחכ' שהוא בחי' פנימיות חכמה נק' עדן אך זהו בחי' עדן דלתתא (... ע\"ד דוגמא ברק המבריק שהוא ג\"כ בבחי' העלם ואינו מתיישב בכלי המוח כו'. ..), אך בחי' עדן עילאה הוא מקור התענוג שהוא למעלה מראי' דחכמה והוא בתכלית ההעלם אך הארה המתגלי' ממנו נק' בחי' נהר שיוצא מעדן שמסתרת על עצם האור ואינו מתגלה רק הארה בעלמא להשקות את הגן שהוא ענין גילוי רזין דאורייתא לנשמות ומלאכים דג\"ע. אך בחי' עדן עצמו שהוא בחי' רזין דרזין שעליו נאמר עין לא ראתה זהו המתגלה ע\"י משיח בבחי' ראי' והתגלות ממש, והנה לגילוי בחי' זאת דעדן עצמו צריך להיות בחי' בקיעת הנהר שיאיר בחי' העדן הנעלם לבא לידי גילוי כו' וד\"ל.\n<b>אך</b> מה שצריך להיות שבעה נחלים הענין הוא שהתעוררו' המשכת בחי' עדן צריך להיות על ידי התעוררות רחמים עליונים. והנה כמו שהשבטים המה בבחי' בריאה ושרשם באצי' כך האבות המה בבחי' אצי' ושרשם למעלה מהאצי' וכמ\"ש בעבר הנהר ישבו אבותיכם<sup data-n=\"3602\">58</sup> נהר הוא בחי' בינה כנ\"ל, ובעבר הנהר הוא בחי' מדות דעתיק ואריך שהמה בלתי מוגבלים בכלים וע\"ז נאמר וחסדי מאתך לא ימוש<sup data-n=\"3603\">59</sup> וכן נאמר ברחמים גדולים אקבצך<sup data-n=\"3604\">60</sup> ומדות אלו המה שרש נשמות האבות, וזהו והכהו לשבעה נחלים שעי\"ז יתעלו מדות הרחמים דאבות לשרשם הנק' רחמים גדולים ומבואר לעיל דהתעוררות רחמים הוא גורם המשכת אא\"ס שבחכ' עלאה ולכן על ידי רחמים גדולים יתעורר כח החכמה נעלמה המיוחדת במקור התענוג הנעלם הנק' עדן לבא לידי ראי' והתגלות כנ\"ל שזהו ענין לימוד התורה דמשיח שימשיך בחי' עדן הנעלם דעין לא ראתה לבא לידי ראי' והתגלות כו', כי הלימוד דמשיח לא יהי' ללמוד דעת והשגה שהאיך יתכן שאדם אחד ילמוד עם כמה אלפים רבבות מישראל שיקומו אז ועוד דמשה ואבות המה בקיאים בכל התורה ומה ילמוד עוד עמם אלא עכ\"ל שלימודו יהי' להמשיך מעדן הנעלם לבא לידי ראי' והתגלות בעילוי אחר עילוי ולא בבחי' שמיעה והשגה בלבד.",[["3599","55","<b>ועבד הלוי הוא</b>: קרח יח, כג. ראה זהר קרח קעח, ב. תו\"א לך יא, ב. מאמרי אדה\"ז על פרשיות התורה ח\"א ס\"ע פד ואילך. תו\"ח שמות ח\"א לד, א. וש\"נ."],["3600","56","<b>דהתגלות עתיק הוא בבינה</b>: מובא בכ\"מ בשם הע\"ח — ראה תו\"ח לך פא, ב ואילך. הנסמן במאמרי אדה\"א הנחות תקע\"ז ע' ד. ביאוה\"ז להצ\"צ אחרי ע' שסד."],["3601","57","<b>ונהר יוצא מעדן</b>: בראשית ב, י. ראה גם לעיל ע' עט."],["3602","58","<b>בעבר הנהר ישבו אבותיכם</b>: יהושע כד, ב. ראה הנסמן במ\"מ לקו\"ת כאן יז, ג. וראה גם תו\"ח בשלח ח\"א קנח, ב ובהערה 405. לעיל מאמר ד\"ה להבין ההפרש בין שליו\"ט תר\"ב בסופו. וש\"נ."],["3603","59","<b>וחסדי מאתך לא ימוש</b>: ישעי' נד, י."],["3604","60","<b>ברחמים גדולים אקבצך</b>: ישעי' נד, ז [ושם: וברחמים — ראה גם תו\"ח בשלח ח\"א קעז, א. וש\"נ]."]]],[4801940433,"<b>ויובן</b> ענין הראי' ברזין דאורייתא ממה שנמצא בכתבי האריז\"ל שפעם א' למד באתון דבלעם מה שלא יוכל לדרוש בפ' שנה<sup data-n=\"3605\">61</sup> והאיך יכול להיות זה והגם שמצינו שסקירה אחת שבמחשבה כאשר יצטרך לאמרה בדבור יתרבה צירופי אותיות עד שיצטרך לדבר שעה או שתים<sup data-n=\"3606\">62</sup> ולכן אותיות המחשבה נק' אתוון רברבין לגבי אותיות הדבור כי אות א' במחשבה יכיל ריבוי צירופי אותיות בדבור אבל מ\"מ יש להם ערך זה עם זה בזמן אבל מסקירה אחת יצטרך לדרוש פ' שנה זה אינו בערך כלל וע\"כ לומר שלימודו הי' בבחי' ראי' והסתכלות ולא בבחי' שמיעה והשגה וידוע דבחי' ראי' דחכמה היא למעלה מן הזמן לגמרי ולכן כאשר יצטרך לפרשה בדבור הנופל תחת הזמן יומשך פ' שנה ויותר מזה (... רק לדוגמא בעלמא נקט הזמן דפ' שנה כו'. ..). והנה יש כמה מדריגות לאין שיעור כמו בחי' הראי' שהי' אצל רשב\"י והראי' שהי' אצל משה הי' גבוה יותר וכמ\"ש וירא ראשית<sup data-n=\"3607\">63</sup> אבל הראי' דמשיח יהי' גבוה מכולם בבחי' עדן הנעלם עצמו עין לא ראתה כנ\"ל ועל ידו יומשך ההעלם דעדן עצמו בבחי' התגלות בכללות נש\"י. והנה משה רצה שיהי' המשכה זאת דבחי' ראי' בכללות נש\"י על ידו ולכן ביקש אעברה נא ואראה את הארץ<sup data-n=\"3608\">64</sup> בכדי לפעול בחי' ראי' בכללות נש\"י אך לא פעל רק ענין השמיעה דבינה וכמאמר שמע ישראל<sup data-n=\"3609\">65</sup> כו' וד\"ל.\n<b>והנה</b> עם כל הנ\"ל יובן ההפרש בין מתן תורה שעל ידי משה ובין מ\"ת שלעתיד שעל ידי משיח, כי מ\"ת דמשה הוא בחי' גליא דתורה שהוא מה שנמשך אא\"ס המלובש בחכמה עלאה דאצי' להאיר למטה בעשי' כמו למעלה שזהו על ידי תורה ומצות הגשמיי' כנ\"ל, והמשכה זאת דתומ\"צ הוא לפי ערך ההעלאה שהוא בחי' התעוררות רחמים רבים על נפשו שזהו מדריגת השבטים שבזה מעורר שרש השבטים כמו באצי' (... כידוע בפי' ששם עלו שבטים שבטי י\"ה<sup data-n=\"3610\">66</sup> שיש בחי' שבטים דעלמא דנוק' שהוא בחי' שבטים שבעולם הבריאה ויש שבטים שבעלמא דדכורא<sup data-n=\"3611\">67</sup> כו'. ..), ועל ידי שרש השבטים מתעורר ומתגלה בנפשו בחי' רחמים דאבות שהוא בחי' פנימי' מדות דאצי' שהוא בחי' רחמים רבים על עולמות עליונים וזהו בחי' קי\"ס הכנה למתן תורה כנ\"ל, ולפי ערך התעוררות זאת כן ההמשכה דאא\"ס שבחכמה עלאה שהוא בחי' גליא דתורה כו'. אך מ\"ת דמשיח הוא בחי' המשכת חכמה הנעלמה לבא לידי גילוי שזהו המשכת והתגלות בחי' עדן וזהו בחי' סתים דאורייתא ולהמשכה זאת מוכרח להיות העלאה והתעוררות דרחמים גדולים שהוא",[["3605","61","<b>האריז\"ל. . למד. . בפ' שנה</b>: ראה פע\"ח שער ק\"ש שעהמ\"ט שט\"ז, פ\"א. שה\"א צג, א ובהערה 9. פלח הרמון יתרו ע' רנה."],["3606","62","<b>שסקירה אחת שבמחשבה. . לדבר שעה או שתים</b>: ראה שה\"א צג, ב ובהערה 15."],["3607","63","<b>וירא ראשית</b>: ברכה לג, כא."],["3608","64","<b>אעברה נא ואראה את הארץ</b>: ואתחנן ג, כה. ראה מאמרי אדה\"ז תקס\"ג ח\"ב ע' תרסח ואילך. תקס\"ד ע' רא ואילך וע' רד. לקו\"ת ואתחנן ג, ג-ד. שע\"ת קד, ב ואילך. מאמרי אדה\"א הנחות תקע\"ז ע' רעא."],["3609","65","<b>שמע ישראל</b>: ואתחנן ו, ד."],["3610","66","<b>ששם עלו שבטים שבטי י\"ה</b>: תהלים קכב, ד."],["3611","67","<b>שבטים דעלמא דנוק'. . דדכורא</b>: ראה זהר פקודי רכט, ב. רל, א. שע\"ת צב, ג ובהערה 28. לעיל הערה 32."]]],[4801940471,"בחי' האבות כמו שהם בשרשם בעבר הנהר ולכן צריך להיות מקודם בחי' בקיעת הנהר לשבעה נחלים כנ\"ל וד\"ל.\n<b>ועם</b> זה יובן מה שאנו אומרים אתה בחרתנו<sup data-n=\"3612\">68</sup> מכל העמים ולכאורה מה הוא הרבותא דבחירה זאת הלא<sup data-n=\"3613\">69</sup> צריך להיות כן, כי שרש האוה\"ע הם כמר מדלי מותרות ופסולת הנמשך מבחי' שתי מדות חו\"ג דאצי' בדרך ריבוי צמצומים עד למטה בעולם העשי' והפסולת הנשאר אחר הבירור בעולם העשי' מהארת המדות הנ\"ל הוא מקור חיות אוה\"ע, משא\"כ נש\"י שרשם בשרש המדות דאצי' כמו שהם למעלה מן החכמה שהוא בחי' רחמים גדולים הנ\"ל ובחי' וחסדי חסד דלגאו כנ\"ל וא\"כ המה ממילא מובדלים מן העמים מצד שרש נשמותיהם (... וכמארז\"ל ע\"פ ממני פריך נמצא<sup data-n=\"3614\">70</sup> מובדלים נפשותיהם של ישראל כו'. ..), ולמה צריך לבחירה כי הבחירה לא יפול רק בשני דברים שוים והוא בוחר באחד מחמת רצונו אליו בלי טעם כלל, אך עם כל הנ\"ל יובן שזאת הבחירה הוא להמשיך אליהם בחי' עדן הנעלם הנ\"ל דעין לא ראתה שהוא בחי' אא\"ס המלובש בחכמה המיוחדת במקור עונג הנעלם כנ\"ל שהוא קדוש ומובדל אפי' משרש נש\"י, כי אין ערוך אפי' משרש נש\"י שהוא בחי' רחמים גדולים ובחי' וחסדי לגבי בחי' זאת דעדן (... כי בחי' רחמים גדולים שרש נש\"י הוא בחי' ז\"ת דע\"י המלובשים בנאצלים משא\"כ בחי' עדן הוא בחי' ג\"ר דע\"י שהוא בחי' תחתונה שבעצמי' המאציל ולכן הגם שבכל הפרצופים יש ערך מבחי' המדות שבהם לג\"ר שבהם וכנ\"ל דבחי' העלאה דהתעוררות רחמים מעורר המשכה חכמה ודעת אבל בע\"י אין ערוך זה לזה כו' ולכן צריך בחירה כמשי\"ת. ..), אך אעפ\"כ בחר בנו לייחד אותנו ולרומם אותנו במקור עונג הנעלם הנק' עדן ועל ידי בחירה זאת יש בנו כח לעורר על ידי רחמים רבים בחי' עדן הנ\"ל (... והבחירה זאת הוא מבחי' רצון הנעלם שלמעלה מן הטעם ועונג כידוע דאין טעם לרצון<sup data-n=\"3615\">71</sup> אפי' בחי' טעם הכמוס ועונג הנק' טוב טעם כו' וד\"ל. ..). ואפשר<sup data-n=\"3616\">72</sup> שזהו ענין ברכת אשר בחר בנו שבברכת התורה שהוא השבח והודאה על אשר בחר בנו ברצונו הפשוט ונתן לנו את תורתו סתים דאורייתא בחי' עדן הנעלם כנ\"ל וד\"ל). ועם זה יובן ג\"כ ענין עבודת אדה\"ר בג\"ע קודם החטא שהי' במדריגה זאת שיהי' לעתיד להמשיך בחי' עדן שלמעלה משרש נשמתו שיבא לבחי' התגלות בגן עדן להאיר לנשמות ומלאכים כנ\"ל. וזהו מה שהוסיף בעבודתו בקדש להמשיך בחי' אור מרומם והגבה מאד נעלה יותר מבחי' מדריג' נשמתו כמ\"ש מצד עצמה כו' (... וכנ\"ל דשרש כל הנשמות הוא בבחי' ז\"ת דע\"י אבל בחי' עדן הוא בחי' ג\"ר דע\"י כו'. ..).",[["3612","68","<b>שאנו אומרים אתה בחרתנו</b>: בתפלת העמידה ליו\"ט. ראה גם לקמן מאמר ד\"ה אם בחוקותי הג' על יד הערה 146. מאמרי אדה\"ז כתובים ח\"א ע' עה."],["3613","69","<b>הלא</b>: אולי כ\"ה בהכת\"י."],["3614","70","<b>ממני פריך נמצא</b>: הושע יד, ט. ראה ע\"ח שער הקליפות שמ\"ח, פ\"ב."],["3615","71","<b>דאין טעם לרצון</b>: ראה של\"ה בית ה' ד, ב בהגה. מאמרי אדה\"א דברים ח\"א ע' כא. וש\"נ. תו\"ח בא ח\"א פט, ד. וש\"נ."],["3616","72","<b>ואפשר</b>: אוצ\"ל: (... ואפשר."]]],[4801940506,"<b>ובזה</b> יובן ג\"כ במה שנחשב לו לחטא ענין אכילת חטה כי בחי' חטה שרשה בחכמה ודעת<sup data-n=\"3617\">73</sup> דעולם התהו כידוע דלכן אין התינוק יודע לקרות<sup data-n=\"3618\">74</sup> אבא עד שיטעום טעם דגן כי נפש אדם הוא בחי' חכמה ודעת דעולם התיקון משא\"כ חטה שהיא בחי' צומח שרשה בבחי' הדעת דעולם התהו ולכן ממשיך דעת בתינוק מבחי' ההעלם לבא לידי גילוי אור, והנה בחי' חטה כ\"ב אתוון דאורייתא הוא בחי' חכמה עלאה דתורה המתלבש בצירופי אותיות שלמעלה מבחי' חכמה דתהו ותיקון רק שנמשך ובא בכל העולמות לברר בירורים כידוע דבחכמה אתברירו<sup data-n=\"3619\">75</sup>, וכללות ענין בבירור<sup data-n=\"3620\">76</sup> הוא לאהפכא מחושך התחתון לאור שהוא בחי' ביטול היש לאין ועי\"ז מעורר ג\"כ חשך העליון דתהו בחי' ההעלם שלמעלה מגילוי שיבא לידי גילוי אור וכל זה הוא בחי' גליא דתורה המתלבש באותיות לברר בירורים (... כי כללות ההשתלשלות נכלל בב' בחי' העלם וגילוי שזהו בחי' תהו ותיקון ונמצא שגם התהו הוא בבחי' השתלשלות<sup data-n=\"3621\">77</sup>, וא\"כ כללות החכמה דתורה הנמשך למטה בעולם הגשמי דעשי' להפך מחושך התחתון לאור ומלובשת ג\"כ בחכמה עליונה שבעצם ההעלם דעולם התהו להמשיך ההעלם דחשך העליון לידי גילוי אור לפי ערך הבירור והעלאה דעולמות זה הכל הוא בחי' גליא דתורה מבוררת בתכלית כנ\"ל בענין אמרת הוי' צרופה (... כי כל מברר לא יוכל לברר כ\"א שהוא מבורר בתכלית וכמ\"ש במ\"א בענין סמוך לפלטין שלך<sup data-n=\"3622\">78</sup> כו'. ..) מ\"מ מצד שהיא מתלבשת בבחי' טו\"ר לברר בירורים לכן נק' ע\"ש המתברר כו' וד\"ל. אבל עבודת אדה\"ר הי' בחי' המשכת סתים דאורייתא שלמעלה מהשתלשלות לגמרי ובחי' זאת היא למעלה מכל בחי' הבירורים והמשכות שעל ידי הבירורים, ולכן לא הי' צריך להתלבש בבחי' גליא דתורה בכדי לברר בירורים שזהו בחי' חטה כ\"ב אתוון דאורייתא, רק שהבירור בעולמות הי' נעשה ממילא על ידי המשכת אור שלו בג\"ע שזהו בחי' המשכת המאור בעצמו סתים דאורייתא לבא לידי גילוי אור כו' (... וכמשל האבוקה הגדולה שמושך ממילא כל הניצוצות אליו. ..) ולכן לא הי' צריך להלביש את עצמו בבחי' חטה כ\"ב אתוון דאורייתא, ולכן כשהלביש את עצמו בבחי' זאת נחשב לו לחטא כו' וד\"ל.\n<b>ומעתה</b> יובן ענין הלחם וכבשים ותנופתם ומה שהניף הלחם על הכבשים דוקא, כי הנה בחי' לחם הוא בחי' חכמה דתורה הנגלית וכבשים הוא בחי' האבות שהוא בחי' מדה\"ר וכנ\"ל שבחי' התעוררות רחמים הוא בחי' העלאה לעורר עי\"ז המשכה דחכמה דתורה (... וכמ\"ש היתה לי דמעתי לחם<sup data-n=\"3623\">79</sup> שעל ידי דמעות",[["3617","73","<b>חטה. . ודעת</b>: ראה לקו\"ת במדבר י, ג. יא, ג. מאמרי אדה\"א ויקרא ח\"א ע' לג, וש\"נ. שה\"א ח, ב."],["3618","74","<b>אין התינוק יודע לקרות</b>: ראה ברכות מ, סע\"א. מאמרי אדה\"א דברים ח\"א ע' רמה. וש\"נ. תו\"ח בא ח\"א צה, ב. וש\"נ. לעיל ע' מא."],["3619","75","<b>דבחכמה אתברירו</b>: ראה זהר היכלות פקודי רנד, סע\"ב. הנסמן במאמרי אדה\"א דברים ח\"א ע' רצה. שמות ח\"ב ע' שכא. תו\"ח תשא ח\"ב שפד, ד ואילך."],["3620","76","<b>בבירור</b>: כנצ\"ל: הבירור."],["3621","77","<b>השתלשלות</b>: אוצ\"ל: השתלשלות. ..)."],["3622","78","<b>כל מברר. . בענין סמוך לפלטין שלך</b>: ראה גם לעיל סוף מאמר ד\"ה וספרתם תקצ\"ח. וש\"נ."],["3623","79","<b>היתה לי דמעתי לחם</b>: תהלים מב, ד."]]],[4801940538,"ממרירות שמעורר רחמים רבים על נפשו על עוצם ירידתה מאיגרא רמה<sup data-n=\"3624\">80</sup> כו' מזה נמשך אח\"כ המשכת לחם דתורה כו'. ..), אך בחי' סתים לא נתגלה רק יתגלה לע\"ל על ידי המשיח, אך אעפ\"כ היום לעשותם כתיב ולמחר לקבל שכרם<sup data-n=\"3625\">81</sup> שהקיבול שכר הוא גילוי בחי' עדן סתים דאורייתא הנ\"ל, אך צריך לעשות הכנה עכשיו להמשכת בחי' עדן שיומשך בבחי' גילוי לימות המשיח, ועוד י\"ל שגם עכשיו נמשך רק שהוא בהעלם ולע\"ל יתגלה, וזהו ענין התנופה שעל ידי תנופת הכבשים הוא מעלה ומרומם בחי' המדות דאצי' לשרשם בעבר הנהר בחי' רחמים גדולים הנ\"ל ועל ידי תנופת הלחם הוא מרומם בחי' חכמה דתורה לשרשה בבחי' חכמה נעלמה המיוחד במקור עונג הנעלם ונמצא שגם עכשיו בעת לימודו ממשיך סתים דאורייתא בהעלם וכאשר מעורר רחמים על נפשו מעורר בהעלם בחי' רחמים גדולים הנ\"ל, וזהו תנופת הלחם על הכבשים דוקא כי שתי הלחם בשרשם המה בבחי' עדן למעלה משרש הכבשים שהוא בחי' המדות דעבר הנהר כנ\"ל וד\"ל (... אך לכאורה אינו מובן מהו ההפרש בין המשכת בחי' עדן סתם דאורייתא להמשכת גליא דאורייתא שהוא בחי' ח\"ע הגלוי' כי באמת גם אא\"ס שבחכ\"ע הוא ג\"כ מלובש במצות הגשמיי' בהעלם ולא בגילוי כי אין שינוי בגוף התפילין מקודם הנחתן לאחר הנחתן רק לעתיד יתגלה האור מתוך הלבוש כמ\"ש ולא יכנף<sup data-n=\"3626\">82</sup> כו' שלא יהי' מוסתר בכנף ולבוש כמו עכשיו, ולפי הנ\"ל גם בחי' סתים דאורייתא בחי' עדן נמשך ג\"כ עכשיו בהעלם וא\"כ למה אנו אומרים שעכשיו הוא רק מ\"ת הנגלית ומ\"ת הנסתרת תהי' לע\"ל ממ\"נ אם אנו קורין ניתנה המשכה בהעלם א\"כ גם סתים דאורייתא ניתנה לנו ואם אין אנו קורין ניתנה כ\"א להמשכה בגילוי א\"כ גם גליא דתורה שהוא בחי' אא\"ס שבחכמה עלאה לא ניתן עדיין כי הוא נמשך בהעלם ולא בגילוי כו', אך הענין יובן ע\"פ הידוע שיש ב' מיני חשך והעלם הא' העלם וחשך התחתון שהוא בחי' הגשמי' המסתיר על הרוחני' או היש המסתיר על בחי' אין או הכלי המסתיר ומגביל את האור כו', והב' הוא בחי' חשך העליון שהוא מקור כל מיני גילוי אור רק שנק' בשם חשך ע\"ש השלילה שהוא מושלל מכל מיני גילוי אור, אך מה שאנו אומרים למעלה מושלל אין הכוונה שהוא מושלל באופן שלא יתהווה ממנו שום גילוי אור אלא אדרבה הוא מקור לכל מיני גילוי אור רק אעפ\"כ אינו נתפס בהם כי כל ההמשכות וכל הגילוים הנמשכים ממנו אין פועלים בו שום שינוי ונשאר בבחי' קדושתו העצמי' כמו קודם ההמשכה והגילוי כו'. והנה מבואר למעלה במאמר ועשית חג שבועות<sup data-n=\"3627\">83</sup> שהשם זה דחשך הוא שם לעצמי' האור מצד המקבלים לבד פי' שבלתי יכולים להרגיש מהות עצמו' אא\"ס ית' אם לא בהרגשה זאת שהוא מושלל ומובדל מכל מיני גילוי א\"כ בחי' זאת דחשך הוא ג\"כ לבוש לאור העצמי וכמאמר ישת חשך סתרו<sup data-n=\"3628\">84</sup>. ועתה יובן ענין הנ\"ל דמה שמעוררים וממשיכים עכשיו בחי' סתים דאורייתא שהוא בחי' עדן בהעלם הכוונה להלבוש שכללות האור הנ\"ל בבחי' הלבוש דחשך שהוא",[["3624","80","<b>מאיגרא רמה</b>: ראה חגיגה ה, ב. רש\"י איכה ב, א. תו\"ח שמות ח\"א ד, ג. וש\"נ."],["3625","81","<b>היום לעשותם. . ולמחר לקבל שכרם</b>: ואתחנן ז, יא. ראה ערובין כב, א."],["3626","82","<b>ולא יכנף</b>: ישעי' ל, כ."],["3627","83","<b>במאמר ועשית חג שבועות</b>: כנראה הכוונה להמאמר שנמצא בבוך 1305 ע' סח ואילך. יודפס בעז\"ה בפלח הרמון במקומו."],["3628","84","<b>ישת חשך סתרו</b>: תהלים יח, יב."]]],[4801940561,"בחי' העלם העליון ונק'<sup data-n=\"3629\">85</sup> מצות<sup data-n=\"3630\">86</sup> התחברות מיני' ובי'. ..) (... מפנימי' הכתר לחיצוני' הכתר שנק' בשם חשך סתרו<sup data-n=\"3631\">87</sup> כידוע וד\"ל. ..), ולכן לא נק' זה בשם ניתנה כי לא נמשך למטה בעולמות רק נעשה והוכן בבחי' מקור להמשכה וגילוי אור שזהו בחי' חשך כנ\"ל, אך בחי' חכמה עלאה הגלוי' היא הנמשכת ומתלבשת בבחי' כלים דאצי' וכן למטה בבי\"ע בבחי' היש שבהם וכן למטה מטה בעשי' שלנו בגשמיי' שבה ונק' זה בשם נתינה כי האור כבר נמשך למטה רק שהוא מלובש בלבוש המסתיר ועל ידי זיכוך הלבוש ממילא יתגלה, וזהו בחי' מצות הוי' כו' וד\"ל. ולכן כתיב ונגלה כבוד הוי'<sup data-n=\"3632\">88</sup> ולא נמשך כי כבר נמשך אור שם הוי' למטה ואינו חסר רק הגילוי מתוך הלבוש ולע\"ל כאשר יושלם הבירור בעת רצון הוי' אזי יוסר ההסתר דלבוש עד שהלבוש יהי' מזוכך מאד ולא יסתיר כלל וממילא יתגלה האור כו' וד\"ל<sup data-n=\"3633\">89</sup>.",[["3629","85","<b>ונק'</b>: אוצ\"ל: (... ונק'."],["3630","86","<b>מצות</b>: אוצ\"ל: מצותי."],["3631","87","<b>מפנימי' הכתר. . חשך סתרו</b>: ראה זהר רע\"מ פינחס רכה, א. לקו\"ת ויקרא א, א."],["3632","88","<b>ונגלה כבוד הוי'</b>: ישעי' מ, ה."],["3633","89","<b>וד\"ל</b>: אוצ\"ל: וד\"ל. ..)."]]],[4801940119,"<b>רישומי דברים ביאור על והניף הכהן אותם</b>\n<b>להבין</b> שרשי הדברים הנ\"ל<sup data-n=\"3634\">1</sup>. הנה כתיב אדם ובהמה תושיע ה'<sup data-n=\"3635\">2</sup> שיש יתרון באדם מבבהמה ומצד אחר יש יתרון בבהמה מבאדם. ומתחלה י\"ל היתרון באדם על הבהמה כי הנה אנו רואים בכל הבע\"ח שאין בכאו\"א רק מדה פרטי'<sup data-n=\"3636\">3</sup> ואינה מורכבת מזולתו כלל כמ\"ש כל עוף כנף למינהו<sup data-n=\"3637\">4</sup>, כמו שאנו רואים בנשר שהוא רחמני<sup data-n=\"3638\">5</sup> בטבעו לא ימצא בו מדת האכזריות כלל, וכן בעורב שהוא אכזרי<sup data-n=\"3639\">6</sup> בטבעו לא ימצא בו מדת הרחמנות כלל כו', וכ\"ה בשרשם עד רום המעלות במרכבה עליונה דבי\"ע שהמלאכים נק' בשם עופות כמ\"ש ועוף יעופף ועוף זה מיכאל יעופף זה גבריאל<sup data-n=\"3640\">7</sup> כאו\"א אין בו רק<sup data-n=\"3641\">8</sup> מדה פרטי' כמו מחנה מיכאל באהבה",[["3634","1","<b>להבין שרשי הדברים הנ\"ל</b>: הנחת ר\"ה מדרוש כ\"ק אדמו\"ר הצ\"צ.\nביאור זה מיוסד על הביאור שנדפס בלקו\"ת אמור לז, ג. וראה הנרשם במ\"מ לשם.\nראה עוד ע\"ד המאמר לקמן ברשימת הכת\"י."],["3635","2","<b>אדם ובהמה תושיע ה'</b>: תהלים לו, ז."],["3636","3","<b>הבע\"ח. . רק מדה פרטי'</b>: ראה רמב\"ם בהקדמה לפי' המשניות (ד\"ה אחר כן ראה) הובא בלקו\"ת כאן."],["3637","4","<b>כל עוף כנף למינהו</b>: בראשית א, כא."],["3638","5","<b>בנשר שהוא רחמני</b>: ראה ירושלמי פאה פ\"א, ה\"א. תנחומא עקב ב. לקו\"ת אמור כאן לז, ג. האזינו עז, ג. עח, א ואילך. מאמרי אדה\"א דברים ח\"ג ע' תתעט. וש\"נ. תו\"ח בשלח ח\"א ריג, ב ובהערה 213."],["3639","6","<b>בעורב שהוא אכזרי</b>: ראה ירושלמי־ תנחומא־ לקו\"ת אמור־ מאמרי אדה\"א־ ותו\"ח שבהערה שלפנ\"ז."],["3640","7","<b>ועוף יעופף. . מיכאל. . גבריאל</b>: בראשית א, כ. ראה זהר בראשית מו, ב. מאמרי אדה\"א קונטרסים ע' שעו. וש\"נ. תו\"ח בראשית יט, א ובהערה 5."],["3641","8","<b>רק</b>: ניתוסף ע\"פ אג."]]],[4801940183,"וחסד לא ימצא בו מדת היראה ולכן נק' שר של מים<sup data-n=\"3642\">9</sup>, וכן מחנה גבריאל ביראה וגבורה לא ימצא בו מדת אהבה ולכן נק' שר של אש<sup data-n=\"3643\">10</sup>, ולכן אין מלאך אחד עושה שתי שליחות הפכים<sup data-n=\"3644\">11</sup> כי לא ימצא בו רק מדה אחת חסד או גבורה ולא מהיפוכו כלל (... ומה שמצינו התכללות במלאכים הוא מכח יותר נעלה המאיר עליהם ולא מכח עצמם<sup data-n=\"3645\">12</sup> כו' וד\"ל. ..), משא\"כ באדם מצינו שהוא כולל בעצמו כל הכחות כמו אהוי\"ר או שנאה וחסד או גבורה ורחמים, ועוד כולל בתוכו מלבד ז' המדות ג' שכליים חב\"ד ולא ימצא בעולם שום כח רוחני הנמצא בדצ\"ח שלא יהי' נכלל באדם. והטעם לזה כי שרש דצ\"ח עד רוהמ\"ע<sup data-n=\"3646\">13</sup> הוא במרכבה עליונה ושרשם היותר ראשון הוא במרכבה דבריאה פני ארי' להימין<sup data-n=\"3647\">14</sup> כו' שהמה ג\"כ נבראים מאין ליש והמה בבחי' הפירוד והתחלקות זמ\"ז ע\"ש שמתהווים מכח האלקי כ\"א ממקור מוצא מיוחד (... ע' במאמר וספרתם לעיל<sup data-n=\"3648\">15</sup>. ..), ולכן אין בשרשם שהמה המלאכים בכ\"א רק הארה פרטי' ומיוחדת ולכן למטה בבע\"ח גשמיי' לא ימצא בכ\"א רק מדה פרטיות ובצומח בכ\"א סגולה וחיות פרטי וכן בדומם כו', משא\"כ האדם אנו רואים שהוא בטבעו מושל ורודה על כל הבהמות והיינו מצד ששרשו בכח האלקי עצמו המקור לכל הנבראים, וידוע שמקור המהווה מאין ליש הוא בחי' מל' כמאמר הכתוב מלכותך מלכות כל עולמים<sup data-n=\"3649\">16</sup> ולכן בטבעו ג\"כ לרדות ולמשול כו', וא\"כ בדבר אשר שרשו כ\"כ נעלה בכח האלקי עצמו המהווה וכח האלקי הוא כח פשוט בתכלית עד שמחמת זה כולל בתוכו כל הכחות הפכיי' המתהווים ממנו כי אינם הפכי' כלל לגבי' לכן גם האדם הוא הכולל בתוכו כל ההפכי' להיותו בדוגמא עליונה ממש כו' וד\"ל. ולזה הטעם האדם הוא בעל בחירה עד שיכול למרוד באלקים חיים ח\"ו משא\"כ כל הברואים לא ישנו את תפקידם ופקודתו שמרה רוחם, והיינו מצד שכולם נבראו כ\"א ממקורו שיש לו בבחי' כח האלקי וממילא הוא בבחי' ביטול עד שאין ביכולתם לעשות איזה דבר היפוך רצון ה' (... ואפי' הקליפות הרוחניי' נבראו כך שיהיו נפרדים ואעפ\"כ מסדר את הכוכבים כו' כרצונו<sup data-n=\"3650\">17</sup>. ..), משא\"כ כח האלקי הוא הבורא את הכל וכל יכול הוא להוות את הכל מאין ליש ואין שום דבר נמנע ממנו, ולהיותו כח נעלה מאד הוא המתלבש ביותר נמוך והולבש הארה זאת והושפל מאד מאד בבחי' האדם עד שנתהווה באדם כח היכולת להיות נפרד ולמרוד באדונו ח\"ו כו' וד\"ל.",[["3642","9","<b>מיכאל. . ולכן </b>[אג: וכן]<b> נק' שר של מים</b>: ראה סה\"מ תרל\"ה ח\"א ע' קפח. [וכן צ\"ל ב] מאמרי אדה\"א הנחות תקע\"ז ע' לד. וש\"נ."],["3643","10","<b>גבריאל. . ולכן </b>[אג: וכן]<b> נק' שר של אש</b>: ראה בהערה שלפנ\"ז."],["3644","11","<b>אין מלאך. . שתי שליחות הפכים</b>: ב\"ר פ\"נ, ב. ראה מאמרי אדה\"ז תקע\"א ע' ה. שעה\"י קלא, ב ובהערה 11."],["3645","12","<b>התכללות במלאכים. . ולא מכח עצמם</b>: ראה גם אגה\"ק סי\"ד. מאמרי אדה\"א שמות ח\"ב ע' תקצג. במדבר ח\"ב ע' תשיב ואילך. ע' תשכו."],["3646","13","<b>רוהמ\"ע</b>: א: רום המעלות."],["3647","14","<b>פני ארי' להימין</b>: יחזקאל א, י."],["3648","15","<b>במאמר וספרתם לעיל </b>[אג ליתא]: לע\"ע אין ידוע לאיזה מאמר כוונתו. ראה גם לעיל מאמר ד\"ה וספרתם הד'. לקו\"ת במדבר י, א."],["3649","16","<b>מלכותך מלכות כל עולמים</b>: תהלים קמה, יג."],["3650","17","<b>מסדר. . כו' כרצונו</b>: ע\"פ ברכת ק\"ש (בתפלת ערבית)."]]],[4801940240,"<b>והנה</b> זהו יתרון מעלת האדם<sup data-n=\"3651\">18</sup> על הבהמה במה שהוא בשרשו בכח האלקי עצמו כנ\"ל המקור לכל הפרטים כו', אך אנו רואים באדם עוד ענין א' שיש בו יתרון על הבהמה מעין יתרון הנ\"ל והוא שמלבד שהוא הכולל בתוכו כל הכחות עוד זאת שכל כח וכח פרטי שבו הוא כולל כל הכחות, כמו מדת החסד בעצמה היא כלולה מגבורה עד שיוכל להלביש את חסדו בדין ועונש כמו חושך שבטו שונא בנו<sup data-n=\"3652\">19</sup> שהכאות האלו שמכה לבנו בעונש ויסורין מלובש בהם עמקות האהבה שיש לו לבנו שמחמת זה רוצה להדריכו בדרך ישרה, וכן להיפוך יש בחי' גבורה המתלבש בחסד ונקרא חסד שבגבורה כמו אם רעב שונאך האכילו לחם<sup data-n=\"3653\">20</sup>, וכן החכמה כלולה מכל הכחות מבחי' בינה כמ\"ש הבן בחכמה<sup data-n=\"3654\">21</sup> ומבחי' המדות כידוע שיש שכל מטה כלפי חסד וכן כלפי דין כו' וכן לרחם כו', והנה בחי' זאת היא באה מכח היותר נעלה שלמעלה מבחי' המל' שהוא מצד שרשו בפרצופים עליונים דעולם התיקון כו'. וביאור הדבר הנה ידוע שכמה וכמה מדריגות אלפים ורבבות עד אין שיעור נאצלו מעצמו' אא\"ס עד שבא למדריגה זאת להקרות בשם בורא מאין ליש (... כי זהו בחי' המל' סופא דכל דרגין<sup data-n=\"3655\">22</sup> נק' בשם אין והוא בחי' מקור לבחי' יש הנברא וידוע באד\"ר ובאדר\"ז רבוא רבבות מדריגות עלמין<sup data-n=\"3656\">23</sup> שנאצלו עד דאתברי פרצופא דנוק' כו' וד\"ל. ..), ועד\"ז<sup data-n=\"3657\">*24</sup> מרב המשפיע שכל לתלמיד שמוכרח לצמצם שכלו בעצמו בכמה צימצומים שונים עד שבא להתלבש בדבור שהדבור הוא התחלת מקור השפע לשכל המקבל, וכ\"ה בכל ההשתל' המקור שלהם הוא רק בחי' המל' דבר הוי', ומתחלה צ\"ל השתל' רבוא רבבות בהעלם עצמי' עד שבא לידי גילוי דבר הוי' להיות מקור לעולמות הנבראים מאין ליש, והנה בד\"כ נחלקים כל העולמות המשתלשלים בהעלם עד המל' סופא דכל דרגין הנק' דבר הוי' לג' בחי' נקודה ספי' פרצוף<sup data-n=\"3658\">24</sup>, וענין הנקודה הוא כמו טבע החסד שלא יתכלל בהיפוכו כלל, ובחי' ספי' הוא כאשר נכלל מיו\"ד והיינו כאשר החסד נכלל מגבורות ונק' גבורות שבחסד ע\"ד חושך שבטו כו' כנ\"ל, וכן הגבורה נכלל מחסד, אך אחרי התכללותם כ\"א מזולתו אזי מתקשרים ומתחברים כל הע\"ס יחד אפי' עצם החסד עם עצם הגבורה ונעשה בחי' פרצוף שזהו בחי' המעטת האור והתלבשותו בריבוי כלים ואז יכול להיות מקור לדבר הוי' המחי' ומהווה את העולמות כו'. והנה שרש נפש האדם בבחי' זאת דהשתל' שבהעלם הוא בבחי' התיקון שהוא בחי' פרצוף שהוא בחי' קשר י\"ס וכ\"א כלול מיו\"ד לכן גם בנפש האדם יש כל הכחות וכאו\"א כלול מכל הכחות כנ\"ל.",[["3651","18","<b>האדם</b>: ניתוסף ע\"פ אג."],["3652","19","<b>חושך שבטו שונא בנו</b>: משלי יג, כד."],["3653","20","<b>אם רעב שונאך האכילו לחם</b>: משלי כה, כא [ושם: האכילהו]."],["3654","21","<b>הבן בחכמה</b>: ס\"י פ\"א, מ\"ד."],["3655","22","<b>המל' סופא דכל דרגין</b>: ראה זהר בשלח נו, א. פקודי רכו, סע\"א."],["3656","23","<b>באד\"ר ובאדר\"ז רבוא רבבות מדריגות עלמין</b>: ראה גם סה\"מ תרפ\"ג ע' קפו. וש\"נ. אוה\"ת וארא ע' קצו ואילך."],["3657","*24","<b>ועד\"ז</b>: א: ועד\"ד. ג: וע\"ד דוגמא."],["3658","24","<b>נקודה ספי' פרצוף</b>: ראה ע\"ח שער הפרצופים ש\"ל, פ\"ז. שער היחוד קכד, א ובהערה 4."]]],[4801940293,"<b>והנה</b> בכל הנ\"ל הוא יתרון האדם על הבהמה, אבל יש יתרון לבהמה על האדם במה שהבהמה יש בה בחי' ביטול<sup data-n=\"3659\">25</sup> בטבע ולא תבעט אפי' בנער קטן הנוהג בה משא\"כ האדם טבע שלו לא להיות בטל לשום דבר כ\"א ע\"י הטו\"ד, ושרש הענין להיות ששרש הבהמה הגם שבהשתל' הנגלה מדבר הוי' היא נמוכה מן האדם (... כנ\"ל דשרשה במרכבה ושרש האדם הוא בבחי' המל' אדם הרוכב על הכסא כו'. ..) מ\"מ בבחי' השתל' הנעלם שלמעלה מבחי' הדבור הנק' מל' כנ\"ל שרש הבהמה היא גבוה יותר משרש נפש האדם, כי שרש נפש האדם הוא בבחי' התיקון כנ\"ל שלכן יש בו בחי' התכללות אבל שרש נפש הבהמה הוא מבחי' אורות דתהו שהמה בחי' אורות תקיפים<sup data-n=\"3660\">26</sup> מצד תוקף הביטול לעצמי' המאציל, ולכן המה בבחי' מיעוט הכלי ואינם נכללים כ\"א<sup data-n=\"3661\">27</sup> מזולתו להיות נכללים בריבוי הכלים כי כ\"ז הוא מצד תוקף האור והביטול הוא בבחי' נקודה והעדר ההתפשטות ולכן אינו יוצא לחוץ מעצמו לסבול את זולתו וליכלל עמו בכל ההתכללות ומצד<sup data-n=\"3662\">28</sup> המורכב בהתפשטות אבל כל עצם לא יוכל לסבול את זולתו כו', והנה לכן יש בבהמה בחי' ביטול בטבע מצד נפילת החיות שבה מאורות דתהו שהביטול הוא בהם בתוקף מאד ולכן כחה חזק ג\"כ מן האדם מצד שרשה באורות תקיפין, אך מצד שהאורות דתהו בחיצוני' הכלים שלהם המה בבחי' נקודה בהעדר ההתפשטות ולכן המה בחי' ענפין מתפרדין<sup data-n=\"3663\">29</sup> לכן גם למטה במרכבה דפני ארי' כו' וכן למטה בבהמות הגשמי' אין בהם ההתכללות מריבוי בחי' רק בכ\"א אין רק מדה פרטי' כנ\"ל וד\"ל.\n<b>והנה</b> יש עוד בחי' באדם שיש בו יתרון אפי' על שרש הבהמות והחיות שהוא בחי' אורות דתהו והוא מצד ההתכללות, כי אע\"פ שמבואר למעלה שבחי' התכללות שבו מצד שרשו באורות דתיקון אשר שם האורות מועטים וחלושים ולכן מתכללי' כ\"א בחבירו והפירוד דבהמות וחיות הוא מצד שרשו באורות דתהו ענפין מתפרדין ונמצא שההתכללות שבאדם אינו רק מצד חלישות האור שזהו בחי' גירעון לגבי אורות דתהו כו' (... וזהו מה שנמצא בחי' ביטול בבחי' אדם יותר מן הבהמה מצד השכל והדעת המחליש תוקף המדות וזהו בחי' רך כקנה משא\"כ מדות טבעי' המה קשים כארז<sup data-n=\"3664\">30</sup> כו' אך בחי' ביטול טבעי נמצא בבהמה יותר כנ\"ל. ..). אך הנה ידוע דקוב\"ה לא שרי' רק באתר שלים<sup data-n=\"3665\">31</sup> לכן מחמת זה נמצא פנימי' אא\"ס בתקון דוקא יותר מבאורות דתהו מחמת שהתיקון הוא בחי' אתר שלים כלול מכל ההפכים כו', והגם שהביטול הוא בתוקף יותר באורות דתהו מ\"מ הביטול הוא רק לבחי' חיצוני' דאא\"ס פי' הארה וזיו ממנו השייך להתפשטות בעולמות ולא בבחי' פנימי'",[["3659","25","<b>שהבהמה. . ביטול</b>: ראה גם לקו\"ת אמור לז, א. תו\"ח וישלח קפא, ג."],["3660","26","<b>דתהו. . אורות תקיפים</b>: ראה ע\"ח שער המלכים שי\"א, פ\"א. תו\"ח בראשית ט, א ובהערה 6."],["3661","27","<b>כ\"א</b>: כל אחד."],["3662","28","<b>בכל. . ומצד</b>: אג: כי כל. . הוא מצד."],["3663","29","<b>ענפין מתפרדין</b>: זהר ח\"ש קכג, א."],["3664","30","<b>רך כקנה. . קשים כארז</b>: ע\"פ תענית כ, סע\"א. ראה לקו\"ת אמור כאן לז, ד. מטות פז, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תשמז. וש\"נ. תו\"ח בראשית ט, א ובהערה 17. סה\"מ תר\"ל ע' ג."],["3665","31","<b>דקוב\"ה. . באתר שלים</b>: ראה זהר ויחי רטז, ב. אמור צ, ב. לקו\"ת כאן לח, רע\"א ובהנסמן במ\"מ לשם."]]],[4801940343,"ועצמו' כו' משא\"כ* בתיקון שורה מבחי' פנימי' ועצמו'<sup data-n=\"3666\">*32</sup> אא\"ס מצד שהתיקון הוא בחי' אתר שלים כו' וד\"ל.\n<b>ובזה</b> יובן ג\"כ מה שמצינו שני דברים הפכים והוא מה שהמאכל דדצ\"ח מחי' לנפש האדם ואעפ\"כ נפש האדם היא המבררת את המאכל ומעלהו לשרשו, והיינו מפני שבאדם שהוא כלול מכל הכחות והוא בבחי' אתר שלים לכן בו שורה בחי' אא\"ס שלימותא דכולא<sup data-n=\"3667\">32</sup> ולכן נמצא בו בחי' הביטול לעצמו' אא\"ס ממש אליו ולא למדותיו<sup data-n=\"3668\">33</sup> (... מלבד הביטול שנמצא בו מצד חלישת המדות מפני השכל המאיר בהם כנ\"ל בענין רך כקנה כו'. ..) וכמו למעלה בחכ' אתברירו<sup data-n=\"3669\">34</sup> מצד שבחי' פנימי' ועצמי' אא\"ס שורה בה כן באדם הביטול דחכמה כח מ\"ה<sup data-n=\"3670\">35</sup> הנמצא בו הוא כלי להשראת פנימי' ועצמי' אא\"ס ולכן הוא המברר את הכל. אך מה שנמצא באדם הגילוי פנימי' דאא\"ס הוא בדרך השראה בלבד וכנ\"ל דקוב\"ה שרי' כו', אבל מצד עצם המהות שרשו הוא למטה מן הבהמה אשר שרשה בתהו שקדם לתיקון כנ\"ל, לכן אחר שנתבררה הבהמה על ידי האדם מתעלית לשרשה וממשיך תוס' אור וחיות בנפש האדם וכמ\"ש כי לא על הלחם<sup data-n=\"3671\">36</sup> כו' כי על כל מוצא פי הוי' שבלחם יחי' האדם שזהו האור וחיות מעולם התהו שנק' מוצא פי הוי' כנ\"ל וד\"ל. ועם זה יובן ג\"כ ענין הקרבנות שמעוררים מצד שרשן אורות דתהו להיות נמשך בבחי' ריח ניחוח להוי'<sup data-n=\"3672\">37</sup> דתיקון שהוא בחי' תוס' אור ועי\"ז מכפר על נפש האדם וכן עד\"ז שולחנו של אדם מכפר<sup data-n=\"3673\">38</sup> מטעם הנ\"ל וד\"ל.\n<b>ומעתה</b> י\"ל ענין בחי' כבשי תמידין וההפרש שביניהם לכבשי עצרת כו', כי הנה יש בחי' כבש ב' קודם לשי\"ן וכשב שי\"ן קודם לב', וביאור הדברים הנה מבואר בזוהר בענין אות השי\"ן<sup data-n=\"3674\">39</sup> שלא נברא בו העולם כי אמר לו הקב\"ה טב אנת ויאות אנת וקשוט אנת אבל אתוון דזיופא נטלין לך למהוי עמהון, ביאור הענין דשי\"ן הוא בחי' ג' קוין חג\"ת שזהו בחי' טב ויאה וקשוט, טב הוא",[["3666","*32","<b>כו' משא\"כ. . ועצמו'</b>: ניתוסף ע\"פ אג."],["3667","32","<b>אא\"ס שלימותא דכולא</b>: ראה עבודת הקודש ח\"א רפ\"ח. דרך אמונה להנ\"ל מהדורת קה\"ת ע' יג ובהנסמן שם. לקו\"ת עקב טז סע\"א. הלשון שלימותא דכולא — ראה ת\"ז בהקדמה (יז, ב)."],["3668","33","<b>אליו ולא למדותיו</b>: ואתחנן ד, ז. במאמרי אדה\"ז תקס\"ג ח\"א ע' קכו: שארז\"ל בספרי. ראה פרדס שער הכוונה של\"ב, פ\"ב. מאמרי אדה\"א ויקרא ח\"א ע' נ. וש\"נ. נ\"ך ע' לד. וש\"נ."],["3669","34","<b>בחכ' אתברירו</b>: ראה זהר היכלות פקודי רנד, סע\"ב. הנסמן במאמרי אדה\"א דברים ח\"א ע' רצה. שמות ח\"ב ע' שכא. תו\"ח תשא ח\"ב שפד, ד ואילך."],["3670","35","<b>דחכמה כח מ\"ה</b>: זהר רע\"מ צו כח, א. לד, א."],["3671","36","<b>כי לא על הלחם</b>: עקב ח, ג. ראה גם לעיל ר\"ע קסג. ר\"ע קעה. פלח הרמון בשלח ע' קצב ואילך. יתרו ע' רלו. מאמרי אדה\"א הנחות תקע\"ז ע' קכא ואילך. וש\"נ."],["3672","37","<b>ריח ניחוח להוי'</b>: ויקרא א, ט."],["3673","38","<b>שולחנו של אדם מכפר</b>: ברכות נה, א. ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'שסה. וש\"נ."],["3674","39","<b>בענין אות השי\"ן</b>: ראה זהר בהקדמה ב, ב."]]],[4801940390,"מדת החסד, ויאה הוא מדת הגבורה<sup data-n=\"3675\">40</sup>, וקשוט הוא מדת אמת בחי' ת\"ת<sup data-n=\"3676\">41</sup> כמ\"ש תתן אמת ליעקב<sup data-n=\"3677\">42</sup> כו'. אך הנה ג' מדות שרשן האמיתי הוא ברצון למעלה מן החכמה ועוד יותר נעלה אפי' מן הרצון והיינו בכתרים דתהו שזהו בחי' ז' מלכין קדמאין<sup data-n=\"3678\">43</sup> כו' (... משא\"כ הרצון הוא כתר<sup data-n=\"3679\">44</sup> דתיקון. ..), ולכן לעוצם הרוממות שלהם כאשר יאיר האור מהם יוכלו החיצוני' לקבל יניקה ביתר מכפי המדה מצד העדר תפיסת מקום שלהם כידוע בענין שממית בידים תתפש<sup data-n=\"3680\">45</sup> כו', ולכן א' דאתוון דזיופא נטלין שזהו אותיות ק\"ר שהמה מקור יניקת החיצונים כידוע דאות הקו\"ף הוא חיות הקליפה והסט\"א שע\"י חיות זה מגביה את עצמה כנשר ולדמות את עצמה כקוף בפני אדם<sup data-n=\"3681\">46</sup>, וכן אות הרי\"ש הוא בחי' רע, אך חיות הקליפה אין לה קיום מצד עצמה רק ע\"י שמקבלים מאות השי\"ן שהוא אות דקדושה שמרמז על ג' קוין שהן ג' המדות חג\"ת כו', וזהו אתוון דזיופא נטלין לך למהוי עמהון לקבל יניקה ממנה כו' וד\"ל. והנה לתקן זה הענין שלא יהי' תוס' יניקה לזה הי' העובדות דיעקב אע\"ה שנאמר בו והכשבים הפריד יעקב<sup data-n=\"3682\">47</sup> היינו שהמשיך שרש המדות כמ\"ש בבחי' רוממות והתנשאות דכתר (... דתיקון או כתרים דתהו כו' שלכן יכולים הכל לקבל מצד הרוממות כנ\"ל. ..), אבל הוא המשיכם והביאם לידי גילוי למטה במדות שלמטה מן החכמה, וההמשכה זאת מהעלם אל הגילוי הי' ע\"י קו המדה דחכמה דוקא שמבדיל בין ישראל לעמים והיינו שלא יאיר האור רק בסט' דקדושה ולהם יומשך במדה ושיעור כפי הצורך לקיומם בלבד ונמצא שעשה להמשיך מבחי' כשב להיות בחי' כבש.\n<b>וביאור</b> הדברים הנה באגדה<sup data-n=\"3683\">48</sup> נאמר ויוציאנו ה' אלקינו ביד חזקה ובזרוע נטוי', הוי' אלקינו חו\"ב וביד חזקה ובזרוע נטוי' הוא חו\"ג דאריך ומבואר בכהאריז\"ל שיצי\"מ הי' מבחי' או\"א שעלו והלבישו לזרועות דאריך<sup data-n=\"3684\">49</sup>, וביאור ענין עלי' והלבשה זאת יובן ע\"ד חיות הנפש המלובש בגוף שנעשה שינוי בחיות הנפש מצד התלבשותו בגוף כידוע דהנפש מתפעלת ממאורעות הגוף<sup data-n=\"3685\">50</sup> כו', וכן יובן בענין",[["3675","40","<b>טב. . החסד ויאה. . הגבורה</b>: להעיר מזהר הרקיע שם (יא, א): יאות. . חסד וטב. . גבורה."],["3676","41","<b>אמת בחי' ת\"ת</b>: ראה גם מאמרי אדה\"א שמות ח\"א ע' כא. נ\"ך ע' כג ובהנסמן בהנ\"ל."],["3677","42","<b>תתן אמת ליעקב</b>: מיכה ז, כ."],["3678","43","<b>ז' מלכין קדמאין</b>: ראה וישלח לו, לא ואילך. זהר אד\"ר נשא קכח, א. קלה, א. ע\"ח שער הכללים פ\"א. שער דרושי נקודות ש\"ח, פ\"ד. שער שבה\"כ ש\"ט, פ\"א ואילך. לקמן מאמר ד\"ה אם בחוקותי הא' על יד הערה 40."],["3679","44","<b>הרצון הוא כתר</b>: ראה פרדס שער עצמות וכלים ש\"ד, פ\"ח. שער הצחצחות שי\"א, פ\"ה. פ\"ו. אגה\"ק סכ\"ט. מאמרי אדה\"א הנחות תקע\"ז ע' עב. וש\"נ."],["3680","45","<b>שממית בידים תתפש</b>: משלי ל, כח. ראה גם פלח הרמון שמות ע' יז. בשלח ע' קכה."],["3681","46","<b>דאות הקו\"ף. . כקוף בפני אדם</b>: ראה גם זהר הרקיע שם. מאמרי אדה\"א קונטרסים ע' תקצח. וש\"נ."],["3682","47","<b>והכשבים הפריד יעקב</b>: ויצא ל, מ."],["3683","48","<b>באגדה </b>[א: בהגדה. ג: תיקן בהגדה]: ראה הגדה של פסח עם לקוטי טעמים מנהגים וביאורים (קה\"ת מהדורת תשל\"ג ואילך) ע' ה."],["3684","49","<b>ויוציאנו. . חו\"ב. . חו\"ג. . לזרועות דאריך</b>: ראה פע\"ח שער חה\"מ שכ\"א, פ\"ז. תו\"ח בא ח\"א פט, א ובהנסמן לשם."],["3685","50","<b>דהנפש מתפעלת ממאורעות הגוף</b>: ראה תניא פמ\"ב (ס, ב). שער היחוד והאמונה פ\"ז (פג, ב). תו\"א וירא יג, ג. ועוד."]]],[4801940434,"התלבשות המדות להשכל שהמה מטים את השכל ומשנים אותו כפי רצון המדות כמו עד\"ד כי יצר לב האדם<sup data-n=\"3686\">51</sup> רע מנעוריו שמתחלה כתיב ויתעצב אל לבו<sup data-n=\"3687\">52</sup> ונטה בסברא זאת לחוב עד שהביא המבול מחמת זה ואח\"כ כשהקריב נח קרבן<sup data-n=\"3688\">53</sup> ונעשה שמחת הלב למעלה אז מסברא זאת עצמה<sup data-n=\"3689\">54</sup> נתהפך לטוב להיות כי יצר לב האדם רע בטבע אין להאשימו כ\"כ על חטאתו, נמצא שמחמת המדות שבלב שמחה ועצבות מלבישים את השכל לכן משנים אותו לפי הטייתן כו'. וכ\"ה עד\"ז כשהשכל מלביש את הרצון אז משנה אותו מכפי טבעו שאע\"פ שע\"פ הטבע הרצון יומשך לכל מ\"מ השכל מגבילו שלא יומשך רק לראוי ולא לשאינו ראוי כו', וזהו\"ע יצי\"מ שהי' מצד שאו\"א עלו והלבישו לזרועות דאריך כי מצד מדות שברצון לעוצם רוממותם יוכל פרעה מלך מצרים ג\"כ לקבל תוס' יניקה עד שיכול למשול על ישראל ועכב אותם בגלות אך מחמת או\"א שנתעלו להלביש המדות שברצון ולמשול עליהם שיאירו רק ע\"פ חכמה וע\"פ החכמה אין אא\"ס שורה אלא במי שבטל אליו<sup data-n=\"3690\">55</sup> שזהו ישראל שיש בהם הביטול דחכמה ולא לאוה\"ע ועי\"ז נתחזק כח ישראל לצאת מגלות מתחת יד פרעה ומצרים ונחלש כח פרעה שלא הי' יכול לעכב אותם תחת ידו כו' וד\"ל.\n<b>והנה</b> זהו מה שפעל יעקב הכנה לזה בעובדא שלו שזהו מה שהפריד את הכשבים פי' שהמשיך אותם בבחי' הגילוי לעלמא דפרודא<sup data-n=\"3691\">56</sup> ע\"י החכמה דוקא שזהו ע\"י עליות החכמה להלביש המדות כו' ונמצא שמה שהמדות היו מתחלה למעלה מן החכמה שזהו כשב שי\"ן קודם לבי\"ת עתה נתעלה מדריגת החכמה להלביש אותם ולמשול עליהם שלא יומשכו רק ע\"פ החכמה ונמצא שבבחי' זאת החכמה הוא למעלה מהם במה שביכולתה למשול עליהם כנ\"ל ונמצא שהב' קודם לשי\"ן וזהו בחי' כבש כו'.\n<b>ועתה</b> יובן ענין כבשי התמידין את הכבש האחד תעשה<sup data-n=\"3692\">57</sup> כו' ומבואר במ\"א דתעשה הוא בחי' יעקב<sup data-n=\"3693\">58</sup> כו' שזהו מלשון תיקון<sup data-n=\"3694\">59</sup> מל' ועשתה את צפרניה<sup data-n=\"3695\">60</sup> כו', פי' שבכ\"י שהיו מקריבים את הכבש ע\"י הכהן המקריב שמדתו ומדריגתו הוא בחי' יעקב (... מצד שהוא שליח כל ישראל<sup data-n=\"3696\">61</sup> כנ\"ל בתורה<sup data-n=\"3697\">62</sup>. ..), עי\"ז הי' פועל ג\"כ",[["3686","51","<b>כי יצר לב האדם</b>: נח ח, כא."],["3687","52","<b>ויתעצב אל לבו</b>: בראשית ו, ו."],["3688","53","<b>כשהקריב נח קרבן</b>: נח ח, כ. כא."],["3689","54","<b>מסברא זאת עצמה</b>: ראה גם לעיל ע' טו. ע' ק. ע' רה. לקמן מאמר ד\"ה רפאיני הא' על יד הערה 84. תו\"ח בראשית יד, א ובהערה 3."],["3690","55","<b>אין אא\"ס שורה אלא במי שבטל אליו</b>: ראה תניא פ\"ו."],["3691","56","<b>לעלמא דפרודא</b>: ראה זהר בראשית כב, א."],["3692","57","<b>את הכבש האחד תעשה</b>: תצוה כט, לט."],["3693","58","<b>ומבואר במ\"א </b>[ אג: במ\"ח]<b> דתעשה הוא בחי' יעקב</b>: ראה לקו\"ת כאן לח, ד: ”דאיתא במ\"ח את הכבש אחד יעקב תעשה בבקר כו'\". ובמ\"ח מסכת תפלת העשי' פ\"ד, מ\"ו: ”א\"ת הכ\"בש אח\"ד יעקב\" ראה גם מאמרי אדה\"ז תקס\"ח ח\"א כאן ע' רסג. ע' רסו ואילך."],["3694","59","<b>דתעשה. . מלשון תיקון</b>: ראה גם מאמרי אדה\"ז תקס\"ח ח\"א ע' רסז."],["3695","60","<b>ועשתה את צפרניה</b>: תצא כא, יב. ראה גם תו\"ח בשלח ח\"א קמה, ד. וש\"נ."],["3696","61","<b>הכהן. . שליח כל ישראל</b>: ראה יומא יט, סע\"א ואילך ובתוד\"ה מי איכא (ע\"ב)."],["3697","62","<b>כנ\"ל בתורה</b>: וכנראה שזהו הדרוש שנדפס בלקו\"ת אלא שנאמר בסגנון הצ\"צ וכפי שרשמו ר' הלל."]]],[4801940472,"תיקון זה להיות החכמה מלבשת ממדות<sup data-n=\"3698\">63</sup> דאריך שהם בחי' בקר דאברהם וערב דיצחק שיוכל להיות מהם יניקה לחיצוני' וע\"י הלבשת החכמה נעשה תיקון זה יומשך האור רק לישראל ובערב להמתיק הגבורות שלא יהי' הסתר לישראל כו' וד\"ל.\n<b>ומעתה</b> י\"ל ענין כבשי עצרת ותנופתם וגם תנופת הלחם ולחם על הכבשים, דהנה לפעמים א' דאו\"א מלבישים לזרועות דאריך<sup data-n=\"3699\">64</sup> ולפעמים א' דאו\"א יונקים ממזלות<sup data-n=\"3700\">65</sup>, הענין הוא דהלבשה הוא בחי' קירוב ותפיסא יותר מבחי' יניקה אך אעפ\"כ היניקה ממזלות גבוה יותר, והיא הנותנת דמחמת שהמזלות נמשכים ממקום גבוה מאד לכן א\"א להיות<sup data-n=\"3701\">*66</sup> נתפס בבחי' חו\"ב בבחי' קירוב רק בדרך יניקה מרחוק, והענין הוא דהמזלות המה מותרי מוחין מבחי' חכמה סתימאה<sup data-n=\"3702\">66</sup> וכל מותרות נמשך מצד בקיעה הבוקע מחמת תגבורת השפע שנתגברה בפנימי' עד שאין הכלי יוכל להכיל השפע בתוכה לכן בוקע בבחי' מותרות ונובלות, וכ\"ה למעלה עצם הכתר הנק' כתר שבכתר הוא למעלה מחכ\"ס הנק' חכמה שבכתר וגם בו יש ב' בחי' חיצוניות הנק' רצון ופנימי' הנק' תענוג<sup data-n=\"3703\">67</sup>, והנה כאשר יאירו שניהם בחכמה סתימאה אז לא יכיל כלי החכ\"ס ויבקע בחי' מותרות ונובלות ומזה נמשך בחי' השערות הנק' מזלות ולכן לפי שהמשכה זאת דמזלות הוא מבחי' עצם הכתר לכן לא יוכל להתקבל בבחי' קירוב ותפיסא כנ\"ל רק בחי' יניקה מרחוק. והנה מחמת שעצם הכתר יש בו ב' בחי' רצון ותענוג שזהו פנימי' וחיצוני' שבו כנ\"ל ולכן גם המזלות הנמשך ממנו נחלקים בד\"כ לשני בחי' שזהו מזל ונוצר דאבא יונק ממנו הוא נמשך מפנימי' הכתר הנק' תענוג לכן נמשך בבחי' משפיע אבל מזל ונקה הוא נמשך מבחי' חיצוני' הכתר הנק' רצון ונעשה בחי' מקבל ואימא יונק<sup data-n=\"3704\">68</sup> ממנו כידוע דכמו שאו\"א המה בחי' משפיע ומקבל כך שרשם שהם בחי' ונוצר ונקה הם בבחי' משפיע ומקבל.\n<b>וזהו</b> שרש שתי הלחם שהם מרמזים לתשב\"כ ותושבע\"פ<sup data-n=\"3705\">69</sup>, כי תורה נק' לחם<sup data-n=\"3706\">70</sup> כו' שזהו שני מדריגות דחו\"ב כי בינה הוא שרש תושבע\"פ וכ\"ה שרש הנשמות כי שרש הנש\"י ותושבע\"פ אחד הוא, וחכמה הוא שרש תושב\"כ<sup data-n=\"3707\">71</sup>, וחכמה יונק ממזל",[["3698","63","<b>ממדות</b>: אג: למדות."],["3699","64","<b>דאו\"א מלבישים לזרועות דאריך</b>: ראה ע\"ח שער או\"א שי\"ד, פ\"א. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"א לע' שנד. לעיל הערה 49."],["3700","65","<b>דאו\"א יונקים ממזלות</b>: ראה ע\"ח שער הכללים פ\"ה. שער או\"א שי\"ד, ספ\"ג. פ\"ח. אמ\"ב שער התפילין קיז, ד. וש\"נ."],["3701","*66","<b>ממזלות גבוה. . להיות</b>: ניתוסף ע\"פ אג."],["3702","66","<b>דהמזלות המה. . מבחי' חכמה סתימאה</b>: ראה גם לעיל ע' קמג. מאמרי אדה\"א דברים ח\"א ס\"ע רכו ואילך."],["3703","67","<b>חיצוניות הנק' רצון ופנימי' הנק' תענוג</b>: ראה גם מאמרי אדה\"א ויקרא ח\"א ע' רטז. תו\"ח בשלח ח\"א רב, ד. וש\"נ. לעיל ע' עז."],["3704","68","<b>מזל ונוצר דאבא יונק. . ונקה. . ואימא יונק</b>: ראה לעיל הערה 65."],["3705","69","<b>שתי הלחם. . לתשב\"כ ותושבע\"פ</b>: ראה זח\"א השמטות רס, א."],["3706","70","<b>תורה נק' לחם</b>: ראה שבת קכ, א. לקו\"ש בהעלותך כרך ד ע' 1038 הערה 26. תניא פ\"ה ובמ\"מ הגהות והע\"ק לשם. סה\"מ תרכ\"ז ע' קמט. וש\"נ."],["3707","71","<b>בינה. . תושבע\"פ. . וחכמה. . תושב\"כ</b>: ראה זח\"ב תוספות רעו, ב. תו\"ח בא ח\"א צד, ד. וש\"נ."]]],[4801940507,"השמיני ששרשו בפנימי' הכתר הנק' תענוג שזהו שרש הטעמים ונגינות השייכים לתושב\"כ כנ\"ל בתורה, ובינה יונק ממזל הי\"ג ששרשו בחיצוני' הכתר הנק' רצון שייך דוקא לנש\"י ותושבע\"פ שעל ידם מתגלה הרצון בגילוי ובדקדוק איך לעשות כידוע וכנ\"ל בתורה, וע\"י תנופת הלחם היו מניפים בחי' או\"א לשרשם בעצמי' הכתר אשר שם התענוג והרצון א' הוא (... כי מה שהתענוג והרצון<sup data-n=\"3708\">72</sup> חיצוני' או להיפך היינו בבחי' גילוי אור הכתר אבל בעצמו' הכתר המה א' ממש. ..), וזהו מה שיונקים ממזלות כי ע\"י המזלות המה יונקים משרשם שהוא בחי' עצמות הכתר ועי\"ז הי' נעשה ג\"כ תנופת הכבשים היינו עליות המדות שלמטה מן חכמה שי\"ן שאחרי הבי\"ת בבחי' שי\"ן שקודם הבי\"ת שהוא בחי' המדות שבכתר, וכ\"ז ע\"י יניקת או\"א ממזלות כי השי\"ן הוא ג\"כ בחי' שערות כי השערות המה בדוגמת יודי\"ן ווי\"ן<sup data-n=\"3709\">73</sup> שזהו ג' ווי\"ן שבשי\"ן שהמה ג\"כ בחי' יודי\"ן ווי\"ן כו' וד\"ל (ונלע\"ד<sup data-n=\"3710\">74</sup> בדרך אפשר כי יש ב' בחי' מדות בבחי' הכתר הא' בחי' חג\"ת דאריך המלובשי' באו\"א שזהו בחי' שי\"ן שקודם הב' ולאחר התלבשותם באו\"א נק' כבש שי\"ן שאחר הבי\"ת מצד שאו\"א עולים ומלבישים לזרועות הנ\"ל ונמצא שכח החכמה נחשב למע' מהם במה שמושל על המדות אע\"פ שהוא רק מלביש להם, וכאשר נמשך האור מבחי' מדות אלו במדות דז\"א בבחי' תוס' אור ע\"י החכמה דוקא זהו בחי' כבשי תמידין, אבל יש בחי' מדות שבעצמות הכתר שלמעלה מגדר הלבשה באו\"א והוא בחי' מדות דע\"י שהלבשה שלהם הוא בבחי' גולגלתא ומו\"ס שהם אינם באים בבחי' קירוב בהשתל' רק בדרך יניקה מרחוק ונמצא שנמשכים ג\"כ ע\"י השערות הנק' מזלות, אך באמת גם הארת ג\"ר דע\"י שאינם מלובשים כלל אפי' בגלגלתא ומוחא ג\"כ מאירים דרך פנימיות חכ\"ס בבחי' מזלות הנ\"ל. ועם זה יובן שרש שתי הלחם דתו' הוא הארת ג\"ר דע\"י המאירים דרך מזלות ושרש כבשי עצרת הוא בחי' המדות דז\"א שלמטה מהחכמה כאשר מתרוממים לקבל ממדות דע\"י דוקא שלמעלה אפי' משרש המדות דז\"א (... ששרשם בחג\"ת דאריך כו'. ..) וזהו ע\"י תנופת הכבשים, אך תנופת הכבשים נעשה ע\"י תנופת הלחם כנ\"ל שכאשר מאיר אור הג\"ר דע\"י שהוא בחי' גילוי עצמו' אא\"ס כמ\"ש אז ממילא מאיר שרש ההשתלשלו' כמ\"ש בעצמו' אא\"ס שזהו בחי' מדות דע\"י, וזהו המבואר בתורה שמאיר שרש ההשתל' כמ\"ש מצד עצמו' אא\"ס שהוא בחי' ההתנשאות עצמי' כידוע דבחי' ע\"י הוא בחי' המתנשא מימות עולם<sup data-n=\"3711\">75</sup> שהוא מל' דא\"ס והוא מקור האמיתי דהשתל' כידוע דמלכותך דוקא מכ\"ע וזה מתגלה ע\"י תנופת הכבשים שזהו גילוי אא\"ס למטה בהשתל' כמו למעלה בשרשם המיוחד בעצמי' אא\"ס, והתגלות זאת באה מצד התגלות שרש התורה בעצמי' אא\"ס שהוא למעלה משרש ההשתל' בעצמו' שהוא רק בחי' מדות דמל' דא\"ס כנ\"ל וד\"ל. ..).",[["3708","72","<b>שהתענוג והרצון</b>: אוצ\"ל: שהתענוג פנימי והרצון."],["3709","73","<b>השערות. . יודי\"ן ווי\"ן</b>: ראה סידור שחרית נד, ד ואילך. מאמרי אדה\"א בראשית ע' רנה. וש\"נ. קונטרסים ע' צד (מהדו\"ת)."],["3710","74","<b>(ונלע\"ד</b>: אוצ\"ל: (... ונלע\"ד."],["3711","75","<b>המתנשא מימות עולם</b>: ע\"פ ברכת יוצר."]]],[4801940120,"<b>יום ד' פ' שמות רישומי דברים</b>\n<b>שבת</b> שבתון<sup data-n=\"3712\">1</sup> הוא לכם<sup data-n=\"3713\">2</sup> ועניתם את נפשותיכם בתשעה לחודש בערב כו', ובפ' אחרי נאמר שבת שבתון היא לכם<sup data-n=\"3714\">3</sup> ועניתם את נפשותיכם חוקת עולם כו'. להבין השנויים שבפסוק זה שבפ' אמור לפסוק זה שבפ' אחרי, כי בפ' אמור נאמר שבת שבתון הוא לשון זכר ובפ' אחרי נאמר שבת שבתון היא ל' נקיבה, ועוד שבפ' אמור אמר ועניתם את נפשותיכם בתשעה לחדש כו' ובפ' אחרי נאמר ועניתם את נפשותיכם חוקת עולם ולא נאמר בתשעה, ועוד קשה ל' בתשעה והל\"ל בתשיעי דהלא אין חיוב העינוי רק בתשיעי בערב ולמחרת ביום ה'<sup data-n=\"3715\">4</sup> ולא בכל התשעה ימים כו', ועוד שבפ' אמור לא נאמר חוקת עולם ובפ' אחרי אמר חוקת עולם, ואדרבה הוי ראוי לומר להיפך דבפ' אמור מונה סדר המועדות בלבד והמועד הוא חוקת עולם להיות נוהג גם אחר החורבן משא\"כ בפ' אחרי שמדבר בעבודת יוהכ\"פ שאינו אלא בזמן הבית ולא אחר החורבן ואיך א' חוקת עולם, ועוד י\"ל מה שא' בפ' אחרי וכיפר על הקודש<sup data-n=\"3716\">5</sup> מטומאות בנ\"י ובסוף הפ' אחר פסוק דשבת שבתון הוא<sup data-n=\"3717\">6</sup> אמר וכיפר על מקדש הקדש<sup data-n=\"3718\">7</sup>, וי\"ל ענין השנוי, גם להבין מהו ענין הכפרה על הקדש וכי חטא חטא ששייך כפרה כו'.\n<b>והנה</b> להבין כל הנ\"ל יש להקדים ענין ירידת הנשמה בגוף שהיא לצורך עלי'<sup data-n=\"3719\">8</sup> וענין הירידה הוא להיות ידוע שהנשמה עצמה טהורה היא כמאמר נשמה שנתת בי טהורה היא<sup data-n=\"3720\">9</sup> וביאור ענין טהורה היינו שאין בה שום צמצום והסתר כלל להפריד ולהבדיל בינה לבחי' אלקות ולכן הוא בתכלית הביטול כמ\"ש אליהו חי הוי' אשר עמדתי לפניך<sup data-n=\"3721\">10</sup>, עמידה הוא בחי' ביטול<sup data-n=\"3722\">11</sup> בתכלית, וגם יתפרש טהורה מל' תוקף הבהירות כמו בעצם השמים לטהר<sup data-n=\"3723\">12</sup> כו', והיינו ג\"כ ענין הנ\"ל שבנשמה מאיר בה בחי' אלקות בלי שום צמצום והסתר כלל [... וזהו מה שהנשמה נק' חלק אלקה ממעל<sup data-n=\"3724\">13</sup>",[["3712","1","<b>שבת שבתון</b>: הנחת ר\"ה מדרוש כ\"ק אדמו\"ר הצ\"צ.\nמאמר הצ\"צ נדפס בלקו\"ת דרושים ליו\"כ סח, ד. וראה הנרשם במ\"מ לשם.\nעוד ע\"ד המאמר ראה לקמן ברשימת הכת\"י כאן."],["3713","2","<b>שבת שבתון הוא לכם</b>: אמור כג, לב."],["3714","3","<b>שבת שבתון היא לכם</b>: אחרי טז, לא."],["3715","4","<b>ה'</b>: העשירי."],["3716","5","<b>וכיפר על הקודש</b>: אחרי שם, טז. בלקו\"ת כאן מציין לספר עשרה מאמרות מאמר חיקור דין ח\"א פי\"ג."],["3717","6","<b>הוא</b>: כנצ\"ל: היא."],["3718","7","<b>וכיפר על מקדש הקדש</b>: וכ\"ה לקמן בהביאור על יד הערה 67 — אחרי טז, לג [ושם: את מקדש]."],["3719","8","<b>ירידת הנשמה. . לצורך עלי'</b>: ראה הנסמן באוה\"ת עקב ע' תפא."],["3720","9","<b>נשמה שנתת בי טהורה היא</b>: ברכת אלקי נשמה (ברכות ס, ב)."],["3721","10","<b>כמ\"ש אלי' חי ה' אשר עמדתי לפניך</b>: מל\"א יז, א־ יח, טו [בדילוג — ושם לפניו]. ראה מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשעו. פרשיות התורה ח\"ב ע' תשכט ובהנסמן במ\"מ לשם. שה\"א צח, ב ובהערה 14. תו\"ח בשלח קסד, ב. לקמן מאמר ד\"ה והתהלכתי תרכ\"ב קרוב לתחילתו."],["3722","11","<b>עמידה. . ביטול</b>: ראה לקו\"ת נשא כ, ג. לעיל ע' קנט ובהערה 52."],["3723","12","<b>בעצם השמים לטהר</b>: משפטים כד, י [ושם: וכעצם — ראה תו\"ח בא ח\"א קכג, ג. וש\"נ]."],["3724","13","<b>שהנשמה נק' חלק אלקה ממעל</b>: ראה איוב לא, ב. תניא רפ\"ב. תו\"ח וארא ח\"א נא, ד. וש\"נ."]]],[4801940184,"להיותה בחי' אלקות ממש בתכלית הביטול כמו הספירה ממש רק ההפרש ביניהם שהנשמה אין בה כח לברוא יש מאין ועיין במאמר איהו וחיוהי<sup data-n=\"3725\">14</sup> כו'], והנה אח\"כ א' אתה בראת כו' שנתלבשה בבחי' בריאה יש מאין והיינו בחי' נשמה דבריאה שהיא לבוש בלבד לגבי הנשמה העצמי' שיש בה בחי' צמצום והסתר על האמיתית אור האלקי [... כידוע דבחי' נשמה דבריאה הוא בחי' חוש להשיג אלקות בהשגה דווקא ובבחי' ההשגה לא יוכל להשיג בחי' אמיתית הביטול כמ\"ש כו'] ואח\"כ ירדה מעולם הבריאה לעולם היצי' ע\"י צמצום שני ונתלבשה בלבוש הנק' בחי' רוח דיצי'<sup data-n=\"3726\">15</sup>, וזהו יצרת כו' [... ובחי' רוח דיצי' הוא החוש להתפעל מן ההשגה שיש בה צמצום יותר ולכן ההתפעלות מורגשת יותר מן ההשגה כו'], ואח\"כ ירדה בבחי' צמצום שלישי מיצי' לעשי' להתלבש בבחי' נפש דעשי' ובאמצעות הנפש מתלבשת בגוף גשמי' שזהו מה שאמר נפחת כו' [... ובחי' נפש הוא פרומקייט טבעית בבחי' המעשה בלבד להיות סו\"מ וע\"ט כו'] ונמצא שזהו ענין ירידת הנשמה להסתתר בכמה לבושין עד שלא יאיר אור הביטול שבה בגוף רק בבחי' המעשה בלבד כו' אבל בחי' ירידה זאת צורך עלי' והיינו שתתעלה למעלה ממקורה ושרשה שנק' בחי' טהרה לבחי' קדושה כו', ולכן לע\"ל כאשר יהי' שלימות עליות הנשמות נאמר ואנשי קדש תהיו<sup data-n=\"3727\">16</sup> כו', וענין העלי' זאת היא ע\"י המצות וכמאמר אשר קדשנו במצותיו<sup data-n=\"3728\">17</sup> כו' ולכן כל נפש מישראל מחוייבת לקיים כל התרי\"ג<sup data-n=\"3729\">18</sup> מצות<sup data-n=\"3730\">19</sup> ואפילו מצות התלויים בכהנים רק שקיומם הוא ע\"י העיבור או גילגול והיינו שכך עלה ברצונו שלא יוכל להיות שלימות העלי' בבחי' קדש כ\"א ע\"י קיום כל התרי\"ג כו', וגם קיום כל המצות תלוי בזמן ולכן יוצרו לכל נפש כמה מחי'<sup data-n=\"3731\">20</sup> בזמן עד שיוכל להשתלם בשלימות העלי' בבחי' קדש העליון וכידוע בזהר ע\"פ ואברהם זקן בא בימים<sup data-n=\"3732\">21</sup> באינון יומין עילאין דאינון לבושין כו' וואי<sup data-n=\"3733\">22</sup> למאן שחסר לי' לבושא חדא כו' גרע לבושא כו' כי המצות כאשר מתקיימין בזמן נעשין לבושין לנשמה שע\"י לבושין הללו תעלה הנשמה לבחי' קדש העליון כו' וד\"ל.\n<b>והנה</b> מתחילה י\"ל ענין ההפרש בין טהרה לקדושה כו' [שבחי' קדושה הוא למעלה מבחי' טהרה ולכן בלוים נאמר וכה תעשה להם לטהרם<sup data-n=\"3734\">23</sup> ובכהנים שהם למעלה מלוים נאמר וקדשתו<sup data-n=\"3735\">24</sup> כו'<sup data-n=\"3736\">25</sup>, והנה בחי' טהרה וקדושה",[["3725","14","<b>במאמר איהו וחיוהי</b>: אגה\"ק ס\"כ (קל, א)."],["3726","15","<b>רוח דיצי</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"ז. לעיל ע' יג הערה 131."],["3727","16","<b>ואנשי קדש תהיו</b>: משפטים כב, ל [ושם: תהיון]. ראה גם לקמן על יד הערה 58."],["3728","17","<b>אשר קדשנו במצותיו</b>: נוסח ברכת המצות."],["3729","18","<b>כל נפש. . כל התרי\"ג מצות</b>: ראה הל' ת\"ת לאדה\"ז פ\"א, ה\"ד. תו\"ח בשלח ח\"א קעה, ד ובהערה 542."],["3730","19","<b>התרי\"ג מצות</b>: ראה מכות כג, סע\"ב. כללי המצות לר\"י גיקטיליא מערכת שש מאות [צפת תשנ\"ב ע' 208]. לקו\"ש יתרו כרך כו ס\"ע 424 ואילך. אג\"ק שלו ח\"ג ע' רג."],["3731","20","<b>מחי'</b>: אוצ\"ל: יחי'."],["3732","21","<b>ואברהם זקן בא בימים</b>: ח\"ש כד, א. ראה זהר ח\"ש קכט, א. ויחי רכד, א. מאמרי אדה\"א ויקרא ח\"ב ע' תשמט. וש\"נ. תו\"ח בשלח ח\"א קעו, א. וש\"נ."],["3733","22","<b>וואי</b>: אוצ\"ל: ווי."],["3734","23","<b>וכה תעשה להם לטהרם</b>: בהעלותך ח, ז."],["3735","24","<b>וקדשתו</b>: אמור כא, ח."],["3736","25","<b>כו'</b>: אוצ\"ל: כו']."]]],[4801940241,"הוא בחי' ממכ\"ע וסוכ\"ע<sup data-n=\"3737\">26</sup> כי בחי' ממכ\"ע היינו אור וחיות הבא בדרך התלבשות ולכן הוא מלובש בתוך כל עלמין להחיותם בבחי' או\"פ כו', וענין כל עלמין היינו ב' מיני עלמין הא' בחי' עלמין סתימין דלא אתגליין והב' בחי' עלמין דאתגליין<sup data-n=\"3738\">27</sup> ויובן מבשרי אחזה באור וחיות הנמשך מרב לתלמיד דרך הדיבור היינו שפע השכל שנתגלה ע\"י הדיבור הוא תקוע ומלובש תוך מחשבת התלמיד ומלובש בו בבחי' או\"פ כי שכל התלמיד תופס אור השכל ומגבילו והיינו לפי שנתלבש אור שכל הרב בבחי' צמצום והסתר באותיות הדיבור לכן יכול התלמיד להגביל אור שכל זה בתוכיות ופנימיות שכלו כו', וע\"ד דוגמא זאת הוא התגלות אור השכל מכח המשכיל לעצמו שהגילוי בא ג\"כ ע\"י התלבשות באותיות המחשבה להרהר ולהשכיל איזה דבר ואז אור שכלו ומחשבתו מלובש בדבר המושכל כמו כשחושב איזה בנין ומשכילו בשכלו הרי בחי' שכלו ומחשבתו מלובשים בדבר ציור הבנין המדומה במחשבתו כי<sup data-n=\"3739\">28</sup> רק שיש הפרש בין התלבשות אור וחיות המתגלה ע\"י הדיבור בדבר נבדל כמו שכל ומחשבת התלמיד שאז הדבר נבדל הוא מלובש ומסתיר על אור וחיות השופע בו ועי\"ז הוא נראה בבחי' מציאות לעצמו בבחי' נפרד ובין התלבשות אור וחיות המתגלה ע\"י אותיות המחשבה לעצמו לחשב בדבר נבדל שבחי' דבר הנבדל הוא כלול ובטל באור וחיות השופע בו בתכלית כו' [... וטעם הדברים נלע\"ד להיות כי בכל שפע המתלבש באותיות יש בזה בחי' מקיף ופנימי' אך אותיות הדיבור להיותם באים בבחי' נפרד מעצמו' המשפיע לכן הם מעלימים אור המקיף לגמרי ואינם מגלים רק הארה בעלמא בבחי' פנימי' ולכן הפנימי' נבדל מן המקיף ואינו מתייחד עמו כ\"ז<sup data-n=\"3740\">29</sup> כמו בשכל המתקבל בשכל התלמיד שאינו מקבל רק הארה בעלמא ע\"י אותיות הדיבור ועצם השכל נשאר בבחי' האותיות עצמם בבחי' העלם ומקיף כו' [אך בהעלם לכה\"פ ישנו לעצמו' השכל באותיות ולכן קאים אדעתי' דרבי'<sup data-n=\"3741\">30</sup> אח\"כ מתוך האותיות עצמם כו'], ולכן נראה שכל המקבל בבחי' נבדל לעצמו אחר גמר קבלת השפע מאת המשפיע וזהו הוראה שאפי' בעת קבלת השפע שמוכרח להיות בבחי' ביטול לאור שכל הרב אינו ביטול גמור רק בחי' ביטול היש בלבד, אבל בחי' אותיות המחשבה אינם נמשכים בבחי' נפרד חוץ מעצמו' המשפיע ולכן אינם מסתירים על עצמיות אור השכל השופע בהם בחי' מקיף ופנימי ומתייחד בהם המקיף עם הפנימי' לכן הם בטילים ונכללים באור השכל בתכלית, ולכן אנו רואים בכל מחשבה הגם שמחשב בדבר נבדל וכח מחשבתו ושכלו מלובשים בדבר נבדל ההוא ומוקפת בתוכם מ\"מ המה מקיפים ג\"כ לבחי' דבר הנבדל בשעת מעשה גופא, נמצא שכח שכלו מתגלה בדבר הנבדל ע\"י אותיות המחשבה בבחי' מקיף ופנימי ושניהם הם בגילוי גמור ומיוחדים זב\"ז לכן דבר הנבדל המתחשב הוא בטל בתכלית כו' וד\"ל].",[["3737","26","<b>ממכ\"ע וסוכ\"ע</b>: זהר רע\"מ פינחס רכה, א."],["3738","27","<b>עלמין סתימין דלא אתגליין. . דאתגליין</b>: ת\"ז בהקדמה יז, א."],["3739","28","<b>כי</b>: כנראה מיותר. או שצ\"ל: כו'."],["3740","29","<b>כ\"ז</b>: אוצ\"ל: כו'."],["3741","30","<b>קאים אדעתי' דרבי'</b>: ראה גם לעיל ע' קצד ובהערה 15."]]],[4801940294,"<b>והנמשל</b> יובן למשכיל למעלה בבחי' ממכ\"ע שהוא אור וחיות האלקי הבא בדרך התלבשות בבחי' אותיות [... שזהו ענין אורות בכלים כי הכלים הוא בחי' אותיות<sup data-n=\"3742\">31</sup> כמשי\"ת בביאור שאח\"ז כו'], שאור וחיות זה מתגלה בבחי' או\"פ בתוך כל העולמות דבי\"ע וכל העולמות מרגישים אור וחיות הזה בגילוי גמור בתוך תוכם כו' ולכן אינם מרגישים רק שאור האלקי הוא מחי' ומהוה אותם אבל מ\"מ הם מורגשים ג\"כ למציאות דבר מה [... ואפי' בעת בחי' ביטול שלהם. . . השפע שהוא בחי' רצוא שקודם השוב<sup data-n=\"3743\">32</sup> אינו ביטול גמור רק בחי' ביטול היש כו']. . . בחי' העולמות ומלאכים שמקבלים מבחי' אותיות הדיבור כמ\"ש בדבר ה' שמים נעשו<sup data-n=\"3744\">33</sup> שזהו בחי' העולמות וברוח פיו כל צבאם<sup data-n=\"3745\">34</sup> שזהו בחי' המלאכים ואור וחיות האלקי המתגלה ע\"י אותיות דבורו ית' הוא נמשך בבחי' צמצום והסתר עד שמחמת זה הם נראים למציאות בפ\"ע [ולכן נק' שפע זאת בשם דבר הוי' כי דברה תורה כלשון בנ\"א<sup data-n=\"3746\">35</sup> וכמו שלמטה הדיבור הוא נפרד מן המשפיע כו' כן למעלה השפע הנמשך בדרך צמצום והסתר עד שנראה בבחי' נפרד נק' בשם דיבור אע\"פ שבאמת אינו נפרד כי אין לך דבר חוץ ממנו<sup data-n=\"3747\">36</sup>, אבל נש\"י עלה במחשבה<sup data-n=\"3748\">37</sup> והם מקבלים חיותם והתהוותם דרך אותיות מחשבתו ית' [... שזהו בחי' פנימי' הכלים כמו שית' בביאור כו'] ואור וחיות המאיר דרך אותיות המחשבה הוא מאיר בתוקף הבהירות והגילוי ובלי צמצום והסתר כלל [כנ\"ל בב' פי' דטהורה ומחמת זה מתייחד המקיף עם הפנימי' מצד שהאותיות אינם מעלימים לאור המקיף כנ\"ל] ולכן הנשמה הגם שמלבשת לאור האלקי השופע בה ותופסת אותו בתוך תוכה מ\"מ הוא בתכלית הביטול וההתכללות באור השופע בה עד שאינה נראה למציאות בפ\"ע כלל.\n<b>וזהו</b> ב' מיני עלמין בחי' עלמין סתימין דלא אתגליין שנק' בשם עלמין סתימין מחמת שאור האלקי שופע בהם בתוקף הגילוי ולכן הם סתומים ונעלמים ואינם מתגלים למטה כמו אור הבהיר ביותר שנק' בשם חושך מצד שא\"א להסתכל בו כו' והם מקבלים מאותיות מחשבתו ית' ומבחי' זאת נמשכים בחי' הנשמות כו', אבל בחי' עלמין דאתגליין האור האלקי שופע בהם בבחי' צמצום והסתר ולכן הם מתגלים במציאות דבר מה ומתגלים למטה ולכן נק' בשם עלמין דאתגליין כו' [ובד\"כ הוא שתי בחי' יוצר אור ובורא חושך<sup data-n=\"3749\">38</sup> וכו'], וזהו ג\"כ ענין ים ויבשה כי ים",[["3742","31","<b>הכלים. . אותיות</b>: ראה גם לקו\"ת מטות פב, ג. מאמרי אדה\"א דברים ח\"א ע' ט. וש\"נ."],["3743","32","<b>השוב</b>: אולי כ\"ה בהכת\"י."],["3744","33","<b>בדבר ה' שמים נעשו</b>: תהלים לג, ו."],["3745","34","<b>וברוח פיו כל צבאם</b>: ראה גם ש\"א ח, ב ובהערה 39."],["3746","35","<b>דברה תורה כלשון בנ\"א</b>: ברכות לא, ב. ראה תו\"ח וירא צח, ב."],["3747","36","<b>ממנו</b>: אוצ\"ל: ממנו]."],["3748","37","<b>נש\"י עלה במחשבה</b>: ראה ב\"ר פ\"א, ד. שע\"ת קטו, ב. תו\"ח שמות ח\"א לב, ב ובהערה 248."],["3749","38","<b>יוצר אור ובורא חושך</b>: ישעי מה, ז. ראה פע\"ח שער הק\"ש ש\"ח, פ\"א. הנסמן בתו\"ח בשלח ח\"א קמד, ג הערה 41. סה\"מ תרכ\"ז ע' רפו. וש\"נ."]]],[4801940344,"הוא בחי' עלמא דאתכסי' שהוא בחי' כח המח' העליונה מקור כל נש\"י ונש\"י נכללים במ\"ס<sup data-n=\"3750\">43</sup> זאת בתכלית הביטול כדגים שבים המובלעים במקורם וכל חיותם הוא מבחי' מקור המהווה אותם ואין להם חיות אחר כלל, ולכן אין יכולים להפרד ממקורם ומיד כשפורשים מתים<sup data-n=\"3751\">44</sup> אבל נבראים שביבשה הגם שמתהווים מן היבשה כמאמר הכל הי' מן העפר<sup data-n=\"3752\">45</sup> וגם ניזונים ממנו כמאמר ארץ ממנו יצא לחם<sup data-n=\"3753\">46</sup> אעפ\"כ הם נראים בבחי' נפרד ויוכלו להתקיים אפילו באויר השמים כן למעלה בחי' עלמא<sup data-n=\"3754\">41</sup> דאתגליי'<sup data-n=\"3755\">39</sup> שהוא בחי' כח<sup data-n=\"3756\">42</sup> הדיבור<sup data-n=\"3757\">40</sup> העליון נק' יבשה שמשם נמשכו כל העולמות והמלאכים לכן אינם בתכלית הביטול כנשמות.\n<b>אך</b> כ\"ז הוא בחי' ממכ\"ע שהוא בא בסדר והדרגה בכל עולם לפ\"ע שבעולמות העליונים הנק' עלמין סתימין הוא מתגלה בתכליות ואח\"כ בעולמות התחתונים הנק' עלמין דאתגליין מתמעט אור התגלות שפעו במיעוט אחר מיעוט עד שבעולם העשי' מתמעט הגילוי מכל וכל וזהו בחי' טהרה שהוא ראשית הגילוי דממכ\"ע המאיר בעלמין סתימין נק' בשם טהרה להיות מאיר בהם בלי צמצום והסתר כלל כנ\"ל בב' פי' דטהורה כו', אך בחי' ב' הוא בחי' סוכ\"ע שהוא בחי' אור שאינו נמשך בדרך התלבשות באותיות כלל ולכן אינו נמצא בכל העולמות בגילוי רק בהעלם וזהו פי' ענין סובב שאין הכוונה מקיף ולמעלה<sup data-n=\"3758\">47</sup> רק שנמצא בהעלם בתוך כל העולמות בהשוואה, והטעם להיות שאין ערך לכל העולמות לגבי בחי' אור זה עד ששוין לגבי ריחוק הערך דעלמין סתימין עם ריחוק הערך דעלמין דאתגליין וכמו שנמצא בעלמין סתימין כ\"ה נמצא ממש בעלמין דאתגליין וכמו שאינו מתגלה בעלמין דאתגליין רק שנמצא בהם בהעלם כן אינו מתגלה בעלמין סתימין רק שנמצא בהם בהעלם ושניהם<sup data-n=\"3759\">48</sup> אין ערוך לגבי' בהשוואה כו', ובחי' זאת דסוכ\"ע נק' בשם קדושה ע\"ש שהוא קדוש ומובדל לגמרי מגדר העולמות כו' ואינו מאיר בהם רק בבחי' מקיף בהעלם ובהשוואה למטה כמו למעלה וד\"ל [... וזהו והקדוש בשמים ובארץ<sup data-n=\"3760\">49</sup> שהוא קדוש בתכליות לכן נמצא בשמים ובארץ בהשוואה כו'].\n<b>והנה</b> זהו ג\"כ שהמלאכים ונש\"י אומרים ג\"כ קדוש כו' הוי' צבאות<sup data-n=\"3761\">50</sup>, כי הנה אעפ\"י שאנו אומרים שאור הסובב נמצא בהעלם אין הכוונה שאינו פועל",[["3750","43","<b>במ\"ס</b>: במחשבה סתימאה."],["3751","44","<b>ומיד כשפורשים מתים</b>: ראה גם תו\"ח תולדות קנח, ב ובהערה 18."],["3752","45","<b>הכל הי' מן העפר</b>: קהלת ג, כ."],["3753","46","<b>ארץ ממנו יצא לחם</b>: איוב כח, ה [ושם: ממנה]."],["3754","41","<b>עלמא דאתכסי'. . עלמא דאתגליי'</b>: ראה זהר בראשית יח, א. ויצא (ס\"ת) קנב, א. קנח, רע\"ב. וארא כט, ב. ת\"ז בהקדמה א, סע\"א ואילך."],["3755","39","<b>ים ויבשה. . עלמא דאתכסי'. . עלמא דאתגליי'</b>: ראה לעיל ע' פב. וש\"נ."],["3756","42","<b>עלמא דאתכסי'. . המח'. . עלמא דאתגליי'. . הדיבור</b>: ראה שער היחוד והאמונה פי\"א. תו\"ח בשלח ח\"א קמג, ד. וש\"נ."],["3757","40","<b>ים ויבשה. . המח'. . כח הדיבור</b>: ראה גם לעיל ס\"ע פ. לקמן מאמר ד\"ה והתהלכתי תרט\"ו על יד הערה 40. שה\"א פד, ב. תו\"ח בשלח ח\"א קנג, סע\"ב ואילך."],["3758","47","<b>סובב שאין הכוונה מקיף ולמעלה</b>: ראה תניא פמ\"ח סז, סע\"ב ובמ\"מ הגהות והע\"ק לשם. לעיל ע' קס ובהערה 64."],["3759","48","<b>ושניהם</b>: בהכת\"י מחוק. ואולי כצ\"ל."],["3760","49","<b>והקדוש בשמים ובארץ</b>: ברכת ישתבח. ראה גם מאמרי אדה\"א שמות ח\"ב ס\"ע תכב. וש\"נ. דברים ח\"א ע' קפג. וש\"נ."],["3761","50","<b>קדוש כו' הוי' צבאות</b>: ישעי' ו, ג."]]],[4801940391,"כלל, כי אדרבה עיקר הפעולה הוא מבחי' הסובב, רק שפעולה זאת אינו מורגש בגילוי רק בהעלם, והמשכה פעולה זאת דסוכ\"ע בממכ\"ע [... כי אעפ\"י שעיקר הפעולה והתהוות הוא מבחי' הסובב מ\"מ הפעולה ע\"י אמצעית אור הממלא ולכן נק' בחי' זאת המשכת סוכ\"ע בממכ\"ע כו'] נק' בשם קדוש בוא\"ו<sup data-n=\"3762\">51</sup> כי עצם הסובב הוא נק' קדוש<sup data-n=\"3763\">52</sup> והמשכת פעולתו בממכ\"ע הוא בחי' וא\"ו שמורה על הירידה מגבוה לנמוך, וזהו ג\"פ קדוש כנגד ג' עולמות בי\"ע<sup data-n=\"3764\">53</sup> כי אע\"פ שנמשכו אור הסובב בדרך ירידה מגבוה לנמוך לפ\"ע עולם הבריאה מ\"מ אינו<sup data-n=\"3765\">54</sup> בערך עולם היצירה וצ\"ל ירידה להוות ולהחיות עולם היצירה וזהו קדוש הב' ועד\"ז מיצי' לעשי' הוא בחי' קדוש הג' וזהו ג\"פ קדוש עד שיהי' הוי' צבאות אות הוא בצבא דילי'<sup data-n=\"3766\">55</sup> שהם הנשמות ומלאכים דעלמין סתימין ועלמין דאתגליין כו' [... ואות הוא בחי' אות<sup data-n=\"3767\">56</sup> המ\"מ<sup data-n=\"3768\">57</sup> הבא בדרך בהתלבשות באותיות כו'], ונמצא שיש ב' בחי' באור הסובב הנק' בשם קדוש בוא\"ו וקדוש בלא וא\"ו כו' [... שזהו בחי' ב' מקיפים מקיף הפרטי ומקיף הכללי והוא בחי' חי' יחידה כו' וד\"ל], וזהו ענין עליית הנשמה ע\"י המצות והיינו שעולה למעלה ממקורה ושרשה בממכ\"ע שהיא בבחי' טהרה כנ\"ל ונכללת בבחי' ביטול באור עצמו' הסובב הנק' קדוש בלא וא\"ו שזהו ואנשי קדש תהיו לי<sup data-n=\"3769\">58</sup> שיהיו בחי' כלים לעצמיות אור הסובב ולכן עתידים צדיקים שיאמר לפניהם קדוש<sup data-n=\"3770\">59</sup> היינו שגילוי אור הסובב בממכ\"ע הנק' בשם קדוש יהיו הם בבחי' מקור לשפע זאת ולהשפיע ולהמשיך המשכה זאת בעולמות אבל בעצמם יהי' בחי' ביטול למעלה מבחי' זאת רק לעצמו' הסובב הנק' קדש כו' [... אבל עכשיו אומרים בעצמם קדוש וביטולם הוא רק לבחי' זאת דהמשכה סובב בממלא כו' וד\"ל].\n<b>אך</b> להבין מאין יש כח גדול כזה בבחי' המצות לרומם את הנשמה במעלה ומדריגה שאינה מערכה כלל, כי הנה יש להקדים דמה שכל המצות נק' בשם מצות המלך<sup data-n=\"3771\">60</sup> כי הנה יש הפרש בין כל מיני שפע להשפעת מדת המלוכה, כי כל מיני שפע נמשכים בבחי' פנימיות במקבל [... והיינו שעצם ההשפעה נשארת בבחי' מקיף והארה בלבד נתפס בבחי' פנימי' אבל מ\"מ ההארה נמשכת בבחי' תפיסא במהות המקבל כו'] כמו שפע שכל מרב לתלמיד שנמשכת במהות המקבל עד שנתוסף ונתרבה מהות שכלי מחמת זה אבל שפע המלוכה איננה נתפס",[["3762","51","<b>קדוש בוא\"ו</b>: ראה גם לקמן מאמר ד\"ה את שבתותי תשמרו תרי\"ב ובהערה 57."],["3763","52","<b>קדוש</b>: אוצ\"ל: קדש."],["3764","53","<b>ג\"פ קדוש. . בי\"ע</b>: ראה גם לקו\"ת כאן (סט, ב. ע, ד — באצי'). מאמרי אדה\"ז תקס\"ה ח\"א ע' רנב (נו\"ש). ע' רצב."],["3765","54","<b>אינו</b>: בהכת\"י כאן מחוק. ואולי כצ\"ל."],["3766","55","<b>אות הוא בצבא דילי'</b>: ראה חגיגה טז, רע\"א (לגי' הע\"י). תו\"ח בא ח\"א קיד, ד. וש\"נ."],["3767","56","<b>אות</b>: אוצ\"ל: אור."],["3768","57","<b>המ\"מ</b>: הממלא."],["3769","58","<b>ואנשי קדש תהיו לי</b>: בלקו\"ת כאן מציין: וע' בזהר פ' משפטים (דקכ\"א סע\"א)."],["3770","59","<b>עתידים צדיקים שיאמר לפניהם קדוש</b>: ב\"ב עה, ב. וראה גם לעיל מאמר ד\"ה וספרתם הה' על יד הערה 250."],["3771","60","<b>שכל המצות נק' בשם מצות המלך</b>: ראה אסתר ג, ג. לקו\"ת כאן סט, ג. הנסמן מאמרי אדה\"א שמות ח\"א ע' יא. נ\"ך ע' רלה. ש\"א ע' נו."]]],[4801940435,"במקבל כלל רק הארתה הוא בבחי' מקיף בלבד [... פי' שאעפ\"י שגם במדת המלוכה עצם המדה נשארת בבחי' העלם ורק הארתה בלבד נמשך למקבל ואדרבה ההארה שבמדת המלוכה היא רק הארה בעלמא שאין לה ערך כלל לעצם המדה יותר ממה שאין ערך להארת כל המדות לגבי מקור המדות עצמם כי מדת המלוכה נשארת בבחי' הרוממות בעצמי' המלך ורק שם המלך נק' על אנשי המדינה והשם אין לו ערך כלל לגבי העצם מ\"מ אפי' הארה זאת דשמו אין נתפס בבחי' פנימי' באנשי המדינה רק בבחי' מקיף עליהם בלבד והיינו שאינם מרגישים מהותו כלל רק זאת מרגישים שהוא מרומם ומנושא מהם ולכן אין בהם שום תוס' מהות משפע המלוכה עליהם רק אדרבה ביטול מהותם מכל וכל כו'], ולכן אין שום כלי להכיל הארת מדת המלוכה רק בבחי' הביטול למעלה מן הטעם ועונג לגמרי שהוא ענין קבלת עול המלך עליהם שעי\"ז מקבלים שפע מדת המלוכה בהם אבל אם הביטול עפ\"י איזה עונג וטעם אין כח להכיל הארת מדת המלוכה משא\"כ בשארי השפעות כמו שפע השכל מרב לתלמיד הנה הביטול שיש בתלמיד המקבל השכל נמשך מצד העונג יש<sup data-n=\"3772\">61</sup> לו בהשכלה לזאת מניח ומבטל א\"ע מכל וכל בשביל לשמוע השכל כו'.\n<b>והנמשל</b> יובן למשכיל למעלה בענין המשכת שפע אלקי בעולמות הנבראים בע\"ג שאין להם ערוך כלל לגבי אור אלקי הבלתי מוגבל לזאת א\"א להיות ההשפעות אור האלקי להוות ולהחיות הנבראים כ\"א בדרך רוממות והתנשאות, והיינו שעצם אור האלקי נשאר בבחי' העלם ורק הארה בעלמא ממנו מאיר בנבראים וגם הארה זאת אינה מאירה רק בבחי' מקיף על הנבראים וזהו כי נשגב שמו לבדו<sup data-n=\"3773\">62</sup> שזה עצם מדת המלוכה שהוא ג\"כ בבחי' נשגב לבדו ורק הודו שהוא הארכו<sup data-n=\"3774\">63</sup> מדת המלוכה וגם הארה זאת אינה מאירה רק בבחי' מקיף וזהו על ארץ ושמים כו', אך אין המשל דומה לנמשל כי במשל אין הארת המקיף במדת המלוכה פועל רק בחי' ביטול באנשי המדינה אבל בנמשל דמדת המלוכה למעלה הנה מהארת המדה בבחי' מקיף נעשה ג\"כ מקור להחיותם ולהוותם מאין ליש בפ\"מ כו', והנה כל המצות הם בחי' בירורים לאהפכא חשוכא לנהורא והיינו לעשות מיש לאין בכדי שיהיו נכללים כל חיות העולמות בבחי' ביטול באור האלקי המאיר ממדותיו ומלכותו ית' ולכן א\"א להיות בירור והיפוך זה כ\"א כאשר יעשה איש הישראלי את המצוה בבחי' ביטול דרך עול דווקא למעלה מן הטעם ועונג ועי\"ז נעשה חיות המתברר [בעולם ע\"י גוף המצוה ובנפש ע\"י הכפי' שלו לעשות המצוה בחי' גילוי להארת מדת מלכותו ית' כו' ולכן ג\"כ מצות ק\"ש ואהבת הגם שהשכל מחויב<sup data-n=\"3775\">64</sup> להתבונן ולאהוב מ\"מ צריך לכוין שעושה זה בדרך כפי' והכרח בכדי לקיים רצון המלך ולא מצד חיוב השכל כו' והיינו מצד שכך הוא רצון הקב\"ה לעורר נפשו בהתבוננות והתפעלות כו'.",[["3772","61","<b>יש</b>: אוצ\"ל: שיש."],["3773","62","<b>כי נשגב שמו לבדו</b>: תהלים קמח, יג."],["3774","63","<b>הארכו</b>: אוצ\"ל: הארת."],["3775","64","<b>מחויב</b>: אוצ\"ל: מחייב."]]],[4801940473,"<b>והנה</b> ידוע דמדת המלוכה שרשה בבחי' חכ\"ע ולמעלה יותר מבחי' רצה\"ע [... כידוע דאבא יסד ברתא<sup data-n=\"3776\">65</sup> וכתר עליון איהו כתר מלכות<sup data-n=\"3777\">66</sup> וזהו מראש מקדם נסוכה<sup data-n=\"3778\">67</sup> כו'], ולכן הביטול זה דהתכללות החיות במדת המלוכה ע\"י בחי' קבלת עומ\"ש מרומם את המדה עצמה לשרשה בחכמה ורצה\"ע וממילא מתעלה עמה גם כל חיות המתברר עד שרשו ברצה\"ע [כי שרש האמיתי דחיות כל העולמות הוא בבחי' רצה\"ע כמ\"ש כל אשר חפץ ה' עשה<sup data-n=\"3779\">68</sup> ], ואז ע\"י הבירורים הנ\"ל מתעלה גם הנשמה העושה את המצוה לבחי' חכמה ורצה\"ע הנק' קדש כו', וזה ענין עלית הנשמה ע\"י המצות מבחי' טהרה לבחי' קדושה שהוא בחי' חכמה ורצה\"ע שהם בחי' סובב כ\"ע, ולכן נק' המצות בשם לבושים להיותם ממשיכים אור האלקי מבחי' סוכ\"ע להיות שורה על הנשמה בגילוי אור ואז נכללו בבחי' ביטול בבחי' סוכ\"ע, ובחי' זאת נק' לבושים כמו הלבוש המקיף את האדם כן אור הנמשך ע\"י המצות נמשך בבחי' מקף בלבד על הנשמה [... אך המקיף הזה מאיר בגילוי אור ואעפ\"כ אינו נתפס בבחי' פנימי' כמ\"ש במ\"א ע\"ד דוגמא המתפעל מן תפילת הצדיק<sup data-n=\"3780\">69</sup> כו'], וזה ענין זרקא מקף כו' הולך סגולתא<sup data-n=\"3781\">70</sup> כי הנה המל' נק' זרקא<sup data-n=\"3782\">71</sup> כמבואר בזהר שהוא בחי' אבנא בקירתא<sup data-n=\"3783\">72</sup> דאזדריקת כו' שהוא בחי' עליות המל' בבחי' החכמה ורצה\"ע ועיקר עלי' זאת הוא ע\"י אותיות התפילה [והתורה] שנק' סוסים<sup data-n=\"3784\">73</sup> כי הגם שהבירור נעשה ע\"י המצוה היינו בחי' הבירור למטה להיות מיש לאין וליכלל החיות של העולם במדת מלכותו ית' אבל עליית המל' גופא זהו ע\"י אותיות התפילה [והתורה]<sup data-n=\"3785\">74</sup>, והנה ע\"י עליית המל' מתעלים נש\"י ג\"כ למעלה יותר מבחי' מדת המלוכה וזהו הולך סגולתא שהמל' שנק' זרקא מוליך עמה נש\"י הנק' עם סגולתא<sup data-n=\"3786\">75</sup> כו'.\n<b>וזהו</b> ואני כברוש רענן<sup data-n=\"3787\">76</sup> פי' שכמו שהארז הלח שקומתו גבוה מאוד אך מצד לחות שבו הוא רך ונכפף עד לארץ ואז כשמניחים איזה דבר עליו ואח\"כ ביעמוד",[["3776","65","<b>דאבא יסד ברתא</b>: ראה זהר רע\"מ פינחס רנו, ב. רמח, א. רנח, א. אגה\"ק ס\"ה. מאמרי אדה\"א דברים ח\"ב ע' שפ הערה ד\"ה מצירופי. קונטרסים ס\"ע תקמז ואילך. תו\"ח שמות ח\"א יב, א. וראה גם לקו\"ת כאן סט, ג."],["3777","66","<b>וכתר עליון איהו כתר מלכות</b>: ת\"ז בהקדמה יז, א. ראה גם לקו\"ת כאן סט, ג."],["3778","67","<b>מראש מקדם נסוכה</b>: תפלת לכה דודי. וראה גם לעיל ע' פט."],["3779","68","<b>כל אשר חפץ ה' עשה</b>: תהלים קלה, ו."],["3780","69","<b>המתפעל מן תפילת הצדיק</b>: ראה גם לעיל ע' קצו. תו\"א מקץ לג, סע\"ד. (וראה שם) נד, ג. מאמרי אדה\"א קונטרסים ע' נו (לקו\"ב)."],["3781","70","<b>זרקא. . סגולתא</b>: ראה זהר בראשית כד, א. ב. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'תסט."],["3782","71","<b>המל' נק' זרקא</b>: ראה מק\"מ לזהר שם (כד, א). אוה\"ת ח\"ש כרך ד ע' תשפג."],["3783","72","<b>אבנא בקירתא</b>: [צ\"ל: דקירטא]. זהר בראשית כד, א. רע\"מ עקב ערב, א. ת\"ז תי\"ט מא, ב. תכ\"א סא, רע\"ב. וראה גם מאמרי אדה\"ז הקצרים ע' תקעט. ענינים ע' רכו וע' רסג. לקו\"ת כאן ולקמן בהביאור (ע, ד) ובמקביליו."],["3784","73","<b>אותיו'. . סוסים</b>: ראה ת\"ז בהקדמה ח, א. מאמרי אדה\"ז תקס\"ט ע' י ובנסמן במ\"מ לשם. סה\"מ תרל\"ח ע' כד ובהערה 219."],["3785","74","[והתורה]: נקוד סגול הפוך עליו. ואולי הכוונה למחוק תיבה זו. ראה גם לקמן בהביאור הערה 51."],["3786","75","<b>נש\"י הנק' עם סגולתא</b>: ראה יתרו יט, ה. תהלים קלה, ד. זהר יתרו קכז, א. קכו, ב. לקו\"ת להאריז\"ל יתרו שם."],["3787","76","<b>ואני כברוש רענן</b>: וכ\"ה לקמן בהביאור — הושע יד, ט [ושם: אני]. ראה גם לקו\"ת כאן (ובמקביליו). אחרי כו, ב."]]],[4801940508,"על עמדו אז הוא מגביה דבר המונח עליו הגבה מאוד נעלה למעלה מראשו, כך הוא בחי' המל' אני<sup data-n=\"3788\">77</sup> שרשה גבוה בבחי' חכמה ורצה\"ע הנק' אין<sup data-n=\"3789\">78</sup> כל<sup data-n=\"3790\">79</sup> וכידוע דנעוץ תחב\"ס<sup data-n=\"3791\">80</sup> אך אח\"כ כשעולה בחי' המל' לשרשה אזי מגביה נש\"י הנכללים בה ע\"י עסק המצות הגבה מאוד נעלה ברצה\"ע למעלה מבחי' מדת המלוכה כו' וזהו סב\"ת כו' [... ואפש\"ל ענין זה דעליית נש\"י למעלה מן המל' ע\"ד המבואר בת\"א בפר' בשלח<sup data-n=\"3792\">81</sup> בביאור דלסוסתי בענין והוי' הולך לפניהם<sup data-n=\"3793\">82</sup> שבשעת יצ\"מ והי'<sup data-n=\"3794\">83</sup> בחי' המל' לפניהם שהם נמשכים אחרי המל' שזהו בעת העליי' מן הגלות דבי\"ע אבל אח\"כ עלו עד הגולגלתא למעלה מבחי' המל' ואז יקראו ראשית תבואתה<sup data-n=\"3795\">84</sup> שמשפיעים לתומ\"צ כי תכליות עליי' המל' הוא רק עד דיקנא דא\"א כו', ועד\"ז נוכל לומר שעליי' נש\"י ע\"י תומ\"צ הוא ג\"כ בד\"ז שמתחילה מתעלים ע\"י תומ\"צ שהם בחי' התפשטות רצונו וחכמתו ואח\"כ מתעלים לעצמיות רצונו וחכ' עד שמתעלים אח\"כ למעלה מן הרצון ג\"כ שהוא בחי' גולגלתא] [כי רק בשעת קי\"ס נתעלו לבחי' גולגלתא בלבד לקבל התו' אבל אחר מ\"ת ביכולתה לעלות למעלה מן הגולגלתא עד העצמי' ממש] שזהו עיקר העליי' דשבת בעצמי' התענוג הנק' רעדכ\"ר שזהו בסעודה ג'<sup data-n=\"3796\">85</sup> ואז<sup data-n=\"3797\">86</sup> נש\"י משפיעים לבחי' המל'], משא\"כ כל השבת אינו מאיר רק התגלות העונג שהוא ענין גילוי אור רצונו וחכמתו העצמי' כו' כמשי\"ת כו' וד\"ל<sup data-n=\"3798\">87</sup>.\n<b>וזהו</b> ג\"כ ענין וצדקה תרומם גוי<sup data-n=\"3799\">88</sup> שכללו' המצות נק' בשם צדקה<sup data-n=\"3800\">89</sup> והם מרוממים לנש\"י למעלה מעלה בקדש העליון כנ\"ל. והנה כתיב ושמרתם את השבת<sup data-n=\"3801\">90</sup> כי קדש היא לכם שעיקר עליית נש\"י הוא בשבת דווקא כי אז מתעלים לעצמו' החכמה ורצה\"ע כי אע\"פ שגם ע\"י התומ\"צ מתעלים בשבת<sup data-n=\"3802\">91</sup>. וביאור הענין יובן מענין קריאת שם שבת שהוא ע\"פ כי בו שבת וינפש<sup data-n=\"3803\">92</sup> עד\"מ",[["3788","77","<b>המל' אני</b>: ראה פרדס שעה\"כ שכ\"ג, פ\"א מערכת אני. פע\"ח בתחלתו. ע\"ח שער העקודים ש\"ו, פ\"ג."],["3789","78","<b>חכמה ורצה\"ע הנק' אין</b>: ראה ת\"ז רתמ\"ב."],["3790","79","<b>כל</b>: כ\"ה בהכת\"י."],["3791","80","<b>דנעוץ תחב\"ס</b>: ראה ס\"י פ\"א, מ\"ז."],["3792","81","<b>בת\"א בפר' בשלח</b>: ראה שם סה, א ד\"ה וזהו."],["3793","82","<b>וה' הולך לפניהם</b>: בשלח יג, כא."],["3794","83","<b>והי'</b>: אוצ\"ל: והוי'. וראה תו\"א שם."],["3795","84","<b>ראשית תבואתה</b>: נסמן לקמן הערה 97."],["3796","85","<b>רעדכ\"ר שזהו בסעודה ג'</b>: ראה זהר יתרו פח, ב. לקמן מאמר ד\"ה את שבתותי תשמרו תרי\"ב ובהערה 100."],["3797","86","<b>ואז</b>: אוצ\"ל: [ואז."],["3798","87","<b>וד\"ל</b>: אוצ\"ל: וד\"ל]."],["3799","88","<b>וצדקה תרומם גוי</b>: משלי יד, לד [ושם: צדקה — ראה גם לקו\"ת כאן סט, ג. מאמרי אדה\"ז תק\"ע כאן ע' קנב וע' קכח. לקמן בהביאור על יד הערה 53. ד\"ה רפאיני הא' על יד הערה 38. ד\"ה רפאיני תר\"ח על יד הערה 54. מאמרי אדה\"א בראשית ע' שצט. ויקרא ח\"ב ע' תשא. וש\"נ. במדבר ח\"ג ע' א'מז. אוה\"ת תרומה ע' א'שפ. תשא ע' א'תתלא]."],["3800","89","<b>שכללות המצות נק' בשם צדקה</b>: ראה מאמרי אדה\"א ויקרא ח\"ב ע' עדרת. וש\"נ. תו\"ח שמות ח\"א יד, א ובהערה 628."],["3801","90","<b>ושמרתם את השבת</b>: תשא לא, ד."],["3802","91","<b>התומ\"צ מתעלים בשבת</b>: ראה גם לקו\"ת כאן סט, ד. [ואולי חסר כאן. ובלקו\"ת כאן: אך גם עליית התומ\"צ של כל ששת ימי המעשה הוא ע\"י השבת]. לקמן מאמר ד\"ה את שבתותי תשמרו תקצ\"ח ובהערה 7. אוה\"ת ש\"ש כרך ה ע' ב'קיט. ע' ב'קכו."],["3803","92","<b>כי בו שבת וינפש</b>: חיבור שני כתובים, בראשית ב, ג. תשא לא, יז [ראה גם לקמן ד\"ה את שבתותי תרי\"ב הערה 16]."]]],[4801940539,"אדם השובת ונח שבא אל עצמותו כי בתחילה הי' כחות נפשו מתפשטים בעשיית המלאכה וכשגומר את המלאכה אז נכללים כל עשר כחות נפשו כאו\"א במקורו גילוי התנועה בכח התנועה וגילוי המדות בכח ומקור המדות וגילוי השכל בכח השכל, וכן הרצון והעונג כו', ועד\"ז יובן למעלה בענין ירידת המל' דאצי' בבי\"ע לברר בירורים ע\"י המצות שמלובש בה ג\"כ בחי' חכמה ורצה\"ע, וכן בכל נשמה בפרט דוגמת המל' כאשר לומדת התורה ומקיימת המצות מתלבשים בה חכמה ורצה\"ע המלובשים בתומ\"צ ועי\"ז מבררת בירורים בבחי' עולם שנה נפש ואח\"כ בגמר הבירור דכל ששת ימים נעשה בחי' שביתה ועלי' ואז מתעלים כל הנשמות בבחי' המל' דאצי' וגם המל' עולה בשרשה בבחי' חכמה ורצה\"ע וגם התומ\"צ עולין בשרשן בחכמה ורצה\"ע ועלייתן הוא לעצמו' הרצון והחכמה כו' [... והיינו ג\"כ בחי' העלי' דשבת בתענוג העליון כי ענין התענוג הוא גילוי אור עצמי' עש\"כ<sup data-n=\"3804\">93</sup> הקבועים ונטועים בעצמי' בנפש כו' וד\"ל. ובזה יובן מה שאנו אומרים בשבת קדשינו במצותיך<sup data-n=\"3805\">94</sup> כו' והלא גם בימות החול אנו אומרים אשר קדשנו במצותיו אך התומ\"צ דחול הם התפשטות הרצון וחכמה אבל בשבת מתגלה עצמי' התומ\"צ כמ\"ש בעצמי' החכמה ורצון ואז הוא עיקר העלי' דנש\"י לעצמי' הקדש ממש כו' וד\"ל]. וזהו ושמרתם את השבת כי קדש היא לכם, לכם דווקא שע\"י השבת נתעלו בעצמי' הקדש ממש כו' וד\"ל [ויתבאר בתוס' ביאור תיבת לכם ע\"פ הנ\"ל דאע\"פ דנש\"י מתעלים ע\"י המל' וע\"י התומ\"צ מ\"מ מתעלים אח\"כ למעלה מבחי' המל' וגם למעלה מן החכמה ורצון למקור התומ\"צ והיינו בעצמי' אא\"ס וע\"י עלי' זאת ממשיכים אח\"כ מבחי' עצמי' אא\"ס בתומ\"צ וגם בבחי' המל' וזהו בכל עסק התורה לשמה לשם התורה עצמה<sup data-n=\"3806\">95</sup> להמשיך אא\"ס בתוכה, וכן במצות נאמר אשר יעשה אותם האדם<sup data-n=\"3807\">96</sup> כו', וזהו קדש ישראל להוי' ראשית תבואתה<sup data-n=\"3808\">97</sup> שהם ראשית לתבואה דגלי' דתורה ורזין דאורייתא ורזי דרזין הנק' דגנך תירושך ויצהריך<sup data-n=\"3809\">98</sup> כו', ונמצא שעיקר עלי' הוא לנש\"י להיותם עולים בעצמי' למעלה מן החכמה ורצון וזהו לכם כו' וד\"ל].\n<b>אך</b> כ\"ז הוא כאשר קיים את התומ\"צ ושמר א\"ע מכל ל\"ת בתכליות אבל כאשר ביטול מ\"ע כו' שאז עושה פגם וחסרון בהמשכת בחי' קדש העליון ומכ\"ש כאשר עבר על ל\"ת שאז נזרק למרחוק מאד בסט' דמסאבא שהוא היפוך הטהרה וכמו ע\"י עשיית המצוה נזרק למעלה בקדש העליון שזהו שנאמר והיתה נפש אדוני צרורה בצרור החיים<sup data-n=\"3810\">99</sup> כן ע\"י העבירות נזרק למטה מאד בסט' דמסאבא שזהו מש\"א",[["3804","93","<b>עש\"כ</b>: עשר כחות."],["3805","94","<b>קדשינו במצותיך</b>: תפלת העמידה לשבת. ראה גם לקמן מאמר ד\"ה והתהלכתי תרכ\"ב על יד הערה 69. לקו\"ת ר\"פ בשלח. מאמרי אדה\"א שמות ח\"א ע' רה. אוה\"ת עקב ע' תריב. סה\"מ תרכ\"ט ע' קמח."],["3806","95","<b>לשמה לשם התורה עצמה</b>: ראה גם לעיל ע' קפו ובהערה 59."],["3807","96","<b>אשר יעשה אותם האדם</b>: אחרי יח, ה."],["3808","97","<b>קדש ישראל להוי' ראשית תבואתה</b>: ירמי' ב, ג."],["3809","98","<b>דגלי'. . דגנך תירושך ויצהריך</b>: ראה גם לקו\"ת כאן סט, ד. תו\"ח וארא ח\"א פב, א. וש\"נ."],["3810","99","<b>והייתה נפש אדוני צרורה בצרור החיים</b>: שמו\"א כה, כט."]]],[4801940562,"ואת נפש אויביך יקלעינה בתוך כף הקלע<sup data-n=\"3811\">100</sup> כו' ואזי אין תיקון לזה כ\"א ע\"י כה\"ג שנכנס בו יהכ\"פ לפני ולפנים בהיכל ק\"ק ששרשו למעלה מבחי' קדש העליון ועי\"ז ימלא כל הפגמים והחסרונות וגם יעביר כל הלבושים הצואים שע\"י ל\"ת כו'. וביאור הענין הנה עד\"מ גשמי' כשנהר יחרב ויבש אז אין לו תקנה להתמלאות מצד המעיין בעצמו שנמשך ממנו בתחילה רק צריך לחפור את המעיין בעומק יותר ואז נמשך המעיין ממקום עמוק ביותר ואז מתגבר ויוכל למלאות את הנהר על כל גדותיו כו'. כן יובן למעלה שכאשר נעשה פגם וחסרון בהמשכת בחי' קדש העליון שהוא בחי' סוכ\"ע אז צריכין לעורר מבחי' קה\"ק שאז בחי' עצמי' אא\"ס שלמעלה מבחי' סובב וממלא, כי הנה בחי' קדש הוא סוכ\"ע שהוא ג\"כ בגדר עלמין רק שנמצא בהם למטה כמו למעלה בהשוואה אחת אבל בחי' עצמו' אא\"ס הוא מקור האמיתי דעצמי' הסובב ועצמי' הממלא שבחי' זאת אינה בגדר עלמין כלל ולכן נק' קה\"ק שהוא למעלה מכל בחי' קדש דסובב וממלא רק הוא מקור האמיתי שלהם ולכן הוא ממלא כל החסרונות שבקדש כמשי\"ת וד\"ל. וכאשר נמשך האור מעצמי' אא\"ס אז הוא ממלא כל החסרונות והפגמים ומעביר כל הלבושים צואים, אך גם בהארה זאת הנמשכת מבחי' עצמי' אא\"ס שלמעלה מבחי' סוכ\"ע וממכ\"ע יש ג\"כ ב' בחי' בחי' מקבל ובחי' משפיע, ובחי' מקבל הוא כח ומקור כל ההשתלשלות כמ\"ש בהעלם העצמי' [... כי אמיתית מקור ההשתלשלות הוא מבחי' עצמי' אא\"ס דווקא הכל יכול וכל' הרמב\"ם מאמיתית המצאו<sup data-n=\"3812\">101</sup> נמצא כל הנמצאים כו' וד\"ל] אבל בחי' משפיע הוא בחי' העלם העצמי' ממש הנק' בחי' ואתה הוי' לבדיך<sup data-n=\"3813\">102</sup> כו'. והנה יש הפרש בהארה המאיר ביוהכ\"פ מבחי' העלם עצמי' בין כשישראל עושין רצונו ומעוררים גילוי העצמי' מלמטה למעלה שאז נמשך מבחי' הגבוה שהוא בחי' משפיע שבהעלם עצמי' ובין כשישראל אין עושין תשובה רק שמתעורר העלם העצמי' להתגלות מצד סגולת היום אז אינו מתגלה רק מבחי' מקבל שבעצמו' כו' וד\"ל.\n<b>והנה</b> בזה יובן כל הנ\"ל דהנה בפ' אמור אמר ועניתם את נפשותיכם בתשעה ולא א' בתשיעי כי אין הכוונה על עינוי גשמי' בלבד שזה אין חיוב רק בתשיעי בערב ולמחרת דווקא אבל בזה שאמר בתשעה כוונתו על עינוי הרוחני שהוא ענין התשובה להתמרמר על בחי' הרע שבתשובה<sup data-n=\"3814\">103</sup> כחות דנה\"ט שהוא בחי' חו\"ב ומדות ועי\"ז מבדיל אותם מנה\"א כו', וזהו ענין נסירה ע\"ד העבודה הנעשית בעשי\"ת כי הנה אעפ\"י שנה\"א היא רוח האדם העולה למעלה<sup data-n=\"3815\">104</sup> להיות נמשך אחרי אלקי' בבחי' טבעי' ועצמי' ורוח הבהמה יורדת למטה אך כשמתלבשים זב\"ז ע\"י רצון הוי' המפליא לעשות ומקשרם ביחד אז נעשה בהם תערובות עד שיכול להיות להוי' ולגרמי' כא', וזהו היינו כחולמים<sup data-n=\"3816\">105</sup> שכמו החולם בעת השינה שאז אין מאיר בו רק תכלית הקטנות דמוחין לכן יכול לדמות שני הפכים כא' אכן כאשר קם מן השינה אז",[["3811","100","<b>ואת נפש. . הקלע</b>: המשך הכתוב והייתה נפש אדוני."],["3812","101","<b>וכל' הרמב\"ם מאמיתית המצאו</b>: ראה רמב\"ם ריש הל' יסודי התורה."],["3813","102","<b>ואתה הוי' לבדיך</b>: ישעי' לז, כ."],["3814","103","<b>שבתשובה</b>: אוצ\"ל: שבתשעה."],["3815","104","<b>רוח האדם העולה למעלה</b>: ראה קהלת ג, כא."],["3816","105","<b>היינו כחולמים</b>: תהלים קכו, א. ראה גם תו\"א וישב כח, ג."]]],[4801940579,"נכנס בו בחי' הדעת שנמשך מצד גדלות המוחין ואז הוא מבחין ומבדיל בין שני הפכים כו', וכן ע\"ד דוגמא בחביות יין כאשר מעורבים השמרים עם היין אז אין בוחן כ\"כ טעם היין וגם בשמרים אין כ\"כ טעם השמרים רק מעורבים זב\"ז אבל כאשר החביות עומדת בשקט זמן מה אז נבדלו השמרים למטה והיין עולה למעלה ואז היין הוא בתוקף הטעם שבו והשמרים נעשו עבים וגסים מאד עד שאינם ראוים כלל לשתות, וכ\"ה בנה\"א כאשר אינו מעמיק דעתו בגדולת ה' ואז אינו מאיר בו רק קטנות המוחין אז יכול להיות בו רצון לה' ורצון לגרמי' כא' כדוגמת החלום הנ\"ל, אבל כאשר מעמיק דעתו בגדולת ה' ומכניס גדלות הדעת בקרבו אז מפריד מנשמתו האלקית כל מיני שמץ רע אפילו תכלית הדקות ואז נשאר נה\"ט למטה בבחי' שינה ואינה פועלת פעולתה ויכול נה\"א לעלות למעלה בלי שיעור [... כמו בשעת התפילה בבינונים כמבואר בלק\"א<sup data-n=\"3817\">106</sup> ], וזהו בחי' אתכפי' כו', וזהו שבש\"ע דייקא אנו אומרים דייקא סלח לנו אבינו<sup data-n=\"3818\">107</sup> כי חטאנו כי מצד גדלות הדעת המאיר אז לכן מרגיש אפילו שמץ דק מן הרע לחטא גדול משא\"כ כשאינו מאיר גדלות הדעת אז כל דרך איש זך בעיניו<sup data-n=\"3819\">108</sup> כו', ועד\"ז ג\"כ בכלל הוא בזמן עשי\"ת שאז מאיר בנש\"י בחי' גדלות המוחין ואז ננסר ונפרד כל כחות דנה\"ט מנה\"א ואז הנה\"א עולה למעלה כו', וכ\"ה למעלה נעשה בחי' נסירה היינו ע\"פ הידוע בענין כי שמש ומגן הוי' אלקים<sup data-n=\"3820\">109</sup> והנסירה היא להפריד בחי' הנרתק דשם אלקים וממילא נתגלה בחי' שמש עילאה שהוא בחי' שם הוי' [שזהו ענין הארת פנים הנמשך בעשי\"ת], וזהו ענין ועניתם את נפשותיכם בתשעה שהוא ענין התשובה להפריד הרע מכל תשעה כחות שבנה\"א שזהו ענין שכל ומדות אבל ההפרדה ברצון אינו נעשה על ידינו רק מלמעלה [כמ\"ש ומל הוי' את לבבך<sup data-n=\"3821\">110</sup> כו'], והנה ע\"י התשובה מעוררים מלמעלה בחי' משפיע שבעצמי' כי כך הוא המדה אשה מזרעת תחלה יולדת זכר<sup data-n=\"3822\">111</sup> וזהו ענין שבת שבתון הוא כי יוהכ\"פ נק' שבת שבתון שהוא בחי' עליות כל שבתות השנה כמו שהשבת הוא עליית ששת ימי החול, ולהיות שבפ' אמור מדבר כשמתעורר מצד מעה\"ת בתשובה מעומקא דליבא שזהו ענין ועניתם את נפשותיכם בתשעה כנ\"ל לכן א' שבת שבתון הוא שאז מאיר בחי' דכר שבעצמו' ולכן לא נאמר שם ג\"כ חוקת עולם בפסוק דשבת שבתון [רק מתחילה א' חוקת עולם לדורותיכם כו'] להיות שהארה זאת אינו מאיר בכל יוהכ\"פ רק כשיש כשרון מעשה התחתונים כו', אבל בפ' אחרי מדבר בגילוי אור הנמשך מצד עצם סגולת היום כי שם נאמר<sup data-n=\"3823\">112</sup> בתשעה שאז אינו מאיר רק מבחי' מקבל שבעצמו' לכן א' שבת שבתון היא ולכן א' ג\"כ חוקת עולם להיות שאור זה נמשך בתמידות בכל יוהכ\"פ גם כשאין בחי' תשובה מלמטה כו'. ועי\"ז יובן מש\"א בתחילה הפרשה וכיפר על הקודש כי שם מדבר ג\"כ כשיש תשובה מלמטה",[["3817","106","<b>נה\"ט. . שינה. . בלק\"א</b>: פי\"ג."],["3818","107","<b>שבש\"ע. . סלח לנו אבינו</b>: ראה גם לקמן מאמר ד\"ה בשברי לכם תקצ\"ט ובהערה 64."],["3819","108","<b>כל דרך איש זך בעיניו</b>: משלי טז, ב (ושם: דרכי]."],["3820","109","<b>כי שמש ומגן הוי' אלקים</b>: תהלים פד, יב. ראה שהיחוה\"א רפ\"ד. מאמרי אדה\"א דברים ח\"ב ע' ת. וש\"נ. נ\"ך ע' שצה. וש\"נ."],["3821","110","<b>ומל הוי' את לבבך</b>: נצבים ל, יח [ושם: ה\"א]."],["3822","111","<b>אשה מזרעת תחלה יולדת זכר</b>: נדה לא, א."],["3823","112","<b>שם נאמר</b>: אוצ\"ל: שם לא נאמר."]]],[4801940591,"למעלה [... ואפשר שמרומז במה שא' בזאת יבוא אהרן<sup data-n=\"3824\">113</sup> שזאת היא בחי' תשובה תתאה תשוב ה'<sup data-n=\"3825\">114</sup> תתאה לגבי' וא\"ו מלמטה למעלה כו'] שאז מעורר מבחי' יותר במה<sup data-n=\"3826\">115</sup> שהוא בחי' דכר ואז מכפר גם על הנוגע בקודש עצמו [כענין הפושעים בי בגופא דמלכא<sup data-n=\"3827\">116</sup> כו'] אבל אחרי שא' שבת שבתון היא כו' חוקת עולם, שהשמיענו ענין האור המאיר מצד עצם סגולת היום גם כשאין תשובה מלמטה אז א' וכיפר על מקדש הקדש בלבד שהוא ענין הפגם הנעשה במקדש הקדש שהוא רק בחי' הארה מקדש העליון אבל לא יוכל לכפר על הפגם הנעשה בקדש עצמיו<sup data-n=\"3828\">117</sup> אבל כשיש תשובה מלמטה אז משלים כל החסרונות והפגמים אפי' הנעשים בקדש עצמו כו' וד\"ל.",[["3824","113","<b>בזאת יבוא אהרן</b>: אחרי טז, ג."],["3825","114","<b>תשובה. . תשוב ה'</b>: ראה זהר רע\"מ נשא קכב, סע\"א. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תרצט ובהנסמן במ\"מ לשם."],["3826","115","<b>יותר במה</b>: אוצ\"ל: יותר גבוה במה."],["3827","116","<b>הפושעים בי בגופא דמלכא</b>: ישעי' סו, כד. ראה זהר יתרו פה, ב. תו\"ח תצוה ח\"ב שמג, ב. וש\"נ."],["3828","117","<b>עצמיו</b>: אוצ\"ל: עצמו."]]],[4801940121,"<b>רישומי דברים ביאור על שבת שבתון הנ\"ל</b>\n<b>להבין</b> שרשי הדברים הנ\"ל<sup data-n=\"3829\">1</sup>, הנה מתחלה י\"ל ענין נשמה שנתת בי<sup data-n=\"3830\">2</sup> טהורה היא ששרשה מבחי' טהורה וירדה ונתלבשה בבי\"ע שזהו מש\"א בראת כו' וירידה זו לצורך עליה<sup data-n=\"3831\">3</sup> לעלות לבחי' קדש העליון כו'. וביאור הענין הנה טהרה וקדושה הוא בחי' או\"כ דאצי' כי הכלים הם ג\"כ בלי מה ובחי' אלקות ממש ואינם בחי' מהות חכמה וחסד כלל רק שהם מקור להשפיע חכמה וחסד, וזהו ענין שם חכים ומבין וחסד<sup data-n=\"3832\">4</sup> שנק' כן ע\"ש שהם מקורים להשפיע חו\"ב וחסד אבל אינם ממהות חכמה וחסד לא מני' ולא דוגמתו, אך גם כל זה הוא בבחי' הכלים אבל האורות אינם במציאות חכמה וחסד כלל כי אינם אפי' בבחי' מקור להשפיע השפעה מיוחדת בפרט רק בחי' א\"ס ממש, ומה שנק' אור החכמה הוא מה שאור הא\"ס מתצמצם להאציל מציאת החסד<sup data-n=\"3833\">5</sup>, ואעפ\"כ לא יתכן לקרותו בשם מקור למקור כי באמת האור לאו מכל אינון מדות כלל<sup data-n=\"3834\">6</sup> כי הוא בחי' א\"ס ממש ומה שמאציל חכמה וחסד הוא",[["3829","1","<b>להבין שרשי הדברים הנ\"ל</b>: הנחת ר\"ה מדרוש כ\"ק אדמו\"ר הצ\"צ.\nמאמר הצ\"צ נדפס בלקו\"ת דרושים ליו\"כ ע, ג. וראה הנרשם במ\"מ לשם.\nראה עוד ע\"ד המאמר לקמן ברשימת הכת\"י כאן."],["3830","2","<b>נשמה שנתת בי</b>: ברכת אלקי נשמה (ברכות ס, ב)."],["3831","3","<b>וירידה זו לצורך עליה</b>: ראה הנסמן באוה\"ת עקב ע' תפא."],["3832","4","<b>וחסד</b>: אוצ\"ל: וחסיד."],["3833","5","<b>החסד</b>: אוצ\"ל: החכמה."],["3834","6","<b>לאו מכל אינון מדות כלל</b>: ראה ת\"ז בהקדמה יז, ב."]]]]});
